    try {
        const payload = {
            ...formData,
            inquirer: formData.inquirer.toUpperCase(), // Garante maiúsculo ao salvar
            accident_date: formData.accident_date || null,
            os_request_date: formData.os_request_date || null,
            os_followup_date: formData.os_followup_date || null,
        };

