            filterStatus === 'ALL' || 
            (filterStatus === 'SENT' && p.sent_to_inquirer) ||
            (filterStatus === 'PENDING' && !p.sent_to_inquirer);

        const matchesFraction = 
            filterFraction === 'ALL' ||
            p.fraction === filterFraction;

        return matchesSearch && matchesStatus && matchesFraction;
    })
