    fraction: '',
    vehicle_prefix: '',
    vehicle_plate: '',
    accident_date: '',
    reds_number: '',
    pav_number: '',
    inquirer: '',
    sent_to_inquirer: false,
    os_request_date: '',
    os_number: '',
