          >
            {loading ? 'Processando...' : (
                isRegistering ? <><UserPlus size={20} /> Criar Minha Conta</> : <><LogIn size={20} /> Entrar</>
            )}
          </button>
        </form>

        <div className="mt-6 pt-4 border-t border-gray-200 text-center">
            <button 
                onClick={() => {
                    setIsRegistering(!isRegistering);
                    setMessage(null);
                    setPassword('');
                    setAccessCode('');
                }}
                className="text-sm font-semibold text-pmmg-primary hover:text-[#C5A059] transition-colors"
            >
                {isRegistering 
                    ? 'Já possui uma conta? Clique para entrar.' 
                    : 'Primeiro acesso? Clique para se cadastrar.'}
            </button>
        </div>

        <div className="mt-4 text-center text-xs text-gray-400">
          Polícia Militar de Minas Gerais
        </div>
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { Lock, User, LogIn, Eye, EyeOff, UserPlus, KeyRound, ShieldAlert, BadgeHelp } from 'lucide-react';
import { supabase } from '../lib/supabase';

interface LoginScreenProps {
  onLoginSuccess?: () => void;
}

type AuthMode = 'LOGIN' | 'REGISTER' | 'RECOVERY';

export const LoginScreen: React.FC<LoginScreenProps> = () => {
  const [mode, setMode] = useState<AuthMode>('LOGIN');

  // Campos do Formulário
  const [pmNumber, setPmNumber] = useState('');
  const [fullName, setFullName] = useState('');
  const [password, setPassword] = useState('');
  const [confirmPassword, setConfirmPassword] = useState(''); // Apenas para recuperação/cadastro
  const [sectionCode, setSectionCode] = useState(''); 

  const [showPassword, setShowPassword] = useState(false);
  const [loading, setLoading] = useState(false);
  const [message, setMessage] = useState<{ text: string; type: 'error' | 'success' } | null>(null);

  // --- CONFIGURAÇÃO DE SEGURANÇA ---
  const ACCESS_CODE = 'FROTA5RPM'; 
  const DOMAIN_SUFFIX = '@frota.pmmg'; // Sufixo para criar o e-mail interno

  const shieldUrl = "https://yaoebstgiagmrvlbozny.supabase.co/storage/v1/object/sign/Logo%20PMMG/ESCUDO%20PMMG.png?token=eyJraWQiOiJzdG9yYWdlLXVybC1zaWduaW5nLWtleV9mMjgyNzE5YS0xNjI0LTRiYTUtODk3MC1jNTc3ZDIzMTQ4YjUiLCJhbGciOiJIUzI1NiJ9.eyJ1cmwiOiJMb2dvIFBNTUcvRVNDVURPIFBNTUcucG5nIiwiaWF0IjoxNzY1NDAzMzE0LCJleHAiOjIzOTYxMjMzMTR9.1uAuyEEDpwU_vmvKjnSJw0uYbcOIkB-vRpXRDU-Arss";

  // Validação de PM
  const handlePmChange = (e: React.ChangeEvent<HTMLInputElement>) => {
      // Aceita apenas números e limita a 7 caracteres
      const val = e.target.value.replace(/\D/g, '').slice(0, 7);
      setPmNumber(val);
  };

  const handleAuth = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    setMessage(null);

    // Validações Básicas
    if (pmNumber.length !== 7) {
        setMessage({ text: "O Nº PM deve conter exatamente 7 dígitos.", type: 'error' });
        setLoading(false);
        return;
    }

    const email = `${pmNumber}${DOMAIN_SUFFIX}`;

    try {
      if (mode === 'REGISTER') {
        // --- CADASTRO ---
        if (sectionCode !== ACCESS_CODE) {
            throw new Error("Código de acesso da seção incorreto.");
        }
        if (!fullName.trim()) {
            throw new Error("Informe seu nome completo.");
        }
        if (password.length < 6) {
            throw new Error("A senha deve ter no mínimo 6 caracteres.");
        }

        const { error, data } = await supabase.auth.signUp({
          email,
          password,
          options: {
              data: {
                  full_name: fullName, // Salva o nome nos metadados do usuário
                  pm_number: pmNumber
              }
          }
        });

        if (error) throw error;

        if (data.user && !data.session) {
           setMessage({ text: "Cadastro realizado! Se o login não for automático, tente entrar.", type: 'success' });
           setMode('LOGIN');
        } else {
           setMessage({ text: "Cadastro realizado com sucesso! Entrando...", type: 'success' });
        }

      } else if (mode === 'LOGIN') {
        // --- LOGIN ---
        const { error } = await supabase.auth.signInWithPassword({
          email,
          password,
        });

        if (error) throw error;

      } else if (mode === 'RECOVERY') {
        // --- RECUPERAÇÃO (Simulação de Segurança) ---
        // Nota Técnica: O Supabase não permite resetar senha de outro usuário via Client-Side sem estar logado.
        // Para um reset real sem e-mail, seria necessário uma Edge Function (Backend) com Admin Key.
        // Aqui validaremos a chave de seção para "autorizar" a tentativa, mas alertaremos a limitação técnica.

        if (sectionCode !== ACCESS_CODE) {
            throw new Error("Chave de acesso da seção incorreta.");
        }

        // Tenta enviar o e-mail de reset padrão do Supabase (caso o e-mail fake existisse, o que não ocorre)
        // Como estamos usando e-mails fictícios (@frota.pmmg), o reset via link não chegará a lugar nenhum.

        // WORKAROUND UX:
        setMessage({ 
            text: "Validação OK. Porém, por segurança, o reset de senha sem e-mail requer contato com o Administrador do Sistema para exclusão da conta antiga.", 
            type: 'error' 
        });
      }
    } catch (error: any) {
      let errorMsg = error.message;
      if (errorMsg.includes("Invalid login credentials")) errorMsg = "Nº PM ou senha incorretos.";
      if (errorMsg.includes("User already registered")) errorMsg = "Este Nº PM já está cadastrado.";

      setMessage({ text: errorMsg, type: 'error' });
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="min-h-screen bg-[#958458] flex items-center justify-center p-4">
      <div className="bg-[#fdfbf7] p-8 rounded-lg shadow-2xl w-full max-w-md border-t-4 border-pmmg-primary">

        <div className="flex flex-col items-center mb-6">
          <img 
            src={shieldUrl} 
            alt="Brasão PMMG" 
            className="h-24 mb-4 drop-shadow-md"
            style={{ height: '6rem' }}
          />
          <h1 className="text-2xl font-bold text-pmmg-primary text-center">Controles Frota 5ª RPM</h1>
          <p className="text-gray-500 text-sm mt-1 uppercase font-bold tracking-wider">
            {mode === 'REGISTER' && 'Novo Cadastro de Militar'}
            {mode === 'LOGIN' && 'Acesso ao Sistema'}
            {mode === 'RECOVERY' && 'Recuperação de Acesso'}
          </p>
        </div>

        <form onSubmit={handleAuth} className="space-y-4">

          {/* Campo Nº PM (Comum a todos) */}
          <div>
            <label className="block text-sm font-bold text-gray-700 mb-1">Nº PM (7 Dígitos)</label>
            <div className="relative">
              <User className="absolute left-3 top-2.5 h-5 w-5 text-gray-400" />
              <input
                type="text"
                required
                maxLength={7}
                className="w-full pl-10 pr-4 py-2 border rounded-md focus:ring-2 focus:ring-pmmg-primary outline-none tracking-widest font-mono"
                placeholder="Ex: 1234567"
                value={pmNumber}
                onChange={handlePmChange}
              />
            </div>
          </div>

          {/* Campo Nome Completo (Apenas Cadastro) */}
          {mode === 'REGISTER' && (
             <div className="animate-fade-in">
                <label className="block text-sm font-bold text-gray-700 mb-1">Nome Completo</label>
                <input
                    type="text"
                    required
                    className="w-full px-4 py-2 border rounded-md focus:ring-2 focus:ring-pmmg-primary outline-none"
                    placeholder="Ex: Sd Fulano de Tal"
                    value={fullName}
                    onChange={(e) => setFullName(e.target.value)}
                />
             </div>
          )}

          {/* Campo Senha (Login, Cadastro e "Nova Senha" no Recovery) */}
          <div>
            <label className="block text-sm font-bold text-gray-700 mb-1">
                {mode === 'RECOVERY' ? 'Nova Senha Desejada' : 'Senha'}
            </label>
            <div className="relative">
              <Lock className="absolute left-3 top-2.5 h-5 w-5 text-gray-400" />
              <input
                type={showPassword ? "text" : "password"}
                required
                minLength={6}
                className="w-full pl-10 pr-10 py-2 border rounded-md focus:ring-2 focus:ring-pmmg-primary outline-none"
                placeholder="Mínimo 6 caracteres"
                value={password}
                onChange={(e) => setPassword(e.target.value)}
              />
              <button
                type="button"
                onClick={() => setShowPassword(!showPassword)}
                className="absolute right-3 top-2.5 text-gray-400 hover:text-gray-600 focus:outline-none"
              >
                {showPassword ? <EyeOff size={20} /> : <Eye size={20} />}
              </button>
            </div>
          </div>

          {/* Código de Seção (Cadastro e Recuperação) */}
          {(mode === 'REGISTER' || mode === 'RECOVERY') && (
            <div className="bg-yellow-50 p-3 rounded border border-yellow-200 animate-fade-in">
                <label className="block text-sm font-bold text-yellow-800 mb-1">
                    {mode === 'RECOVERY' ? 'Chave de Acesso da Seção (Para Reset)' : 'Código de Acesso da Seção'}
                </label>
                <div className="relative">
                <KeyRound className="absolute left-3 top-2.5 h-5 w-5 text-yellow-600" />
                <input
                    type="text"
                    required
                    className="w-full pl-10 pr-4 py-2 border border-yellow-300 rounded-md focus:ring-2 focus:ring-pmmg-accent outline-none bg-white text-gray-800 placeholder-gray-400 uppercase"
                    placeholder="FROTA..."
                    value={sectionCode}
                    onChange={(e) => setSectionCode(e.target.value.toUpperCase())}
                />
                </div>
            </div>
          )}

          {message && (
            <div className={`p-3 rounded text-sm text-center border font-semibold ${
                message.type === 'error' ? 'bg-red-50 text-red-700 border-red-200' : 'bg-green-50 text-green-700 border-green-200'
            }`}>
              {message.text}
            </div>
          )}

          <button
            type="submit"
            disabled={loading}
            className={`w-full text-white font-bold py-3 rounded-md transition-colors flex items-center justify-center gap-2 shadow-lg ${
                loading ? 'bg-gray-400 cursor-not-allowed' : 'bg-pmmg-primary hover:bg-[#3E3223]/90'
            }`}
          >
            {loading ? 'Processando...' : (
                mode === 'REGISTER' ? <><UserPlus size={20} /> Criar Conta</> : 
                mode === 'RECOVERY' ? <><ShieldAlert size={20} /> Tentar Resetar</> :
                <><LogIn size={20} /> Entrar</>
            )}
          </button>
        </form>

        <div className="mt-6 pt-4 border-t border-gray-200 flex flex-col gap-2 text-center">
            {mode === 'LOGIN' && (
                <>
                    <button 
                        onClick={() => { setMode('REGISTER'); setMessage(null); setPassword(''); setPmNumber(''); }}
                        className="text-sm font-semibold text-pmmg-primary hover:text-[#C5A059] transition-colors"
                    >
                        Primeiro acesso? Cadastre-se aqui.
                    </button>
                    <button 
                        onClick={() => { setMode('RECOVERY'); setMessage(null); setPassword(''); setPmNumber(''); }}
                        className="text-xs text-gray-500 hover:text-red-600 transition-colors flex items-center justify-center gap-1"
                    >
                        <BadgeHelp size={14} /> Esqueci minha senha
                    </button>
                </>
            )}

            {(mode === 'REGISTER' || mode === 'RECOVERY') && (
                <button 
                    onClick={() => { setMode('LOGIN'); setMessage(null); setPassword(''); }}
                    className="text-sm font-semibold text-gray-600 hover:text-pmmg-primary transition-colors"
                >
                    Voltar para o Login
                </button>
            )}
        </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { Package, Truck, History, LogOut, Home, KeyRound, UserCircle } from 'lucide-react';
import { InventoryTab } from './components/InventoryTab';
import { MovementsTab } from './components/MovementsTab';
import { FleetTab } from './components/FleetTab';
import { checkConnection, supabase } from './lib/supabase';
import { DatabaseSetup } from './components/DatabaseSetup';
import { LoginScreen } from './components/LoginScreen';
import { DashboardSelection } from './components/DashboardSelection';
import { PavModule } from './components/PavModule';
import { Tab } from './types';

// Tipos de módulo disponíveis
type ModuleType = 'STOCK' | 'PAV' | null;

function App() {
  const [activeTab, setActiveTab] = useState<Tab>('inventory');
  const [currentModule, setCurrentModule] = useState<ModuleType>(null);
  const [isConnected, setIsConnected] = useState<boolean | null>(null);

  // Estados de Autenticação
  const [session, setSession] = useState<any>(null);
  const [authLoading, setAuthLoading] = useState(true);

  // Estado Modal Alterar Senha
  const [isPasswordModalOpen, setIsPasswordModalOpen] = useState(false);
  const [newPassword, setNewPassword] = useState('');
  const [passwordMsg, setPasswordMsg] = useState<{text: string, type: 'success'|'error'} | null>(null);

  useEffect(() => {
    // 1. Verificar conexão com banco
    checkConnection().then(setIsConnected);

    // 2. Verificar Sessão Supabase
    supabase.auth.getSession().then(({ data: { session } }) => {
      setSession(session);
      setAuthLoading(false);
    });

    // 3. Ouvir mudanças na autenticação Supabase
    const { data: { subscription } } = supabase.auth.onAuthStateChange((_event, session) => {
      setSession(session);
      setAuthLoading(false);
    });

    return () => subscription.unsubscribe();
  }, []);

  // Função Unificada de Logout
  const handleLogout = async () => {
    await supabase.auth.signOut();
    setSession(null);
    setCurrentModule(null);
  };

  const handleChangePassword = async () => {
    if (newPassword.length < 6) {
        setPasswordMsg({ text: "A senha deve ter no mínimo 6 caracteres.", type: 'error' });
        return;
    }

    try {
        const { error } = await supabase.auth.updateUser({ password: newPassword });
        if (error) throw error;
        setPasswordMsg({ text: "Senha alterada com sucesso!", type: 'success' });
        setTimeout(() => {
            setIsPasswordModalOpen(false);
            setNewPassword('');
            setPasswordMsg(null);
        }, 1500);
    } catch (err: any) {
        setPasswordMsg({ text: "Erro ao alterar senha: " + err.message, type: 'error' });
    }
  };

  // ----- RENDERING FLOW -----

  // 1. Tela de Carregamento
  if (authLoading) {
     return (
        <div className="min-h-screen bg-[#958458] flex items-center justify-center">
            <div className="text-white font-bold text-xl animate-pulse">Carregando sistema...</div>
        </div>
     );
  }

  // 2. Tela de Login (Se não tiver sessão Supabase)
  if (!session) {
    return <LoginScreen />;
  }

  // 3. Configuração de Banco (apenas se conectado e houver erro de conexão com tabelas)
  if (isConnected === false) {
    return <DatabaseSetup />;
  }

  // Recupera nome dos metadados ou usa o email
  const userFullName = session?.user?.user_metadata?.full_name || 'Militar';
  const userEmail = session?.user?.email || '';

  // 4. Tela de Seleção de Módulo (Dashboard)
  if (!currentModule) {
    return (
      <DashboardSelection 
        onSelectModule={setCurrentModule} 
        userEmail={userFullName}
        onLogout={handleLogout}
      />
    );
  }

  // 5. Módulo PAV
  if (currentModule === 'PAV') {
    return (
      <PavModule 
        onBack={() => setCurrentModule(null)} 
        userEmail={userFullName}
        onLogout={handleLogout}
      />
    );
  }

  // 6. Módulo ESTOQUE (Aplicação original)
  const shieldUrl = "https://yaoebstgiagmrvlbozny.supabase.co/storage/v1/object/sign/Logo%20PMMG/ESCUDO%20PMMG.png?token=eyJraWQiOiJzdG9yYWdlLXVybC1zaWduaW5nLWtleV9mMjgyNzE5YS0xNjI0LTRiYTUtODk3MC1jNTc3ZDIzMTQ4YjUiLCJhbGciOiJIUzI1NiJ9.eyJ1cmwiOiJMb2dvIFBNTUcvRVNDVURPIFBNTUcucG5nIiwiaWF0IjoxNzY1NDAzMzE0LCJleHAiOjIzOTYxMjMzMTR9.1uAuyEEDpwU_vmvKjnSJw0uYbcOIkB-vRpXRDU-Arss";

  return (
    <div className="min-h-screen bg-[#958458] font-sans flex flex-col">
      {/* Header */}
      <header className="bg-[#3E3223] shadow-lg sticky top-0 z-40 border-b-4 border-[#C5A059]">
        <div className="container mx-auto px-4 h-32 flex items-center justify-between">

          {/* Lado Esquerdo: Escudo e Botão Voltar */}
          <div className="flex items-center gap-4 py-2">
            <button 
              onClick={() => setCurrentModule(null)}
              className="hidden md:flex flex-col items-center justify-center text-[#C5A059] hover:text-white transition-colors bg-white/5 hover:bg-white/10 p-2 rounded-lg"
              title="Voltar ao Menu Principal"
            >
               <Home size={20} />
               <span className="text-[10px] uppercase font-bold mt-1">Menu</span>
            </button>
            <img 
              src={shieldUrl} 
              alt="Escudo PMMG" 
              className="h-28 drop-shadow-xl filter brightness-110"
              style={{ height: '7rem' }}
            />
          </div>

          {/* Lado Direito: Título e Saudação */}
          <div className="text-right flex flex-col items-end">
            <h1 className="text-3xl md:text-4xl font-extrabold tracking-tight text-[#C5A059] drop-shadow-md shadow-black/50 font-serif uppercase">
              CONTROLE DE ESTOQUE
            </h1>
            <p className="text-lg font-bold text-[#C5A059] opacity-90 tracking-widest font-serif mb-1">
              FROTA 5ª RPM
            </p>

            <div className="flex items-center gap-3 bg-black/20 px-3 py-1 rounded-full mt-1 border border-white/10">
                <span className="text-sm font-semibold text-white/90 flex items-center gap-2">
                   <UserCircle size={16} className="text-[#C5A059]" /> 
                   Bem-vindo, {userFullName}
                </span>
                <button 
                    onClick={() => setIsPasswordModalOpen(true)}
                    className="text-[#C5A059] hover:text-white transition-colors p-1 hover:bg-white/10 rounded-full"
                    title="Alterar Senha"
                >
                    <KeyRound size={14} />
                </button>
            </div>
          </div>
        </div>

        {/* Navigation Tabs & Logout */}
        <div className="bg-[#4A3B2A]/90 backdrop-blur-sm text-white/90">
          <div className="container mx-auto px-4 flex justify-between items-center overflow-x-auto">
            <div className="flex gap-1">
              {/* Botão Menu Mobile (aparece só em telas pequenas) */}
              <button 
                onClick={() => setCurrentModule(null)}
                className="md:hidden flex items-center gap-2 px-4 py-3 border-b-4 border-transparent text-white/70 hover:text-white hover:bg-white/5"
              >
                 <Home size={18} />
              </button>

              {/* 1. ESTOQUE */}
              <button
                  onClick={() => setActiveTab('inventory')}
                  className={`flex items-center gap-2 px-6 py-3 border-b-4 transition-all whitespace-nowrap font-bold uppercase tracking-wider text-sm ${
                    activeTab === 'inventory' 
                    ? 'border-[#C5A059] text-[#C5A059] bg-black/20' 
                    : 'border-transparent hover:bg-white/5 text-white/70 hover:text-white'
                  }`}
              >
                <Package size={18} /> Estoque
              </button>

              {/* 2. MOVIMENTAÇÕES */}
              <button
                  onClick={() => setActiveTab('movements')}
                  className={`flex items-center gap-2 px-6 py-3 border-b-4 transition-all whitespace-nowrap font-bold uppercase tracking-wider text-sm ${
                    activeTab === 'movements' 
                    ? 'border-[#C5A059] text-[#C5A059] bg-black/20' 
                    : 'border-transparent hover:bg-white/5 text-white/70 hover:text-white'
                  }`}
              >
                <History size={18} /> Movimentações
              </button>

              {/* 3. MAPA CARGA */}
              <button
                  onClick={() => setActiveTab('fleet')}
                  className={`flex items-center gap-2 px-6 py-3 border-b-4 transition-all whitespace-nowrap font-bold uppercase tracking-wider text-sm ${
                    activeTab === 'fleet' 
                    ? 'border-[#C5A059] text-[#C5A059] bg-black/20' 
                    : 'border-transparent hover:bg-white/5 text-white/70 hover:text-white'
                  }`}
              >
                <Truck size={18} /> Mapa Carga
              </button>
            </div>

            {/* Botão Sair */}
            <button 
              onClick={handleLogout}
              className="flex items-center gap-2 px-4 py-2 text-red-200 hover:text-red-100 hover:bg-red-900/30 rounded transition-colors text-sm font-semibold ml-4 whitespace-nowrap"
              title="Sair do sistema"
            >
              <LogOut size={18} /> <span className="hidden sm:inline">Sair</span>
            </button>
          </div>
        </div>
      </header>

      {/* MODAL ALTERAR SENHA */}
      {isPasswordModalOpen && (
          <div className="fixed inset-0 bg-black/70 backdrop-blur-sm flex items-center justify-center z-[80]">
              <div className="bg-white p-6 rounded-lg shadow-2xl w-full max-w-sm border-t-4 border-[#C5A059]">
                  <h3 className="text-lg font-bold text-[#3E3223] mb-4 flex items-center gap-2">
                      <KeyRound size={20} className="text-[#C5A059]" />
                      Alterar Minha Senha
                  </h3>

                  <div className="space-y-4">
                      <div>
                          <label className="block text-sm font-bold text-gray-700 mb-1">Nova Senha</label>
                          <input 
                              type="password"
                              className="w-full border p-2 rounded focus:ring-2 focus:ring-[#C5A059] outline-none"
                              placeholder="Mínimo 6 caracteres"
                              value={newPassword}
                              onChange={e => setNewPassword(e.target.value)}
                          />
                      </div>

                      {passwordMsg && (
                          <div className={`text-sm p-2 rounded ${
                              passwordMsg.type === 'success' ? 'bg-green-100 text-green-800' : 'bg-red-100 text-red-800'
                          }`}>
                              {passwordMsg.text}
                          </div>
                      )}

                      <div className="flex justify-end gap-2 pt-2">
                          <button 
                              onClick={() => { setIsPasswordModalOpen(false); setNewPassword(''); setPasswordMsg(null); }}
                              className="px-4 py-2 text-gray-600 hover:bg-gray-100 rounded"
                          >
                              Cancelar
                          </button>
                          <button 
                              onClick={handleChangePassword}
                              className="px-4 py-2 bg-[#3E3223] text-white rounded hover:bg-[#2a2218]"
                          >
                              Salvar Senha
                          </button>
                      </div>
                  </div>
              </div>
          </div>
      )}

      {/* Main Content */}
      <main className="container mx-auto px-4 py-8 flex-grow">
        <div className="bg-[#fdfbf7] rounded-xl shadow-2xl border border-[#d4c5a3] min-h-[500px] p-1">
          {isConnected === null ? (
            <div className="flex items-center justify-center h-64 text-gray-500 font-semibold">
              Conectando ao banco de dados...
            </div>
          ) : (
            <div className="p-4 md:p-6">
              {activeTab === 'inventory' && <InventoryTab />}
              {activeTab === 'movements' && <MovementsTab />}
              {activeTab === 'fleet' && <FleetTab />}
            </div>
          )}
        </div>
      </main>
    </div>
  );
}

export default App;

import React, { useState } from 'react';
import { Lock, User, LogIn, Eye, EyeOff, UserPlus, KeyRound, ShieldAlert, BadgeHelp, Mail } from 'lucide-react';
import { supabase } from '../lib/supabase';

interface LoginScreenProps {
  onLoginSuccess?: () => void;
}

type AuthMode = 'LOGIN' | 'REGISTER' | 'RECOVERY';

export const LoginScreen: React.FC<LoginScreenProps> = () => {
  const [mode, setMode] = useState<AuthMode>('LOGIN');

  // Campos do Formulário
  const [pmNumber, setPmNumber] = useState('');
  const [fullName, setFullName] = useState('');
  const [personalEmail, setPersonalEmail] = useState('');
  const [password, setPassword] = useState('');
  const [sectionCode, setSectionCode] = useState(''); 

  const [showPassword, setShowPassword] = useState(false);
  const [loading, setLoading] = useState(false);
  const [message, setMessage] = useState<{ text: string; type: 'error' | 'success' } | null>(null);

  // --- CONFIGURAÇÃO DE SEGURANÇA ---
  const ACCESS_CODE = 'FROTA5RPM'; 
  const DOMAIN_SUFFIX = '@frota.pmmg'; // Sufixo interno para autenticação

  const shieldUrl = "https://yaoebstgiagmrvlbozny.supabase.co/storage/v1/object/sign/Logo%20PMMG/ESCUDO%20PMMG.png?token=eyJraWQiOiJzdG9yYWdlLXVybC1zaWduaW5nLWtleV9mMjgyNzE5YS0xNjI0LTRiYTUtODk3MC1jNTc3ZDIzMTQ4YjUiLCJhbGciOiJIUzI1NiJ9.eyJ1cmwiOiJMb2dvIFBNTUcvRVNDVURPIFBNTUcucG5nIiwiaWF0IjoxNzY1NDAzMzE0LCJleHAiOjIzOTYxMjMzMTR9.1uAuyEEDpwU_vmvKjnSJw0uYbcOIkB-vRpXRDU-Arss";

  // Validação de PM (apenas números, max 7)
  const handlePmChange = (e: React.ChangeEvent<HTMLInputElement>) => {
      const val = e.target.value.replace(/\D/g, '').slice(0, 7);
      setPmNumber(val);
  };

  const handleAuth = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    setMessage(null);

    // Validações Básicas
    if (pmNumber.length < 3) {
        setMessage({ text: "Nº PM inválido.", type: 'error' });
        setLoading(false);
        return;
    }

    // E-mail de sistema para autenticação (invisível ao usuário)
    const systemEmail = `${pmNumber}${DOMAIN_SUFFIX}`;

    try {
      if (mode === 'REGISTER') {
        // --- CADASTRO ---
        if (sectionCode !== ACCESS_CODE) {
            throw new Error("Código de acesso da seção incorreto.");
        }
        if (!fullName.trim()) throw new Error("Informe seu nome completo.");
        if (!personalEmail.trim() || !personalEmail.includes('@')) throw new Error("Informe um e-mail pessoal válido.");
        if (password.length < 6) throw new Error("A senha deve ter no mínimo 6 caracteres.");

        const { error, data } = await supabase.auth.signUp({
          email: systemEmail,
          password: password,
          options: {
              data: {
                  full_name: fullName, // Salva o nome nos metadados
                  pm_number: pmNumber,
                  personal_email: personalEmail // Salva o e-mail real nos metadados
              }
          }
        });

        if (error) throw error;

        if (data.user && !data.session) {
           setMessage({ text: "Cadastro realizado! Tente entrar com seu Nº PM e Senha.", type: 'success' });
           setMode('LOGIN');
           setPassword('');
        } else {
           setMessage({ text: "Cadastro realizado com sucesso! Entrando...", type: 'success' });
        }

      } else if (mode === 'LOGIN') {
        // --- LOGIN ---
        const { error } = await supabase.auth.signInWithPassword({
          email: systemEmail,
          password: password,
        });

        if (error) throw error;

      } else if (mode === 'RECOVERY') {
        // --- RECUPERAÇÃO DE SENHA ---
        if (sectionCode !== ACCESS_CODE) {
            throw new Error("Chave de acesso da seção incorreta.");
        }

        // NOTA DE SEGURANÇA:
        // O cliente Supabase (frontend) NÃO permite alterar a senha de um usuário
        // apenas sabendo o e-mail (ou Nº PM), mesmo que tenhamos uma "Chave Secreta" aqui no front.
        // Isso seria uma falha de segurança grave (qualquer um com a chave resetaria a senha de qualquer PM).
        // A alteração direta requer login prévio ou backend administrativo.

        // Simulação de UX para o usuário entender o processo:
        setMessage({ 
            text: "Validação OK. Por segurança, o sistema não permite reset direto sem login antigo. Solicite ao Administrador (P4) a exclusão do seu cadastro para criar um novo.", 
            type: 'error' 
        });
      }
    } catch (error: any) {
      let errorMsg = error.message;
      if (errorMsg.includes("Invalid login credentials")) errorMsg = "Nº PM ou senha incorretos.";
      if (errorMsg.includes("User already registered")) errorMsg = "Este Nº PM já possui cadastro.";

      setMessage({ text: errorMsg, type: 'error' });
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="min-h-screen bg-[#958458] flex items-center justify-center p-4">
      <div className="bg-[#fdfbf7] p-8 rounded-lg shadow-2xl w-full max-w-md border-t-4 border-pmmg-primary">

        <div className="flex flex-col items-center mb-6">
          <img 
            src={shieldUrl} 
            alt="Brasão PMMG" 
            className="h-24 mb-4 drop-shadow-md"
            style={{ height: '6rem' }}
          />
          <h1 className="text-2xl font-bold text-pmmg-primary text-center">Controles Frota 5ª RPM</h1>
          <p className="text-gray-500 text-sm mt-1 uppercase font-bold tracking-wider">
            {mode === 'REGISTER' && 'Novo Cadastro de Militar'}
            {mode === 'LOGIN' && 'Acesso ao Sistema'}
            {mode === 'RECOVERY' && 'Resetar Senha'}
          </p>
        </div>

        <form onSubmit={handleAuth} className="space-y-4">

          {/* Campo Nº PM (Comum a todos) */}
          <div>
            <label className="block text-sm font-bold text-gray-700 mb-1">Nº PM (Somente Números)</label>
            <div className="relative">
              <User className="absolute left-3 top-2.5 h-5 w-5 text-gray-400" />
              <input
                type="text"
                required
                maxLength={9}
                className="w-full pl-10 pr-4 py-2 border rounded-md focus:ring-2 focus:ring-pmmg-primary outline-none tracking-widest font-mono font-bold text-gray-700"
                placeholder="Ex: 1234567"
                value={pmNumber}
                onChange={handlePmChange}
              />
            </div>
          </div>

          {/* Campos Específicos de Cadastro */}
          {mode === 'REGISTER' && (
             <div className="space-y-4 animate-fade-in">
                <div>
                    <label className="block text-sm font-bold text-gray-700 mb-1">Nome Completo</label>
                    <input
                        type="text"
                        required
                        className="w-full px-4 py-2 border rounded-md focus:ring-2 focus:ring-pmmg-primary outline-none uppercase"
                        placeholder="Ex: SD FULANO DE TAL"
                        value={fullName}
                        onChange={(e) => setFullName(e.target.value.toUpperCase())}
                    />
                </div>
                <div>
                    <label className="block text-sm font-bold text-gray-700 mb-1">E-mail Pessoal</label>
                    <div className="relative">
                        <Mail className="absolute left-3 top-2.5 h-5 w-5 text-gray-400" />
                        <input
                            type="email"
                            required
                            className="w-full pl-10 pr-4 py-2 border rounded-md focus:ring-2 focus:ring-pmmg-primary outline-none"
                            placeholder="seu.email@gmail.com"
                            value={personalEmail}
                            onChange={(e) => setPersonalEmail(e.target.value)}
                        />
                    </div>
                </div>
             </div>
          )}

          {/* Campo Senha (Todas as telas) */}
          <div>
            <label className="block text-sm font-bold text-gray-700 mb-1">
                {mode === 'RECOVERY' ? 'Nova Senha Desejada' : 'Senha'}
            </label>
            <div className="relative">
              <Lock className="absolute left-3 top-2.5 h-5 w-5 text-gray-400" />
              <input
                type={showPassword ? "text" : "password"}
                required
                minLength={6}
                className="w-full pl-10 pr-10 py-2 border rounded-md focus:ring-2 focus:ring-pmmg-primary outline-none"
                placeholder="Mínimo 6 caracteres"
                value={password}
                onChange={(e) => setPassword(e.target.value)}
              />
              <button
                type="button"
                onClick={() => setShowPassword(!showPassword)}
                className="absolute right-3 top-2.5 text-gray-400 hover:text-gray-600 focus:outline-none"
              >
                {showPassword ? <EyeOff size={20} /> : <Eye size={20} />}
              </button>
            </div>
            {mode === 'REGISTER' && <p className="text-[10px] text-gray-500 mt-1">Pode conter letras, números e caracteres especiais.</p>}
          </div>

          {/* Código de Seção (Cadastro e Recuperação) */}
          {(mode === 'REGISTER' || mode === 'RECOVERY') && (
            <div className="bg-yellow-50 p-3 rounded border border-yellow-200 animate-fade-in mt-4">
                <label className="block text-sm font-bold text-yellow-800 mb-1">
                    {mode === 'RECOVERY' ? 'Chave de Acesso da Seção (Validação)' : 'Código de Acesso da Seção'}
                </label>
                <div className="relative">
                <KeyRound className="absolute left-3 top-2.5 h-5 w-5 text-yellow-600" />
                <input
                    type="text"
                    required
                    className="w-full pl-10 pr-4 py-2 border border-yellow-300 rounded-md focus:ring-2 focus:ring-pmmg-accent outline-none bg-white text-gray-800 placeholder-gray-400 uppercase font-bold"
                    placeholder="FROTA..."
                    value={sectionCode}
                    onChange={(e) => setSectionCode(e.target.value.toUpperCase())}
                />
                </div>
                <p className="text-[10px] text-yellow-700 mt-1">
                    * Chave necessária para validar a operação.
                </p>
            </div>
          )}

          {message && (
            <div className={`p-3 rounded text-sm text-center border font-semibold ${
                message.type === 'error' ? 'bg-red-50 text-red-700 border-red-200' : 'bg-green-50 text-green-700 border-green-200'
            }`}>
              {message.text}
            </div>
          )}

          <button
            type="submit"
            disabled={loading}
            className={`w-full text-white font-bold py-3 rounded-md transition-colors flex items-center justify-center gap-2 shadow-lg mt-4 ${
                loading ? 'bg-gray-400 cursor-not-allowed' : 'bg-pmmg-primary hover:bg-[#3E3223]/90'
            }`}
          >
            {loading ? 'Processando...' : (
                mode === 'REGISTER' ? <><UserPlus size={20} /> Confirmar Cadastro</> : 
                mode === 'RECOVERY' ? <><ShieldAlert size={20} /> Alterar Senha</> :
                <><LogIn size={20} /> Entrar</>
            )}
          </button>
        </form>

        <div className="mt-6 pt-4 border-t border-gray-200 flex flex-col gap-3 text-center">
            {mode === 'LOGIN' && (
                <>
                    <button 
                        onClick={() => { setMode('REGISTER'); setMessage(null); setPassword(''); setPmNumber(''); setSectionCode(''); }}
                        className="text-sm font-semibold text-pmmg-primary hover:text-[#C5A059] transition-colors"
                    >
                        Não tem cadastro? Crie sua conta.
                    </button>
                    <button 
                        onClick={() => { setMode('RECOVERY'); setMessage(null); setPassword(''); setPmNumber(''); setSectionCode(''); }}
                        className="text-xs text-gray-500 hover:text-red-600 transition-colors flex items-center justify-center gap-1"
                    >
                        <BadgeHelp size={14} /> Esqueci minha senha
                    </button>
                </>
            )}

            {(mode === 'REGISTER' || mode === 'RECOVERY') && (
                <button 
                    onClick={() => { setMode('LOGIN'); setMessage(null); setPassword(''); }}
                    className="text-sm font-semibold text-gray-600 hover:text-pmmg-primary transition-colors"
                >
                    Voltar para o Login
                </button>
            )}
        </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { Package, Truck, History, LogOut, Home, KeyRound, UserCircle } from 'lucide-react';
import { InventoryTab } from './components/InventoryTab';
import { MovementsTab } from './components/MovementsTab';
import { FleetTab } from './components/FleetTab';
import { checkConnection, supabase } from './lib/supabase';
import { DatabaseSetup } from './components/DatabaseSetup';
import { LoginScreen } from './components/LoginScreen';
import { DashboardSelection } from './components/DashboardSelection';
import { PavModule } from './components/PavModule';
import { Tab } from './types';

// Tipos de módulo disponíveis
type ModuleType = 'STOCK' | 'PAV' | null;

function App() {
  const [activeTab, setActiveTab] = useState<Tab>('inventory');
  const [currentModule, setCurrentModule] = useState<ModuleType>(null);
  const [isConnected, setIsConnected] = useState<boolean | null>(null);

  // Estados de Autenticação
  const [session, setSession] = useState<any>(null);
  const [authLoading, setAuthLoading] = useState(true);

  // Estado Modal Alterar Senha (Logado)
  const [isPasswordModalOpen, setIsPasswordModalOpen] = useState(false);
  const [newPassword, setNewPassword] = useState('');
  const [passwordMsg, setPasswordMsg] = useState<{text: string, type: 'success'|'error'} | null>(null);

  useEffect(() => {
    // 1. Verificar conexão com banco
    checkConnection().then(setIsConnected);

    // 2. Verificar Sessão Supabase
    supabase.auth.getSession().then(({ data: { session } }) => {
      setSession(session);
      setAuthLoading(false);
    });

    // 3. Ouvir mudanças na autenticação Supabase
    const { data: { subscription } } = supabase.auth.onAuthStateChange((_event, session) => {
      setSession(session);
      setAuthLoading(false);
    });

    return () => subscription.unsubscribe();
  }, []);

  // Função Unificada de Logout
  const handleLogout = async () => {
    await supabase.auth.signOut();
    setSession(null);
    setCurrentModule(null);
  };

  // Função para alterar senha (usuário logado)
  const handleChangePassword = async () => {
    if (newPassword.length < 6) {
        setPasswordMsg({ text: "A senha deve ter no mínimo 6 caracteres.", type: 'error' });
        return;
    }

    try {
        const { error } = await supabase.auth.updateUser({ password: newPassword });
        if (error) throw error;
        setPasswordMsg({ text: "Senha alterada com sucesso!", type: 'success' });
        setTimeout(() => {
            setIsPasswordModalOpen(false);
            setNewPassword('');
            setPasswordMsg(null);
        }, 1500);
    } catch (err: any) {
        setPasswordMsg({ text: "Erro ao alterar senha: " + err.message, type: 'error' });
    }
  };

  // ----- RENDERING FLOW -----

  // 1. Tela de Carregamento
  if (authLoading) {
     return (
        <div className="min-h-screen bg-[#958458] flex items-center justify-center">
            <div className="text-white font-bold text-xl animate-pulse">Carregando sistema...</div>
        </div>
     );
  }

  // 2. Tela de Login (Se não tiver sessão Supabase)
  if (!session) {
    return <LoginScreen />;
  }

  // 3. Configuração de Banco (apenas se conectado e houver erro de conexão com tabelas)
  if (isConnected === false) {
    return <DatabaseSetup />;
  }

  // Recupera nome dos metadados ou usa o email
  const userFullName = session?.user?.user_metadata?.full_name || 'Militar';
  // const userEmail = session?.user?.email || ''; // E-mail interno

  // 4. Tela de Seleção de Módulo (Dashboard)
  if (!currentModule) {
    return (
      <DashboardSelection 
        onSelectModule={setCurrentModule} 
        userEmail={userFullName} // Passando o Nome Completo
        onLogout={handleLogout}
      />
    );
  }

  // 5. Módulo PAV
  if (currentModule === 'PAV') {
    return (
      <PavModule 
        onBack={() => setCurrentModule(null)} 
        userEmail={userFullName}
        onLogout={handleLogout}
      />
    );
  }

  // 6. Módulo ESTOQUE (Aplicação original)
  const shieldUrl = "https://yaoebstgiagmrvlbozny.supabase.co/storage/v1/object/sign/Logo%20PMMG/ESCUDO%20PMMG.png?token=eyJraWQiOiJzdG9yYWdlLXVybC1zaWduaW5nLWtleV9mMjgyNzE5YS0xNjI0LTRiYTUtODk3MC1jNTc3ZDIzMTQ4YjUiLCJhbGciOiJIUzI1NiJ9.eyJ1cmwiOiJMb2dvIFBNTUcvRVNDVURPIFBNTUcucG5nIiwiaWF0IjoxNzY1NDAzMzE0LCJleHAiOjIzOTYxMjMzMTR9.1uAuyEEDpwU_vmvKjnSJw0uYbcOIkB-vRpXRDU-Arss";

  return (
    <div className="min-h-screen bg-[#958458] font-sans flex flex-col">
      {/* Header */}
      <header className="bg-[#3E3223] shadow-lg sticky top-0 z-40 border-b-4 border-[#C5A059]">
        <div className="container mx-auto px-4 h-32 flex items-center justify-between">

          {/* Lado Esquerdo: Escudo e Botão Voltar */}
          <div className="flex items-center gap-4 py-2">
            <button 
              onClick={() => setCurrentModule(null)}
              className="hidden md:flex flex-col items-center justify-center text-[#C5A059] hover:text-white transition-colors bg-white/5 hover:bg-white/10 p-2 rounded-lg"
              title="Voltar ao Menu Principal"
            >
               <Home size={20} />
               <span className="text-[10px] uppercase font-bold mt-1">Menu</span>
            </button>
            <img 
              src={shieldUrl} 
              alt="Escudo PMMG" 
              className="h-28 drop-shadow-xl filter brightness-110"
              style={{ height: '7rem' }}
            />
          </div>

          {/* Lado Direito: Título e Saudação */}
          <div className="text-right flex flex-col items-end">
            <h1 className="text-3xl md:text-4xl font-extrabold tracking-tight text-[#C5A059] drop-shadow-md shadow-black/50 font-serif uppercase">
              CONTROLE DE ESTOQUE
            </h1>
            <p className="text-lg font-bold text-[#C5A059] opacity-90 tracking-widest font-serif mb-1">
              FROTA 5ª RPM
            </p>

            <div className="flex items-center gap-3 bg-black/20 px-3 py-1 rounded-full mt-1 border border-white/10 shadow-inner">
                <span className="text-sm font-semibold text-white/90 flex items-center gap-2">
                   <UserCircle size={18} className="text-[#C5A059]" /> 
                   Bem-vindo, {userFullName}
                </span>
                <div className="h-4 w-px bg-white/20 mx-1"></div>
                <button 
                    onClick={() => setIsPasswordModalOpen(true)}
                    className="text-[#C5A059] hover:text-white transition-colors p-1 hover:bg-white/10 rounded-full flex items-center gap-1"
                    title="Alterar Senha"
                >
                    <KeyRound size={14} /> <span className="text-[10px] font-bold">SENHA</span>
                </button>
            </div>
          </div>
        </div>

        {/* Navigation Tabs & Logout */}
        <div className="bg-[#4A3B2A]/90 backdrop-blur-sm text-white/90">
          <div className="container mx-auto px-4 flex justify-between items-center overflow-x-auto">
            <div className="flex gap-1">
              {/* Botão Menu Mobile (aparece só em telas pequenas) */}
              <button 
                onClick={() => setCurrentModule(null)}
                className="md:hidden flex items-center gap-2 px-4 py-3 border-b-4 border-transparent text-white/70 hover:text-white hover:bg-white/5"
              >
                 <Home size={18} />
              </button>

              {/* 1. ESTOQUE */}
              <button
                  onClick={() => setActiveTab('inventory')}
                  className={`flex items-center gap-2 px-6 py-3 border-b-4 transition-all whitespace-nowrap font-bold uppercase tracking-wider text-sm ${
                    activeTab === 'inventory' 
                    ? 'border-[#C5A059] text-[#C5A059] bg-black/20' 
                    : 'border-transparent hover:bg-white/5 text-white/70 hover:text-white'
                  }`}
              >
                <Package size={18} /> Estoque
              </button>

              {/* 2. MOVIMENTAÇÕES */}
              <button
                  onClick={() => setActiveTab('movements')}
                  className={`flex items-center gap-2 px-6 py-3 border-b-4 transition-all whitespace-nowrap font-bold uppercase tracking-wider text-sm ${
                    activeTab === 'movements' 
                    ? 'border-[#C5A059] text-[#C5A059] bg-black/20' 
                    : 'border-transparent hover:bg-white/5 text-white/70 hover:text-white'
                  }`}
              >
                <History size={18} /> Movimentações
              </button>

              {/* 3. MAPA CARGA */}
              <button
                  onClick={() => setActiveTab('fleet')}
                  className={`flex items-center gap-2 px-6 py-3 border-b-4 transition-all whitespace-nowrap font-bold uppercase tracking-wider text-sm ${
                    activeTab === 'fleet' 
                    ? 'border-[#C5A059] text-[#C5A059] bg-black/20' 
                    : 'border-transparent hover:bg-white/5 text-white/70 hover:text-white'
                  }`}
              >
                <Truck size={18} /> Mapa Carga
              </button>
            </div>

            {/* Botão Sair */}
            <button 
              onClick={handleLogout}
              className="flex items-center gap-2 px-4 py-2 text-red-200 hover:text-red-100 hover:bg-red-900/30 rounded transition-colors text-sm font-semibold ml-4 whitespace-nowrap"
              title="Sair do sistema"
            >
              <LogOut size={18} /> <span className="hidden sm:inline">Sair</span>
            </button>
          </div>
        </div>
      </header>

      {/* MODAL ALTERAR SENHA (LOGADO) */}
      {isPasswordModalOpen && (
          <div className="fixed inset-0 bg-black/70 backdrop-blur-sm flex items-center justify-center z-[80] p-4">
              <div className="bg-white p-6 rounded-lg shadow-2xl w-full max-w-sm border-t-4 border-[#C5A059]">
                  <h3 className="text-lg font-bold text-[#3E3223] mb-4 flex items-center gap-2">
                      <KeyRound size={20} className="text-[#C5A059]" />
                      Alterar Minha Senha
                  </h3>

                  <div className="space-y-4">
                      <div>
                          <label className="block text-sm font-bold text-gray-700 mb-1">Nova Senha</label>
                          <input 
                              type="password"
                              className="w-full border p-2 rounded focus:ring-2 focus:ring-[#C5A059] outline-none"
                              placeholder="Mínimo 6 caracteres"
                              value={newPassword}
                              onChange={e => setNewPassword(e.target.value)}
                          />
                      </div>

                      {passwordMsg && (
                          <div className={`text-sm p-2 rounded ${
                              passwordMsg.type === 'success' ? 'bg-green-100 text-green-800' : 'bg-red-100 text-red-800'
                          }`}>
                              {passwordMsg.text}
                          </div>
                      )}

                      <div className="flex justify-end gap-2 pt-2">
                          <button 
                              onClick={() => { setIsPasswordModalOpen(false); setNewPassword(''); setPasswordMsg(null); }}
                              className="px-4 py-2 text-gray-600 hover:bg-gray-100 rounded"
                          >
                              Cancelar
                          </button>
                          <button 
                              onClick={handleChangePassword}
                              className="px-4 py-2 bg-[#3E3223] text-white rounded hover:bg-[#2a2218]"
                          >
                              Salvar Senha
                          </button>
                      </div>
                  </div>
              </div>
          </div>
      )}

      {/* Main Content */}
      <main className="container mx-auto px-4 py-8 flex-grow">
        <div className="bg-[#fdfbf7] rounded-xl shadow-2xl border border-[#d4c5a3] min-h-[500px] p-1">
          {isConnected === null ? (
            <div className="flex items-center justify-center h-64 text-gray-500 font-semibold">
              Conectando ao banco de dados...
            </div>
          ) : (
            <div className="p-4 md:p-6">
              {activeTab === 'inventory' && <InventoryTab />}
              {activeTab === 'movements' && <MovementsTab />}
              {activeTab === 'fleet' && <FleetTab />}
            </div>
          )}
        </div>
      </main>
    </div>
  );
}

export default App;

import React from 'react';

export const DatabaseSetup: React.FC = () => {
  const sql = `
-- Execute este SQL no Editor SQL do seu projeto Supabase

-- 1. TABELA DE PERFIS (Mapeia PM -> Email)
CREATE TABLE IF NOT EXISTS public.profiles (
    id UUID REFERENCES auth.users ON DELETE CASCADE PRIMARY KEY,
    pm_number TEXT UNIQUE NOT NULL,
    email TEXT NOT NULL,
    full_name TEXT,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT timezone('utc'::text, now()) NOT NULL
);

-- Políticas de Segurança (RLS) para Profiles
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;

-- Permite que qualquer um LEIA os perfis (Necessário para o Login achar o email pelo PM)
DROP POLICY IF EXISTS "Public Read Profiles" ON public.profiles;
CREATE POLICY "Public Read Profiles" ON public.profiles FOR SELECT USING (true);

-- Permite que o próprio usuário insira seu perfil durante o cadastro
DROP POLICY IF EXISTS "Users Insert Self" ON public.profiles;
CREATE POLICY "Users Insert Self" ON public.profiles FOR INSERT WITH CHECK (auth.uid() = id);

-- Permite que o usuário atualize seu próprio perfil
DROP POLICY IF EXISTS "Users Update Self" ON public.profiles;
CREATE POLICY "Users Update Self" ON public.profiles FOR UPDATE USING (auth.uid() = id);


-- 2. TABELA DE CONTROLE DE PAV
CREATE TABLE IF NOT EXISTS public.pav_processes (
    id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
    fraction TEXT,
    vehicle_prefix TEXT,
    vehicle_plate TEXT,
    accident_date DATE,
    reds_number TEXT,
    pav_number TEXT,
    inquirer TEXT,
    sent_to_inquirer BOOLEAN DEFAULT FALSE,
    os_request_date DATE,
    os_number TEXT,
    os_followup_date DATE,
    observations TEXT,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT timezone('utc'::text, now()) NOT NULL
);

ALTER TABLE public.pav_processes ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "Public Access PAV" ON public.pav_processes;
CREATE POLICY "Public Access PAV" ON public.pav_processes FOR ALL USING (true) WITH CHECK (true);


-- 3. TABELAS DE ESTOQUE (Se ainda não existirem)
CREATE TABLE IF NOT EXISTS public.materials (
    id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
    name TEXT NOT NULL,
    quantity INTEGER DEFAULT 0,
    unit TEXT DEFAULT 'Unidade',
    created_at TIMESTAMP WITH TIME ZONE DEFAULT timezone('utc'::text, now()) NOT NULL
);

CREATE TABLE IF NOT EXISTS public.vehicles (
    id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
    prefix TEXT NOT NULL,
    plate TEXT,
    model TEXT,
    fraction TEXT,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT timezone('utc'::text, now()) NOT NULL
);

CREATE TABLE IF NOT EXISTS public.movements (
    id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
    material_id UUID REFERENCES public.materials(id) ON DELETE CASCADE,
    type TEXT NOT NULL, 
    quantity INTEGER NOT NULL,
    requester TEXT,
    vehicle_prefix TEXT,
    guide_number TEXT,
    observation TEXT,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT timezone('utc'::text, now()) NOT NULL
);

-- Permissões Gerais
ALTER TABLE public.materials ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.vehicles ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.movements ENABLE ROW LEVEL SECURITY;

CREATE POLICY "Public Access Materials" ON public.materials FOR ALL USING (true) WITH CHECK (true);
CREATE POLICY "Public Access Vehicles" ON public.vehicles FOR ALL USING (true) WITH CHECK (true);
CREATE POLICY "Public Access Movements" ON public.movements FOR ALL USING (true) WITH CHECK (true);

-- Trigger de Estoque
CREATE OR REPLACE FUNCTION handle_inventory_update() RETURNS TRIGGER AS $$
BEGIN
    IF (TG_OP = 'DELETE' OR TG_OP = 'UPDATE') THEN
        IF OLD.type = 'ENTRADA' THEN
            UPDATE materials SET quantity = quantity - OLD.quantity WHERE id = OLD.material_id;
        ELSE 
            UPDATE materials SET quantity = quantity + OLD.quantity WHERE id = OLD.material_id;
        END IF;
    END IF;

    IF (TG_OP = 'INSERT' OR TG_OP = 'UPDATE') THEN
        IF NEW.type = 'ENTRADA' THEN
            UPDATE materials SET quantity = quantity + NEW.quantity WHERE id = NEW.material_id;
        ELSE 
            UPDATE materials SET quantity = quantity - NEW.quantity WHERE id = NEW.material_id;
        END IF;
    END IF;
    RETURN NULL;
END;
$$ LANGUAGE plpgsql;

DROP TRIGGER IF EXISTS trigger_inventory_update ON public.movements;
CREATE TRIGGER trigger_inventory_update
AFTER INSERT OR UPDATE OR DELETE ON public.movements
FOR EACH ROW EXECUTE FUNCTION handle_inventory_update();
  `;

  return (
    <div className="fixed inset-0 bg-gray-900 flex items-center justify-center p-4 z-50 text-white overflow-y-auto">
      <div className="bg-gray-800 p-8 rounded-lg max-w-3xl w-full shadow-2xl my-8">
        <h2 className="text-2xl font-bold mb-4 text-red-400">Atualização Necessária do Banco</h2>
        <p className="mb-4 text-gray-300">
          Para habilitar o login por Nº PM com E-mail Real, precisamos criar a tabela de perfis.
        </p>
        <p className="mb-2 font-semibold">Copie e execute este SQL no Supabase:</p>
        <div className="bg-gray-950 p-4 rounded border border-gray-700 font-mono text-sm overflow-auto max-h-64 mb-4 select-all">
          <pre>{sql}</pre>
        </div>
        <button 
          onClick={() => window.location.reload()}
          className="w-full py-3 bg-blue-600 hover:bg-blue-700 rounded font-bold transition"
        >
          Já executei o SQL, entrar no sistema
        </button>
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { Lock, User, LogIn, Eye, EyeOff, UserPlus, KeyRound, ShieldAlert, BadgeHelp, Mail, CheckCircle } from 'lucide-react';
import { supabase } from '../lib/supabase';

interface LoginScreenProps {
  onLoginSuccess?: () => void;
}

type AuthMode = 'LOGIN' | 'REGISTER' | 'RECOVERY';

export const LoginScreen: React.FC<LoginScreenProps> = () => {
  const [mode, setMode] = useState<AuthMode>('LOGIN');

  // Campos
  const [pmNumber, setPmNumber] = useState('');
  const [fullName, setFullName] = useState('');
  const [realEmail, setRealEmail] = useState('');
  const [password, setPassword] = useState('');
  const [sectionCode, setSectionCode] = useState(''); 

  const [showPassword, setShowPassword] = useState(false);
  const [loading, setLoading] = useState(false);
  const [message, setMessage] = useState<{ text: string; type: 'error' | 'success' | 'info' } | null>(null);

  // --- CONFIGURAÇÃO DE SEGURANÇA ---
  const ACCESS_CODE = 'FROTA5RPM'; 

  const shieldUrl = "https://yaoebstgiagmrvlbozny.supabase.co/storage/v1/object/sign/Logo%20PMMG/ESCUDO%20PMMG.png?token=eyJraWQiOiJzdG9yYWdlLXVybC1zaWduaW5nLWtleV9mMjgyNzE5YS0xNjI0LTRiYTUtODk3MC1jNTc3ZDIzMTQ4YjUiLCJhbGciOiJIUzI1NiJ9.eyJ1cmwiOiJMb2dvIFBNTUcvRVNDVURPIFBNTUcucG5nIiwiaWF0IjoxNzY1NDAzMzE0LCJleHAiOjIzOTYxMjMzMTR9.1uAuyEEDpwU_vmvKjnSJw0uYbcOIkB-vRpXRDU-Arss";

  // Validação de PM
  const handlePmChange = (e: React.ChangeEvent<HTMLInputElement>) => {
      const val = e.target.value.replace(/\D/g, '').slice(0, 7);
      setPmNumber(val);
  };

  const handleAuth = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    setMessage(null);

    // Validações Comuns
    if (pmNumber.length < 3) {
        setMessage({ text: "Nº PM inválido.", type: 'error' });
        setLoading(false);
        return;
    }

    try {
      if (mode === 'REGISTER') {
        // --- CADASTRO ---
        if (sectionCode !== ACCESS_CODE) throw new Error("Código de acesso da seção incorreto.");
        if (!fullName.trim()) throw new Error("Informe seu nome completo.");
        if (!realEmail.includes('@')) throw new Error("Informe um e-mail válido.");
        if (password.length < 6) throw new Error("A senha deve ter no mínimo 6 caracteres.");

        // 1. Criar Usuário no Supabase Auth
        const { data: authData, error: authError } = await supabase.auth.signUp({
          email: realEmail,
          password: password,
          options: {
              data: {
                  full_name: fullName,
                  pm_number: pmNumber
              }
          }
        });

        if (authError) throw authError;

        // 2. Criar Perfil na tabela 'profiles' para permitir login por PM depois
        if (authData.user) {
            const { error: profileError } = await supabase.from('profiles').insert({
                id: authData.user.id,
                pm_number: pmNumber,
                email: realEmail,
                full_name: fullName
            });

            if (profileError) {
                // Se falhar o perfil (ex: PM já existe), tenta desfazer ou avisa
                console.error("Erro ao criar perfil:", profileError);
                if (profileError.code === '23505') { // Unique violation
                    throw new Error("Este Nº PM já está vinculado a outra conta.");
                }
            }

            setMessage({ text: "Cadastro realizado com sucesso! Faça login.", type: 'success' });
            setMode('LOGIN');
            setPassword('');
        }

      } else if (mode === 'LOGIN') {
        // --- LOGIN ---
        // 1. Buscar qual é o e-mail deste PM
        const { data: profiles, error: profileError } = await supabase
            .from('profiles')
            .select('email')
            .eq('pm_number', pmNumber)
            .single();

        if (profileError || !profiles) {
            throw new Error("Cadastro não encontrado para este Nº PM. Verifique se digitou corretamente ou cadastre-se.");
        }

        const userEmail = profiles.email;

        // 2. Fazer login com o e-mail encontrado
        const { error: loginError } = await supabase.auth.signInWithPassword({
          email: userEmail,
          password: password,
        });

        if (loginError) throw loginError;

      } else if (mode === 'RECOVERY') {
        // --- RECUPERAÇÃO ---
        if (sectionCode !== ACCESS_CODE) throw new Error("Chave de acesso da seção incorreta.");

        // 1. Buscar o email do PM
        const { data: profiles, error: profileError } = await supabase
            .from('profiles')
            .select('email')
            .eq('pm_number', pmNumber)
            .single();

        if (profileError || !profiles) {
             throw new Error("PM não encontrado no sistema.");
        }

        // 2. Enviar email de reset
        const { error: resetError } = await supabase.auth.resetPasswordForEmail(profiles.email, {
            redirectTo: window.location.origin, // Redireciona para o app após clicar no email
        });

        if (resetError) throw resetError;

        setMessage({ 
            text: `Um link de redefinição de senha foi enviado para: ${profiles.email}. Por segurança, não é possível "sobrepor" a conta sem acesso ao e-mail.`, 
            type: 'info' 
        });
      }

    } catch (error: any) {
      let errorMsg = error.message;
      if (errorMsg.includes("Invalid login credentials")) errorMsg = "Senha incorreta.";
      if (errorMsg.includes("User already registered")) errorMsg = "Este e-mail já está em uso. Tente recuperar a senha.";

      setMessage({ text: errorMsg, type: 'error' });
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="min-h-screen bg-[#958458] flex items-center justify-center p-4">
      <div className="bg-[#fdfbf7] p-8 rounded-lg shadow-2xl w-full max-w-md border-t-4 border-pmmg-primary">

        <div className="flex flex-col items-center mb-6">
          <img 
            src={shieldUrl} 
            alt="Brasão PMMG" 
            className="h-24 mb-4 drop-shadow-md"
            style={{ height: '6rem' }}
          />
          <h1 className="text-2xl font-bold text-pmmg-primary text-center">Controles Frota 5ª RPM</h1>
          <p className="text-gray-500 text-sm mt-1 uppercase font-bold tracking-wider">
            {mode === 'REGISTER' && 'Novo Cadastro de Militar'}
            {mode === 'LOGIN' && 'Acesso ao Sistema'}
            {mode === 'RECOVERY' && 'Recuperar Acesso'}
          </p>
        </div>

        <form onSubmit={handleAuth} className="space-y-4">

          {/* Campo Nº PM (Comum a todos) */}
          <div>
            <label className="block text-sm font-bold text-gray-700 mb-1">Nº PM (Login)</label>
            <div className="relative">
              <User className="absolute left-3 top-2.5 h-5 w-5 text-gray-400" />
              <input
                type="text"
                required
                maxLength={9}
                className="w-full pl-10 pr-4 py-2 border rounded-md focus:ring-2 focus:ring-pmmg-primary outline-none tracking-widest font-mono font-bold text-gray-800 text-lg"
                placeholder="Ex: 1234567"
                value={pmNumber}
                onChange={handlePmChange}
                disabled={loading}
              />
            </div>
          </div>

          {/* Campos de Cadastro */}
          {mode === 'REGISTER' && (
             <div className="space-y-4 animate-fade-in">
                <div>
                    <label className="block text-sm font-bold text-gray-700 mb-1">Nome Completo</label>
                    <input
                        type="text"
                        required
                        className="w-full px-4 py-2 border rounded-md focus:ring-2 focus:ring-pmmg-primary outline-none uppercase"
                        placeholder="Ex: SD FULANO DE TAL"
                        value={fullName}
                        onChange={(e) => setFullName(e.target.value.toUpperCase())}
                    />
                </div>
                <div>
                    <label className="block text-sm font-bold text-gray-700 mb-1">Seu E-mail Real</label>
                    <div className="relative">
                        <Mail className="absolute left-3 top-2.5 h-5 w-5 text-gray-400" />
                        <input
                            type="email"
                            required
                            className="w-full pl-10 pr-4 py-2 border rounded-md focus:ring-2 focus:ring-pmmg-primary outline-none"
                            placeholder="exemplo@gmail.com"
                            value={realEmail}
                            onChange={(e) => setRealEmail(e.target.value)}
                        />
                    </div>
                    <p className="text-[10px] text-gray-500 mt-1">Este e-mail será usado para recuperação de senha.</p>
                </div>
             </div>
          )}

          {/* Campo Senha (Login e Cadastro) */}
          {mode !== 'RECOVERY' && (
            <div>
                <label className="block text-sm font-bold text-gray-700 mb-1">Senha</label>
                <div className="relative">
                <Lock className="absolute left-3 top-2.5 h-5 w-5 text-gray-400" />
                <input
                    type={showPassword ? "text" : "password"}
                    required
                    minLength={6}
                    className="w-full pl-10 pr-10 py-2 border rounded-md focus:ring-2 focus:ring-pmmg-primary outline-none"
                    placeholder={mode === 'REGISTER' ? "Crie sua senha" : "Sua senha"}
                    value={password}
                    onChange={(e) => setPassword(e.target.value)}
                />
                <button
                    type="button"
                    onClick={() => setShowPassword(!showPassword)}
                    className="absolute right-3 top-2.5 text-gray-400 hover:text-gray-600 focus:outline-none"
                >
                    {showPassword ? <EyeOff size={20} /> : <Eye size={20} />}
                </button>
                </div>
            </div>
          )}

          {/* Código de Seção (Cadastro e Recuperação) */}
          {(mode === 'REGISTER' || mode === 'RECOVERY') && (
            <div className="bg-yellow-50 p-3 rounded border border-yellow-200 animate-fade-in mt-4">
                <label className="block text-sm font-bold text-yellow-800 mb-1">
                    Código de Acesso da Seção
                </label>
                <div className="relative">
                <KeyRound className="absolute left-3 top-2.5 h-5 w-5 text-yellow-600" />
                <input
                    type="text"
                    required
                    className="w-full pl-10 pr-4 py-2 border border-yellow-300 rounded-md focus:ring-2 focus:ring-pmmg-accent outline-none bg-white text-gray-800 placeholder-gray-400 uppercase font-bold"
                    placeholder="FROTA..."
                    value={sectionCode}
                    onChange={(e) => setSectionCode(e.target.value.toUpperCase())}
                />
                </div>
                <p className="text-[10px] text-yellow-700 mt-1">
                    * Validação de segurança obrigatória.
                </p>
            </div>
          )}

          {message && (
            <div className={`p-3 rounded text-sm text-center border font-semibold ${
                message.type === 'error' ? 'bg-red-50 text-red-700 border-red-200' : 
                message.type === 'success' ? 'bg-green-50 text-green-700 border-green-200' :
                'bg-blue-50 text-blue-700 border-blue-200'
            }`}>
              {message.text}
            </div>
          )}

          <button
            type="submit"
            disabled={loading}
            className={`w-full text-white font-bold py-3 rounded-md transition-colors flex items-center justify-center gap-2 shadow-lg mt-4 ${
                loading ? 'bg-gray-400 cursor-not-allowed' : 'bg-pmmg-primary hover:bg-[#3E3223]/90'
            }`}
          >
            {loading ? 'Processando...' : (
                mode === 'REGISTER' ? <><UserPlus size={20} /> Confirmar Cadastro</> : 
                mode === 'RECOVERY' ? <><Mail size={20} /> Enviar Link de Recuperação</> :
                <><LogIn size={20} /> Entrar</>
            )}
          </button>
        </form>

        <div className="mt-6 pt-4 border-t border-gray-200 flex flex-col gap-3 text-center">
            {mode === 'LOGIN' && (
                <>
                    <button 
                        onClick={() => { setMode('REGISTER'); setMessage(null); setPassword(''); setPmNumber(''); setSectionCode(''); setRealEmail(''); setFullName(''); }}
                        className="text-sm font-semibold text-pmmg-primary hover:text-[#C5A059] transition-colors"
                    >
                        Não tem cadastro? Crie sua conta.
                    </button>
                    <button 
                        onClick={() => { setMode('RECOVERY'); setMessage(null); setPassword(''); setPmNumber(''); setSectionCode(''); }}
                        className="text-xs text-gray-500 hover:text-red-600 transition-colors flex items-center justify-center gap-1"
                    >
                        <BadgeHelp size={14} /> Esqueci a senha
                    </button>
                </>
            )}

            {(mode === 'REGISTER' || mode === 'RECOVERY') && (
                <button 
                    onClick={() => { setMode('LOGIN'); setMessage(null); setPassword(''); }}
                    className="text-sm font-semibold text-gray-600 hover:text-pmmg-primary transition-colors"
                >
                    Voltar para o Login
                </button>
            )}
        </div>

        {mode === 'RECOVERY' && (
             <p className="text-[10px] text-gray-400 text-center mt-4">
                 * Por segurança, não é possível "sobrepor" um cadastro existente. Utilize a recuperação por e-mail.
             </p>
        )}
      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { Package, Truck, History, LogOut, Home, KeyRound, UserCircle } from 'lucide-react';
import { InventoryTab } from './components/InventoryTab';
import { MovementsTab } from './components/MovementsTab';
import { FleetTab } from './components/FleetTab';
import { checkConnection, supabase } from './lib/supabase';
import { DatabaseSetup } from './components/DatabaseSetup';
import { LoginScreen } from './components/LoginScreen';
import { DashboardSelection } from './components/DashboardSelection';
import { PavModule } from './components/PavModule';
import { Tab } from './types';

// Tipos de módulo disponíveis
type ModuleType = 'STOCK' | 'PAV' | null;

function App() {
  const [activeTab, setActiveTab] = useState<Tab>('inventory');
  const [currentModule, setCurrentModule] = useState<ModuleType>(null);
  const [isConnected, setIsConnected] = useState<boolean | null>(null);

  // Estados de Autenticação
  const [session, setSession] = useState<any>(null);
  const [authLoading, setAuthLoading] = useState(true);

  // Estado Modal Alterar Senha (Logado)
  const [isPasswordModalOpen, setIsPasswordModalOpen] = useState(false);
  const [newPassword, setNewPassword] = useState('');
  const [passwordMsg, setPasswordMsg] = useState<{text: string, type: 'success'|'error'} | null>(null);

  useEffect(() => {
    // 1. Verificar conexão com banco
    checkConnection().then(setIsConnected);

    // 2. Verificar Sessão Supabase
    supabase.auth.getSession().then(({ data: { session } }) => {
      setSession(session);
      setAuthLoading(false);
    });

    // 3. Ouvir mudanças na autenticação Supabase
    const { data: { subscription } } = supabase.auth.onAuthStateChange((_event, session) => {
      setSession(session);
      setAuthLoading(false);
    });

    return () => subscription.unsubscribe();
  }, []);

  // Função Unificada de Logout
  const handleLogout = async () => {
    await supabase.auth.signOut();
    setSession(null);
    setCurrentModule(null);
  };

  // Função para alterar senha (usuário logado)
  const handleChangePassword = async () => {
    if (newPassword.length < 6) {
        setPasswordMsg({ text: "A senha deve ter no mínimo 6 caracteres.", type: 'error' });
        return;
    }

    try {
        const { error } = await supabase.auth.updateUser({ password: newPassword });
        if (error) throw error;
        setPasswordMsg({ text: "Senha alterada com sucesso!", type: 'success' });
        setTimeout(() => {
            setIsPasswordModalOpen(false);
            setNewPassword('');
            setPasswordMsg(null);
        }, 1500);
    } catch (err: any) {
        setPasswordMsg({ text: "Erro ao alterar senha: " + err.message, type: 'error' });
    }
  };

  // ----- RENDERING FLOW -----

  // 1. Tela de Carregamento
  if (authLoading) {
     return (
        <div className="min-h-screen bg-[#958458] flex items-center justify-center">
            <div className="text-white font-bold text-xl animate-pulse">Carregando sistema...</div>
        </div>
     );
  }

  // 2. Tela de Login (Se não tiver sessão Supabase)
  if (!session) {
    return <LoginScreen />;
  }

  // 3. Configuração de Banco (apenas se conectado e houver erro de conexão com tabelas)
  if (isConnected === false) {
    return <DatabaseSetup />;
  }

  // Recupera nome dos metadados ou usa o email
  const userFullName = session?.user?.user_metadata?.full_name || session?.user?.email || 'Militar';

  // 4. Tela de Seleção de Módulo (Dashboard)
  if (!currentModule) {
    return (
      <DashboardSelection 
        onSelectModule={setCurrentModule} 
        userEmail={userFullName} 
        onLogout={handleLogout}
      />
    );
  }

  // 5. Módulo PAV
  if (currentModule === 'PAV') {
    return (
      <PavModule 
        onBack={() => setCurrentModule(null)} 
        userEmail={userFullName}
        onLogout={handleLogout}
      />
    );
  }

  // 6. Módulo ESTOQUE (Aplicação original)
  const shieldUrl = "https://yaoebstgiagmrvlbozny.supabase.co/storage/v1/object/sign/Logo%20PMMG/ESCUDO%20PMMG.png?token=eyJraWQiOiJzdG9yYWdlLXVybC1zaWduaW5nLWtleV9mMjgyNzE5YS0xNjI0LTRiYTUtODk3MC1jNTc3ZDIzMTQ4YjUiLCJhbGciOiJIUzI1NiJ9.eyJ1cmwiOiJMb2dvIFBNTUcvRVNDVURPIFBNTUcucG5nIiwiaWF0IjoxNzY1NDAzMzE0LCJleHAiOjIzOTYxMjMzMTR9.1uAuyEEDpwU_vmvKjnSJw0uYbcOIkB-vRpXRDU-Arss";

  return (
    <div className="min-h-screen bg-[#958458] font-sans flex flex-col">
      {/* Header */}
      <header className="bg-[#3E3223] shadow-lg sticky top-0 z-40 border-b-4 border-[#C5A059]">
        <div className="container mx-auto px-4 h-32 flex items-center justify-between">

          {/* Lado Esquerdo: Escudo e Botão Voltar */}
          <div className="flex items-center gap-4 py-2">
            <button 
              onClick={() => setCurrentModule(null)}
              className="hidden md:flex flex-col items-center justify-center text-[#C5A059] hover:text-white transition-colors bg-white/5 hover:bg-white/10 p-2 rounded-lg"
              title="Voltar ao Menu Principal"
            >
               <Home size={20} />
               <span className="text-[10px] uppercase font-bold mt-1">Menu</span>
            </button>
            <img 
              src={shieldUrl} 
              alt="Escudo PMMG" 
              className="h-28 drop-shadow-xl filter brightness-110"
              style={{ height: '7rem' }}
            />
          </div>

