CREATE OR REPLACE FUNCTION handle_inventory_update() RETURNS TRIGGER AS $$
BEGIN
    IF (TG_OP = 'DELETE' OR TG_OP = 'UPDATE') THEN
        IF OLD.type = 'ENTRADA' THEN
            UPDATE materials SET quantity = quantity - OLD.quantity WHERE id = OLD.material_id;
        ELSE 
            UPDATE materials SET quantity = quantity + OLD.quantity WHERE id = OLD.material_id;
        END IF;
    END IF;
    IF (TG_OP = 'INSERT' OR TG_OP = 'UPDATE') THEN
        IF NEW.type = 'ENTRADA' THEN
            UPDATE materials SET quantity = quantity + NEW.quantity WHERE id = NEW.material_id;
        ELSE 
            UPDATE materials SET quantity = quantity - NEW.quantity WHERE id = NEW.material_id;
        END IF;
    END IF;
    RETURN NULL;
END;
$$ LANGUAGE plpgsql;

DROP TRIGGER IF EXISTS trigger_inventory_update ON public.movements;
CREATE TRIGGER trigger_inventory_update
AFTER INSERT OR UPDATE OR DELETE ON public.movements
FOR EACH ROW EXECUTE FUNCTION handle_inventory_update();


-- 4. MÓDULO PAV
CREATE TABLE IF NOT EXISTS public.pav_processes (
    id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
    fraction TEXT,
    vehicle_prefix TEXT,
    vehicle_plate TEXT,
    accident_date DATE,
    reds_number TEXT,
    pav_number TEXT,
    inquirer TEXT,
    sent_to_inquirer BOOLEAN DEFAULT FALSE,
    os_request_date DATE,
    os_number TEXT,
    os_followup_date DATE,
    observations TEXT,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT timezone('utc'::text, now()) NOT NULL
);

ALTER TABLE public.pav_processes ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "Public Access PAV" ON public.pav_processes;
CREATE POLICY "Public Access PAV" ON public.pav_processes FOR ALL USING (true) WITH CHECK (true);
  `;

  const handleCopy = () => {
      navigator.clipboard.writeText(sql);
      setCopied(true);
      setTimeout(() => setCopied(false), 2000);
  };

  return (
    <div className="fixed inset-0 bg-gray-900 flex items-center justify-center p-4 z-50 text-white overflow-y-auto">
      <div className="bg-gray-800 p-8 rounded-lg max-w-4xl w-full shadow-2xl my-8 border border-gray-700">
        <div className="flex items-center gap-3 mb-6 border-b border-gray-700 pb-4">
            <Database className="text-blue-400" size={32} />
            <div>
                <h2 className="text-2xl font-bold text-white">Configuração do Banco de Dados</h2>
                <p className="text-gray-400 text-sm">Atualize o banco para ativar a nova recuperação de senha.</p>
            </div>
        </div>

        <div className="bg-blue-900/30 border border-blue-500/30 p-4 rounded mb-6">
            <h3 className="font-bold text-blue-300 mb-2">Instruções Importantes:</h3>
            <ol className="list-decimal list-inside text-gray-300 space-y-1 text-sm">
                <li>Copie o código SQL abaixo.</li>
                <li>Vá até o painel do Supabase do seu projeto ({'>'} SQL Editor).</li>
                <li>Cole o código e clique em <strong>Run</strong>.</li>
            </ol>
        </div>

        <div className="relative">
            <div className="absolute top-2 right-2">
                <button 
                    onClick={handleCopy}
                    className={`flex items-center gap-2 px-3 py-1.5 rounded text-sm font-bold transition-all ${
                        copied 
                        ? 'bg-green-600 text-white' 
                        : 'bg-gray-700 hover:bg-gray-600 text-gray-200'
                    }`}
                >
                    {copied ? <><Check size={16} /> Copiado!</> : <><Copy size={16} /> Copiar SQL</>}
                </button>
            </div>
            <div className="bg-gray-950 p-4 rounded border border-gray-700 font-mono text-xs overflow-auto max-h-[400px] mb-6 select-all custom-scrollbar">
                <pre style={{ whiteSpace: 'pre-wrap' }}>{sql}</pre>
            </div>
        </div>

        <button 
          onClick={() => window.location.reload()}
          className="w-full py-4 bg-blue-600 hover:bg-blue-700 rounded-lg font-bold text-lg transition shadow-lg hover:shadow-blue-500/20"
        >
          Já executei o SQL, Tentar Novamente
        </button>
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { Lock, User, LogIn, Eye, EyeOff, UserPlus, KeyRound, ShieldAlert, BadgeHelp, Mail, CheckCircle, RefreshCw } from 'lucide-react';
import { supabase } from '../lib/supabase';

interface LoginScreenProps {
  onLoginSuccess?: () => void;
}

type AuthMode = 'LOGIN' | 'REGISTER' | 'RECOVERY';

export const LoginScreen: React.FC<LoginScreenProps> = () => {
  const [mode, setMode] = useState<AuthMode>('LOGIN');

  // Campos
  const [pmNumber, setPmNumber] = useState('');
  const [fullName, setFullName] = useState('');
  const [realEmail, setRealEmail] = useState('');

  const [password, setPassword] = useState('');
  const [confirmPassword, setConfirmPassword] = useState(''); // Novo campo de confirmação

  const [sectionCode, setSectionCode] = useState(''); 

  const [showPassword, setShowPassword] = useState(false);
  const [loading, setLoading] = useState(false);
  const [message, setMessage] = useState<{ text: string; type: 'error' | 'success' | 'info' } | null>(null);

  // --- CONFIGURAÇÃO DE SEGURANÇA ---
  const ACCESS_CODE = 'FROTA5RPM'; 

  const shieldUrl = "https://yaoebstgiagmrvlbozny.supabase.co/storage/v1/object/sign/Logo%20PMMG/ESCUDO%20PMMG.png?token=eyJraWQiOiJzdG9yYWdlLXVybC1zaWduaW5nLWtleV9mMjgyNzE5YS0xNjI0LTRiYTUtODk3MC1jNTc3ZDIzMTQ4YjUiLCJhbGciOiJIUzI1NiJ9.eyJ1cmwiOiJMb2dvIFBNTUcvRVNDVURPIFBNTUcucG5nIiwiaWF0IjoxNzY1NDAzMzE0LCJleHAiOjIzOTYxMjMzMTR9.1uAuyEEDpwU_vmvKjnSJw0uYbcOIkB-vRpXRDU-Arss";

  // Validação de PM
  const handlePmChange = (e: React.ChangeEvent<HTMLInputElement>) => {
      const val = e.target.value.replace(/\D/g, '').slice(0, 7);
      setPmNumber(val);
  };

  const handleAuth = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    setMessage(null);

    // Validações Comuns
    if (pmNumber.length < 3) {
        setMessage({ text: "Nº PM inválido.", type: 'error' });
        setLoading(false);
        return;
    }

    try {
      if (mode === 'REGISTER') {
        // --- CADASTRO ---
        if (sectionCode !== ACCESS_CODE) throw new Error("Código de acesso da seção incorreto.");
        if (!fullName.trim()) throw new Error("Informe seu nome completo.");
        if (!realEmail.includes('@')) throw new Error("Informe um e-mail válido.");
        if (password.length < 6) throw new Error("A senha deve ter no mínimo 6 caracteres.");

        // Confirmação de senha no cadastro também é boa prática
        if (password !== confirmPassword) throw new Error("As senhas não conferem.");

        const { data: authData, error: authError } = await supabase.auth.signUp({
          email: realEmail,
          password: password,
          options: {
              data: {
                  full_name: fullName,
                  pm_number: pmNumber
              }
          }
        });

        if (authError) throw authError;

        if (authData.user) {
            try {
                await supabase.from('profiles').upsert({
                    id: authData.user.id,
                    pm_number: pmNumber,
                    email: realEmail,
                    full_name: fullName
                }, { onConflict: 'id' });
            } catch (manualInsertError: any) {
                console.warn("Inserção manual falhou, confiando no Trigger:", manualInsertError);
            }

            setMessage({ text: "Cadastro realizado! Faça login para entrar.", type: 'success' });
            setMode('LOGIN');
            setPassword('');
            setConfirmPassword('');
        }

      } else if (mode === 'LOGIN') {
        // --- LOGIN ---
        // 1. Buscar qual é o e-mail deste PM
        const { data: profiles, error: profileError } = await supabase
            .from('profiles')
            .select('email')
            .eq('pm_number', pmNumber)
            .single();

        if (profileError || !profiles) {
            console.error("Erro busca perfil:", profileError);
            throw new Error("Cadastro não encontrado para este Nº PM. Verifique se digitou corretamente ou cadastre-se.");
        }

        const userEmail = profiles.email;

        // 2. Fazer login com o e-mail encontrado
        const { error: loginError } = await supabase.auth.signInWithPassword({
          email: userEmail,
          password: password,
        });

        if (loginError) throw loginError;

      } else if (mode === 'RECOVERY') {
        // --- RECUPERAÇÃO VIA CÓDIGO MESTRE (RPC) ---
        if (sectionCode !== ACCESS_CODE) throw new Error("Código Mestre da Seção incorreto.");
        if (password.length < 6) throw new Error("A nova senha deve ter no mínimo 6 caracteres.");
        if (password !== confirmPassword) throw new Error("As senhas digitadas não conferem.");

        // Chama a função RPC segura no banco de dados
        const { data: rpcData, error: rpcError } = await supabase.rpc('reset_password_via_pm', {
            target_pm: pmNumber,
            new_password: password,
            secret_code: sectionCode
        });

        if (rpcError) throw rpcError;

        setMessage({ 
            text: "Sucesso! Sua senha foi redefinida. Use-a para entrar agora.", 
            type: 'success' 
        });

        // Retorna para login após sucesso
        setTimeout(() => {
            setMode('LOGIN');
            setPassword('');
            setConfirmPassword('');
        }, 2000);
      }

    } catch (error: any) {
      // --- Tratamento de Erro Robusto ---
      let errorMsg = "Ocorreu um erro desconhecido.";

      if (typeof error === 'string') {
          errorMsg = error;
      } else if (error instanceof Error) {
          errorMsg = error.message;
      } else if (typeof error === 'object' && error !== null) {
          errorMsg = error.message || error.msg || error.error_description || JSON.stringify(error);
      }

      // Mensagens Amigáveis
      if (typeof errorMsg === 'string') {
        if (errorMsg.includes("Invalid login credentials")) errorMsg = "Senha incorreta.";
        if (errorMsg.includes("User already registered")) errorMsg = "Este e-mail já está em uso.";
        if (errorMsg.includes("duplicate key")) errorMsg = "Este Nº PM já possui cadastro.";
        if (errorMsg.includes("row-level security")) errorMsg = "Erro de permissão. Tente recarregar a página.";
        if (mode === 'RECOVERY' && errorMsg.includes("PM não encontrado")) errorMsg = "Este Nº PM não possui cadastro no sistema.";

        if (mode === 'REGISTER' && errorMsg.includes("foreign key constraint")) {
            setMessage({ text: "Cadastro realizado! Faça login para entrar.", type: 'success' });
            setMode('LOGIN');
            setPassword('');
            setConfirmPassword('');
            setLoading(false);
            return;
        }
      }

      setMessage({ text: errorMsg, type: 'error' });
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="min-h-screen bg-[#958458] flex items-center justify-center p-4">
      <div className="bg-[#fdfbf7] p-8 rounded-lg shadow-2xl w-full max-w-md border-t-4 border-pmmg-primary">

        <div className="flex flex-col items-center mb-6">
          <img 
            src={shieldUrl} 
            alt="Brasão PMMG" 
            className="h-24 mb-4 drop-shadow-md"
            style={{ height: '6rem' }}
          />
          <h1 className="text-2xl font-bold text-pmmg-primary text-center">Controles Frota 5ª RPM</h1>
          <p className="text-gray-500 text-sm mt-1 uppercase font-bold tracking-wider">
            {mode === 'REGISTER' && 'Novo Cadastro de Militar'}
            {mode === 'LOGIN' && 'Acesso ao Sistema'}
            {mode === 'RECOVERY' && 'Redefinição de Senha'}
          </p>
        </div>

        <form onSubmit={handleAuth} className="space-y-4">

          {/* Campo Nº PM (Comum a todos) */}
          <div>
            <label className="block text-sm font-bold text-gray-700 mb-1">Nº PM (Login)</label>
            <div className="relative">
              <User className="absolute left-3 top-2.5 h-5 w-5 text-gray-400" />
              <input
                type="text"
                required
                maxLength={9}
                className="w-full pl-10 pr-4 py-2 border rounded-md focus:ring-2 focus:ring-pmmg-primary outline-none tracking-widest font-mono font-bold text-gray-800 text-lg"
                placeholder="Ex: 1234567"
                value={pmNumber}
                onChange={handlePmChange}
                disabled={loading}
              />
            </div>
          </div>

          {/* Campos Específicos de Cadastro */}
          {mode === 'REGISTER' && (
             <div className="space-y-4 animate-fade-in">
                <div>
                    <label className="block text-sm font-bold text-gray-700 mb-1">Nome Completo</label>
                    <input
                        type="text"
                        required
                        className="w-full px-4 py-2 border rounded-md focus:ring-2 focus:ring-pmmg-primary outline-none uppercase"
                        placeholder="Ex: SD FULANO DE TAL"
                        value={fullName}
                        onChange={(e) => setFullName(e.target.value.toUpperCase())}
                    />
                </div>
                <div>
                    <label className="block text-sm font-bold text-gray-700 mb-1">Seu E-mail Real</label>
                    <div className="relative">
                        <Mail className="absolute left-3 top-2.5 h-5 w-5 text-gray-400" />
                        <input
                            type="email"
                            required
                            className="w-full pl-10 pr-4 py-2 border rounded-md focus:ring-2 focus:ring-pmmg-primary outline-none"
                            placeholder="exemplo@gmail.com"
                            value={realEmail}
                            onChange={(e) => setRealEmail(e.target.value)}
                        />
                    </div>
                </div>
             </div>
          )}

          {/* Código de Seção (Cadastro e Recuperação) */}
          {(mode === 'REGISTER' || mode === 'RECOVERY') && (
            <div className="bg-yellow-50 p-3 rounded border border-yellow-200 animate-fade-in mt-4">
                <label className="block text-sm font-bold text-yellow-800 mb-1">
                    Código Mestre da Seção
                </label>
                <div className="relative">
                <KeyRound className="absolute left-3 top-2.5 h-5 w-5 text-yellow-600" />
                <input
                    type="text"
                    required
                    className="w-full pl-10 pr-4 py-2 border border-yellow-300 rounded-md focus:ring-2 focus:ring-pmmg-accent outline-none bg-white text-gray-800 placeholder-gray-400 uppercase font-bold"
                    placeholder="FROTA..."
                    value={sectionCode}
                    onChange={(e) => setSectionCode(e.target.value.toUpperCase())}
                />
                </div>
                <p className="text-[10px] text-yellow-700 mt-1">
                    {mode === 'RECOVERY' 
                     ? '* Obrigatório para autorizar a troca de senha.' 
                     : '* Validação de segurança obrigatória.'}
                </p>
            </div>
          )}

          {/* Campo Senha (Todos os modos usam senha agora) */}
          <div className="animate-fade-in">
            <label className="block text-sm font-bold text-gray-700 mb-1">
                {mode === 'RECOVERY' ? 'Nova Senha' : 'Senha'}
            </label>
            <div className="relative">
            <Lock className="absolute left-3 top-2.5 h-5 w-5 text-gray-400" />
            <input
                type={showPassword ? "text" : "password"}
                required
                minLength={6}
                className="w-full pl-10 pr-10 py-2 border rounded-md focus:ring-2 focus:ring-pmmg-primary outline-none"
                placeholder={mode === 'RECOVERY' ? "Digite a nova senha" : "Sua senha"}
                value={password}
                onChange={(e) => setPassword(e.target.value)}
            />
            <button
                type="button"
                onClick={() => setShowPassword(!showPassword)}
                className="absolute right-3 top-2.5 text-gray-400 hover:text-gray-600 focus:outline-none"
            >
                {showPassword ? <EyeOff size={20} /> : <Eye size={20} />}
            </button>
            </div>
          </div>

          {/* Confirmação de Senha (Cadastro e Recuperação) */}
          {(mode === 'REGISTER' || mode === 'RECOVERY') && (
              <div className="animate-fade-in">
                <label className="block text-sm font-bold text-gray-700 mb-1">
                    Confirme a Senha
                </label>
                <div className="relative">
                    <CheckCircle className={`absolute left-3 top-2.5 h-5 w-5 ${confirmPassword && password === confirmPassword ? 'text-green-500' : 'text-gray-400'}`} />
                    <input
                        type="password"
                        required
                        className={`w-full pl-10 pr-4 py-2 border rounded-md focus:ring-2 outline-none ${
                            confirmPassword && password !== confirmPassword 
                            ? 'border-red-500 focus:ring-red-500' 
                            : 'focus:ring-pmmg-primary'
                        }`}
                        placeholder="Digite a senha novamente"
                        value={confirmPassword}
                        onChange={(e) => setConfirmPassword(e.target.value)}
                    />
                </div>
                {confirmPassword && password !== confirmPassword && (
                    <p className="text-xs text-red-500 mt-1">As senhas não coincidem.</p>
                )}
              </div>
          )}

          {message && (
            <div className={`p-3 rounded text-sm text-center border font-semibold ${
                message.type === 'error' ? 'bg-red-50 text-red-700 border-red-200' : 
                message.type === 'success' ? 'bg-green-50 text-green-700 border-green-200' :
                'bg-blue-50 text-blue-700 border-blue-200'
            }`}>
              {message.text}
            </div>
          )}

          <button
            type="submit"
            disabled={loading}
            className={`w-full text-white font-bold py-3 rounded-md transition-colors flex items-center justify-center gap-2 shadow-lg mt-4 ${
                loading ? 'bg-gray-400 cursor-not-allowed' : 'bg-pmmg-primary hover:bg-[#3E3223]/90'
            }`}
          >
            {loading ? 'Processando...' : (
                mode === 'REGISTER' ? <><UserPlus size={20} /> Confirmar Cadastro</> : 
                mode === 'RECOVERY' ? <><RefreshCw size={20} /> Redefinir Senha</> :
                <><LogIn size={20} /> Entrar</>
            )}
          </button>
        </form>

        <div className="mt-6 pt-4 border-t border-gray-200 flex flex-col gap-3 text-center">
            {mode === 'LOGIN' && (
                <>
                    <button 
                        onClick={() => { setMode('REGISTER'); setMessage(null); setPassword(''); setConfirmPassword(''); setPmNumber(''); setSectionCode(''); setRealEmail(''); setFullName(''); }}
                        className="text-sm font-semibold text-pmmg-primary hover:text-[#C5A059] transition-colors"
                    >
                        Não tem cadastro? Crie sua conta.
                    </button>
                    <button 
                        onClick={() => { setMode('RECOVERY'); setMessage(null); setPassword(''); setConfirmPassword(''); setPmNumber(''); setSectionCode(''); }}
                        className="text-xs text-gray-500 hover:text-red-600 transition-colors flex items-center justify-center gap-1"
                    >
                        <BadgeHelp size={14} /> Esqueci a senha
                    </button>
                </>
            )}

            {(mode === 'REGISTER' || mode === 'RECOVERY') && (
                <button 
                    onClick={() => { setMode('LOGIN'); setMessage(null); setPassword(''); setConfirmPassword(''); }}
                    className="text-sm font-semibold text-gray-600 hover:text-pmmg-primary transition-colors"
                >
                    Voltar para o Login
                </button>
            )}
        </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { Package, Truck, History, LogOut, Home, KeyRound } from 'lucide-react';
import { InventoryTab } from './components/InventoryTab';
import { MovementsTab } from './components/MovementsTab';
import { FleetTab } from './components/FleetTab';
import { checkConnection, supabase } from './lib/supabase';
import { DatabaseSetup } from './components/DatabaseSetup';
import { LoginScreen } from './components/LoginScreen';
import { DashboardSelection } from './components/DashboardSelection';
import { PavModule } from './components/PavModule';
import { Tab } from './types';

// Tipos de módulo disponíveis
type ModuleType = 'STOCK' | 'PAV' | null;

function App() {
  const [activeTab, setActiveTab] = useState<Tab>('inventory');
  const [currentModule, setCurrentModule] = useState<ModuleType>(null);
  const [isConnected, setIsConnected] = useState<boolean | null>(null);

  // Estados de Autenticação
  const [session, setSession] = useState<any>(null);
  const [authLoading, setAuthLoading] = useState(true);

  // Estado Modal Alterar Senha (Logado)
  const [isPasswordModalOpen, setIsPasswordModalOpen] = useState(false);
  const [newPassword, setNewPassword] = useState('');
  const [confirmPassword, setConfirmPassword] = useState(''); // Confirmação
  const [passwordMsg, setPasswordMsg] = useState<{text: string, type: 'success'|'error'} | null>(null);

  useEffect(() => {
    // 1. Verificar conexão com banco
    checkConnection().then(setIsConnected);

    // 2. Verificar Sessão Supabase
    supabase.auth.getSession().then(({ data: { session } }) => {
      setSession(session);
      setAuthLoading(false);

      // Se tiver token na URL, limpa
      if (window.location.hash && window.location.hash.includes('access_token')) {
          window.history.replaceState(null, '', window.location.pathname);
      }
    });

    // 3. Ouvir mudanças na autenticação Supabase
    const { data: { subscription } } = supabase.auth.onAuthStateChange((event, session) => {
      setSession(session);
      setAuthLoading(false);

      // Limpeza de URL
      if (window.location.hash && window.location.hash.includes('access_token')) {
          window.history.replaceState(null, '', window.location.pathname);
      }
    });

    return () => subscription.unsubscribe();
  }, []);

  // Função Unificada de Logout
  const handleLogout = async () => {
    await supabase.auth.signOut();
    setSession(null);
    setCurrentModule(null);
    setActiveTab('inventory');
  };

  // Função para alterar senha (usuário logado)
  const handleChangePassword = async () => {
    if (newPassword.length < 6) {
        setPasswordMsg({ text: "A senha deve ter no mínimo 6 caracteres.", type: 'error' });
        return;
    }

    if (newPassword !== confirmPassword) {
        setPasswordMsg({ text: "As senhas não conferem.", type: 'error' });
        return;
    }

    try {
        const { error } = await supabase.auth.updateUser({ password: newPassword });
        if (error) throw error;
        setPasswordMsg({ text: "Senha alterada com sucesso!", type: 'success' });
        setTimeout(() => {
            setIsPasswordModalOpen(false);
            setNewPassword('');
            setConfirmPassword('');
            setPasswordMsg(null);
        }, 1500);
    } catch (err: any) {
        setPasswordMsg({ text: "Erro ao alterar senha: " + err.message, type: 'error' });
    }
  };

  // ----- RENDERING FLOW -----

  // 1. Tela de Carregamento
  if (authLoading) {
     return (
        <div className="min-h-screen bg-[#958458] flex items-center justify-center">
            <div className="text-white font-bold text-xl animate-pulse">Carregando sistema...</div>
        </div>
     );
  }

  // 2. Tela de Login (Se não tiver sessão Supabase)
  if (!session) {
    return <LoginScreen />;
  }

  // 3. Configuração de Banco (apenas se conectado e houver erro de conexão com tabelas)
  if (isConnected === false) {
    return <DatabaseSetup />;
  }

  // Recupera nome dos metadados ou usa o email
  const userFullName = session?.user?.user_metadata?.full_name || session?.user?.email || 'Militar';

  // 4. Tela de Seleção de Módulo (Dashboard)
  if (!currentModule) {
    return (
      <>
        <DashboardSelection 
          onSelectModule={setCurrentModule} 
          userEmail={userFullName} 
          onLogout={handleLogout}
          onChangePassword={() => setIsPasswordModalOpen(true)}
        />
        {/* Modal de Senha (Renderizado globalmente se necessário aqui) */}
        {isPasswordModalOpen && (
            <div className="fixed inset-0 bg-black/70 backdrop-blur-sm flex items-center justify-center z-[90] p-4">
                <div className="bg-white p-6 rounded-lg shadow-2xl w-full max-w-sm border-t-4 border-[#C5A059]">
                    <h3 className="text-lg font-bold text-[#3E3223] mb-4 flex items-center gap-2">
                        <KeyRound size={20} className="text-[#C5A059]" />
                        Nova Senha
                    </h3>

                    <div className="space-y-4">
                        <div>
                            <label className="block text-sm font-bold text-gray-700 mb-1">Nova Senha</label>
                            <input 
                                type="password"
                                className="w-full border p-2 rounded focus:ring-2 focus:ring-[#C5A059] outline-none"
                                placeholder="Mínimo 6 caracteres"
                                value={newPassword}
                                onChange={e => setNewPassword(e.target.value)}
                            />
                        </div>

                        <div>
                            <label className="block text-sm font-bold text-gray-700 mb-1">Confirmar Senha</label>
                            <input 
                                type="password"
                                className={`w-full border p-2 rounded focus:ring-2 outline-none ${
                                    confirmPassword && newPassword !== confirmPassword ? 'border-red-500' : 'focus:ring-[#C5A059]'
                                }`}
                                placeholder="Digite novamente"
                                value={confirmPassword}
                                onChange={e => setConfirmPassword(e.target.value)}
                            />
                        </div>

                        {passwordMsg && (
                            <div className={`text-sm p-2 rounded ${
                                passwordMsg.type === 'success' ? 'bg-green-100 text-green-800' : 'bg-red-100 text-red-800'
                            }`}>
                                {passwordMsg.text}
                            </div>
                        )}

                        <div className="flex justify-end gap-2 pt-2">
