    if (hasConflict) {
        alert(`CONFLITO DETECTADO!\n\nA viatura ${formData.vehicle_prefix} já possui um agendamento que coincide com este horário (${formData.start_hour} - ${formData.end_hour}).\n\nPor favor, verifique a agenda e escolha outro horário ou viatura.`);
        return;
    }

    try {
        const payload = {
            vehicle_prefix: formData.vehicle_prefix,
            driver_name: formData.driver_name.toUpperCase(),
            reason: formData.reason,
            start_time: startDateTime.toISOString(),
            end_time: endDateTime.toISOString(),
            observations: formData.observations
        };

        const { error } = await supabase.from('vehicle_schedules').insert([payload]);

        if (error) throw error;

        alert("Agendamento realizado com sucesso!");
        setIsModalOpen(false);
        setFormData(initialForm);
        fetchData();

    } catch (e: any) {
        const msg = e.message || JSON.stringify(e);
        alert(`Erro ao salvar: ${msg}`);
    }
  };

  const confirmDelete = async () => {
      if (!deletingId) return;
      try {
          const { error } = await supabase.from('vehicle_schedules').delete().eq('id', deletingId);
          if (error) throw error;
          fetchData();
      } catch (e: any) {
          const msg = e.message || JSON.stringify(e);
          alert(`Erro ao excluir: ${msg}`);
      } finally {
          setDeletingId(null);
      }
