                        <button onClick={confirmDeleteSchedule} className="px-4 py-2 bg-red-600 text-white rounded hover:bg-red-700 font-bold">Sim, Excluir</button>
                    </div>
                </div>
            </div>
        )}

      </main>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { Home, CalendarClock, Plus, Search, Trash2, LogOut, Car, User, Clock, AlertTriangle, Info, Truck, Edit, Settings, Filter, CheckSquare, Square, XCircle } from 'lucide-react';
