            .order('prefix');

        if (vError) throw vError;
        setVehicles(vData || []);

    } catch (error: any) {
        console.error("Erro ao buscar dados:", error);
        const msg = error.message || (typeof error === 'object' ? JSON.stringify(error) : String(error));
