          styles: { fontSize: 8 },
      });

      doc.save("Agenda_Viaturas_5RPM.pdf");
  };

  const handleImportExcel = async (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      try {
        const data = await parseExcel(e.target.files[0]);

        // Função auxiliar para buscar chaves
        const findValue = (row: any, searchKeys: string[]) => {
            const objectKeys = Object.keys(row);
            for (const searchKey of searchKeys) {
                const foundKey = objectKeys.find(k => k.toLowerCase().includes(searchKey.toLowerCase()));
                if (foundKey) return row[foundKey];
            }
            return undefined;
        };

        const formattedData: any[] = [];
        let errors = 0;

        for (const row of data) {
            const prefix = findValue(row, ['viatura', 'prefixo']);
            const driver = findValue(row, ['motorista', 'condutor', 'responsavel']);
            const reason = findValue(row, ['motivo', 'destino', 'missao']);

            // Tratamento de Data e Hora
            // Formatos esperados:
            // Data: "2023-12-25" ou "25/12/2023" ou Objeto Date do Excel
            // Hora: "08:00" ou frações decimais

            let dateRaw = findValue(row, ['data', 'dia']);
            let startRaw = findValue(row, ['inicio', 'saida']);
            let endRaw = findValue(row, ['fim', 'chegada', 'retorno']);

            if (!prefix || !driver || !dateRaw || !startRaw || !endRaw) {
                errors++;
                continue;
            }

            try {
                // Normalizar Data
                let dateStr = '';
                if (dateRaw instanceof Date) {
                    dateStr = dateRaw.toISOString().split('T')[0];
                } else if (typeof dateRaw === 'string') {
                    if (dateRaw.includes('/')) {
                        const parts = dateRaw.split('/');
                        // Assume DD/MM/YYYY
                        dateStr = `${parts[2]}-${parts[1]}-${parts[0]}`;
                    } else {
                        dateStr = dateRaw; // Assume ISO
                    }
                }

                // Normalizar Hora (Simplificado para HH:MM string)
                // Se for fração do Excel, converter seria complexo sem libs, assumimos string "HH:MM"
                const normalizeTime = (val: any) => {
                   if (val instanceof Date) return val.toLocaleTimeString('pt-BR', {hour: '2-digit', minute:'2-digit'});
                   return String(val).trim();
                };

                const sTime = normalizeTime(startRaw);
                const eTime = normalizeTime(endRaw);

                const startDateTime = new Date(`${dateStr}T${sTime}:00`);
                const endDateTime = new Date(`${dateStr}T${eTime}:00`);

                if (isNaN(startDateTime.getTime()) || isNaN(endDateTime.getTime())) {
                    errors++;
                    continue;
                }

                formattedData.push({
                    vehicle_prefix: prefix,
                    driver_name: String(driver).toUpperCase(),
                    reason: String(reason || 'Importado'),
                    start_time: startDateTime.toISOString(),
                    end_time: endDateTime.toISOString(),
                    observations: 'Importado via Excel'
                });

            } catch (err) {
