                            >
                                Cancelar
                            </button>
                            <button 
                                onClick={() => handleSaveSchedule(false)}
                                className="px-6 py-2 bg-[#3E3223] text-white rounded hover:bg-[#2a2218] shadow-md font-bold transition-colors"
