import React, { useState, useEffect } from 'react';
import { Home, Plus, Search, Edit, Trash2, LogOut, RefreshCw, Car, ArrowRight, AlertCircle, CheckCircle, XCircle, BarChart3, Clock, Check } from 'lucide-react';
import { supabase } from '../lib/supabase';
