             <p className="text-lg font-bold text-[#C5A059] opacity-90 tracking-widest font-serif">FROTA 5ª RPM</p>
             <div className="text-right mt-1">
                 <span className="text-sm font-semibold text-white/90">Bem-vindo, {userEmail}</span>
