                        <button onClick={confirmDelete} className="px-4 py-2 bg-red-600 text-white rounded hover:bg-red-700 font-bold">Sim, Excluir</button>
                    </div>
                </div>
            </div>
        )}

        {/* Modal Formulário */}
        {isModalOpen && (
            <div className="fixed inset-0 bg-black/60 backdrop-blur-sm flex items-center justify-center z-50 p-4 overflow-y-auto">
                <div className="bg-white rounded-lg shadow-2xl w-full max-w-2xl border-t-8 border-[#C5A059] animate-fade-in my-8">
                    <div className="p-6">
