                            <div className="grid grid-cols-2 gap-4">
                                <div>
                                    <label className="block text-[10px] font-black text-gray-500 uppercase mb-1">Prefixo</label>
                                    <input className="w-full border-2 border-green-100 p-3 rounded-lg focus:border-green-500 outline-none bg-white font-bold" value={formData.received_prefix} onChange={e => setFormData({...formData, received_prefix: e.target.value})} placeholder="Ex: 12345" />
                                </div>
                                <div>
                                    <label className="block text-[10px] font-black text-gray-500 uppercase mb-1">Placa</label>
                                    <input className="w-full border-2 border-green-100 p-3 rounded-lg focus:border-green-500 outline-none bg-white uppercase font-mono font-bold" value={formData.received_plate} onChange={e => setFormData({...formData, received_plate: e.target.value})} placeholder="ABC-1234" />
                                </div>
                                <div>
                                    <label className="block text-[10px] font-black text-gray-500 uppercase mb-1">Marca/Modelo</label>
                                    <input className="w-full border-2 border-green-100 p-3 rounded-lg focus:border-green-500 outline-none bg-white" value={formData.received_model} onChange={e => setFormData({...formData, received_model: e.target.value})} />
                                </div>
                                <div>
                                    <label className="block text-[10px] font-black text-gray-500 uppercase mb-1">BGPM</label>
                                    <input className="w-full border-2 border-green-100 p-3 rounded-lg focus:border-green-500 outline-none bg-white font-mono" value={formData.received_bgpm} onChange={e => setFormData({...formData, received_bgpm: e.target.value})} placeholder="N° BGPM" />
                                </div>
                            </div>
                        </div>

                        <div className="flex justify-center -my-4 relative z-10">
                            <div className="bg-[#C5A059] text-white p-3 rounded-full shadow-xl border-4 border-white">
                                <ArrowRight size={24} className="transform rotate-90 md:rotate-0" />
                            </div>
                        </div>

                        <div className="bg-gray-100 p-5 rounded-lg border-2 border-dashed border-gray-300 mt-4 shadow-inner">
                            <h3 className="font-black text-gray-600 mb-4 flex items-center gap-2 text-xs uppercase tracking-tighter">
                                <Car size={16} /> 2. Viatura Indicada (Preencher se houver)
                            </h3>
                            <div className="grid grid-cols-2 gap-4">
                                <div>
                                    <label className="block text-[10px] font-black text-gray-400 uppercase mb-1">Prefixo (Substituta)</label>
                                    <input className="w-full border-2 border-gray-200 p-3 rounded-lg focus:border-gray-400 outline-none bg-white font-bold" value={formData.indicated_prefix} onChange={e => setFormData({...formData, indicated_prefix: e.target.value})} placeholder="Pendente..." />
                                </div>
                                <div>
                                    <label className="block text-[10px] font-black text-gray-400 uppercase mb-1">Placa (Substituta)</label>
                                    <input className="w-full border-2 border-gray-200 p-3 rounded-lg focus:border-gray-400 outline-none bg-white uppercase font-mono font-bold" value={formData.indicated_plate} onChange={e => setFormData({...formData, indicated_plate: e.target.value})} placeholder="Pendente..." />
                                </div>
                            </div>
                        </div>

                        <div className="flex justify-end gap-3 mt-8 pt-4 border-t border-gray-100">
                            <button onClick={() => setIsModalOpen(false)} className="px-8 py-3 text-gray-600 hover:bg-gray-100 rounded-lg border font-bold transition-all">Cancelar</button>
                            <button onClick={handleSave} className="px-10 py-3 bg-[#3E3223] text-[#C5A059] rounded-lg hover:bg-[#2a2218] shadow-lg font-black uppercase tracking-widest transition-all transform hover:scale-105">Salvar Registro</button>
                        </div>
                    </div>
                </div>
            </div>
        )}
      </main>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { Home, Plus, Search, Edit, Trash2, LogOut, RefreshCw, Car, ArrowRight, AlertCircle, CheckCircle, XCircle, BarChart3, Clock, Check, FileUp, FileDown } from 'lucide-react';
import { supabase } from '../lib/supabase';
import { FleetSubstitution } from '../types';
import { exportToExcel, parseExcel } from '../utils/excel';

interface FleetSubstitutionModuleProps {
  onBack: () => void;
  userEmail: string;
  onLogout: () => void;
}

export const FleetSubstitutionModule: React.FC<FleetSubstitutionModuleProps> = ({ onBack, userEmail, onLogout }) => {
  const shieldUrl = "https://yaoebstgiagmrvlbozny.supabase.co/storage/v1/object/sign/Logo%20PMMG/ESCUDO%20PMMG.png?token=eyJraWQiOiJzdG9yYWdlLXVybC1zaWduaW5nLWtleV9mMjgyNzE5YS0xNjI0LTRiYTUtODk3MC1jNTc3ZDIzMTQ4YjUiLCJhbGciOiJIUzI1NiJ9.eyJ1cmwiOiJMb2dvIFBNTUcvRVNDVURPIFBNTUcucG5nIiwiaWF0IjoxNzY1NDAzMzE0LCJleHAiOjIzOTYxMjMzMTR9.1uAuyEEDpwU_vmvKjnSJw0uYbcOIkB-vRpXRDU-Arss";

  // Estados
  const [substitutions, setSubstitutions] = useState<FleetSubstitution[]>([]);
  const [loading, setLoading] = useState(true);
  const [search, setSearch] = useState('');

  // Modais
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingId, setEditingId] = useState<string | null>(null);
  const [deletingId, setDeletingId] = useState<string | null>(null);

  // Formulário
  const initialForm = {
      received_prefix: '',
      received_plate: '',
      received_model: '',
      received_bgpm: '',
      indicated_prefix: '',
      indicated_plate: ''
  };
  const [formData, setFormData] = useState(initialForm);

  // Fetch
  const fetchData = async () => {
    setLoading(true);
    const { data, error } = await supabase
        .from('fleet_substitutions')
        .select('*')
        .order('created_at', { ascending: false });

    if (error) {
        console.error("Erro ao buscar dados:", error);
        alert("Erro ao carregar dados. Verifique se executou o script SQL.");
    } else {
        setSubstitutions(data || []);
    }
    setLoading(false);
  };

  useEffect(() => {
    fetchData();
  }, []);

  // Estatísticas
  const stats = {
    total: substitutions.length,
    pending: substitutions.filter(s => !s.indicated_prefix || !s.indicated_plate).length,
    completed: substitutions.filter(s => s.indicated_prefix && s.indicated_plate).length
  };

  // Importar Excel
  const handleImport = async (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      setLoading(true);
      try {
        const data = await parseExcel(e.target.files[0]);

        // Função auxiliar para buscar chave ignorando maiúsculas/minúsculas e espaços
        const findValue = (row: any, searchKeys: string[]) => {
            const objectKeys = Object.keys(row);
            for (const searchKey of searchKeys) {
                const foundKey = objectKeys.find(k => k.toLowerCase().trim().includes(searchKey.toLowerCase()));
                if (foundKey) return row[foundKey];
            }
            return undefined;
        };

        const formattedData = data.map((row: any) => {
            const r_prefix = String(findValue(row, ['prefixo recebido', 'prefixo_recebido', 'prefixo']) || '').trim();
            const r_plate = String(findValue(row, ['placa recebida', 'placa_recebida', 'placa']) || '').toUpperCase().trim();

            return {
                received_prefix: r_prefix,
                received_plate: r_plate,
                received_model: findValue(row, ['modelo recebido', 'marca', 'modelo']) || '',
                received_bgpm: findValue(row, ['bgpm', 'n bgpm']) || '',
                indicated_prefix: findValue(row, ['prefixo indicado', 'indicada', 'prefixo_substituta']) || null,
                indicated_plate: String(findValue(row, ['placa indicada', 'placa_substituta']) || '').toUpperCase() || null
            };
        }).filter(r => r.received_prefix && r.received_plate); // Filtra linhas que tenham prefixo e placa da recebida

        if (formattedData.length > 0) {
          const { error } = await supabase.from('fleet_substitutions').insert(formattedData);
          if (error) throw error;
          alert(`${formattedData.length} registros de substituição importados com sucesso!`);
          fetchData();
        } else {
          alert("Nenhum dado válido encontrado. Certifique-se de que a planilha tem colunas para 'Prefixo' e 'Placa'.");
        }
      } catch (err: any) {
        alert(`Erro ao importar: ${err.message || 'Verifique o formato do arquivo.'}`);
        console.error(err);
      } finally {
        setLoading(false);
        e.target.value = ''; // Limpa o input
      }
    }
  };

  // Salvar (Inserir ou Atualizar)
  const handleSave = async () => {
    if (!formData.received_prefix || !formData.received_plate) {
        alert("Prefixo e Placa da viatura RECEBIDA são obrigatórios.");
        return;
    }

    const payload = {
        received_prefix: formData.received_prefix,
        received_plate: formData.received_plate.toUpperCase(),
        received_model: formData.received_model,
        received_bgpm: formData.received_bgpm,
        indicated_prefix: formData.indicated_prefix || null,
        indicated_plate: formData.indicated_plate ? formData.indicated_plate.toUpperCase() : null
    };

    try {
        if (editingId) {
            const { error } = await supabase.from('fleet_substitutions').update(payload).eq('id', editingId);
            if (error) throw error;
            alert("Registro atualizado com sucesso!");
        } else {
            const { error } = await supabase.from('fleet_substitutions').insert([payload]);
            if (error) throw error;
            alert("Substituição registrada com sucesso!");
        }

        setIsModalOpen(false);
        setEditingId(null);
        setFormData(initialForm);
        fetchData();
    } catch (e: any) {
        alert("Erro ao salvar: " + e.message);
    }
  };

  const confirmDelete = async () => {
      if (!deletingId) return;
      try {
          const { error } = await supabase.from('fleet_substitutions').delete().eq('id', deletingId);
          if (error) throw error;
          fetchData();
      } catch (e: any) {
          alert("Erro ao excluir: " + e.message);
      } finally {
          setDeletingId(null);
      }
  };

  const openModal = (item?: FleetSubstitution) => {
      if (item) {
          setEditingId(item.id);
          setFormData({
              received_prefix: item.received_prefix,
              received_plate: item.received_plate,
              received_model: item.received_model || '',
              received_bgpm: item.received_bgpm || '',
              indicated_prefix: item.indicated_prefix || '',
              indicated_plate: item.indicated_plate || ''
          });
      } else {
          setEditingId(null);
          setFormData(initialForm);
      }
      setIsModalOpen(true);
  };

  const handleExport = () => {
      const dataToExport = filteredItems.map(item => ({
          "Data de Lançamento": item.created_at ? new Date(item.created_at).toLocaleDateString('pt-BR') : '-',
          "RECEBIDA - Prefixo": item.received_prefix,
          "RECEBIDA - Placa": item.received_plate,
          "RECEBIDA - Modelo": item.received_model,
          "RECEBIDA - BGPM": item.received_bgpm,
          "INDICADA - Prefixo": item.indicated_prefix || 'Pendente',
          "INDICADA - Placa": item.indicated_plate || 'Pendente',
          "Status": (item.indicated_prefix && item.indicated_plate) ? 'Concluído' : 'Pendente'
      }));
      exportToExcel(dataToExport, 'Substituicoes_Frota_5RPM');
  };

  // Filtragem
  const filteredItems = substitutions.filter(item => 
      item.received_prefix.includes(search) || 
      item.received_plate.toLowerCase().includes(search.toLowerCase()) ||
      (item.indicated_prefix || '').includes(search) ||
      (item.indicated_plate || '').toLowerCase().includes(search.toLowerCase()) ||
      (item.received_bgpm || '').toLowerCase().includes(search.toLowerCase())
  );

  return (
