                                        <input className="w-full border-2 border-green-100 p-2.5 pl-9 rounded-lg focus:border-green-500 outline-none text-sm" value={formData.received_unit} onChange={e => setFormData({...formData, received_unit: e.target.value})} placeholder="Ex: 4 BPM" />
