import React, { useState, useEffect } from 'react';
import { Home, Plus, Search, Edit, Trash2, LogOut, RefreshCw, Car, ArrowRight, AlertCircle, CheckCircle, XCircle, BarChart3, Clock, Check, FileUp, FileDown, MapPin, Building2, Calendar } from 'lucide-react';
import { supabase } from '../lib/supabase';
import { FleetSubstitution } from '../types';
import { exportToExcel, parseExcel } from '../utils/excel';
import * as XLSX from 'xlsx';

interface FleetSubstitutionModuleProps {
  onBack: () => void;
  userEmail: string;
  onLogout: () => void;
}

export const FleetSubstitutionModule: React.FC<FleetSubstitutionModuleProps> = ({ onBack, userEmail, onLogout }) => {
  const shieldUrl = "https://yaoebstgiagmrvlbozny.supabase.co/storage/v1/object/sign/Logo%20PMMG/ESCUDO%20PMMG.png?token=eyJraWQiOiJzdG9yYWdlLXVybC1zaWduaW5nLWtleV9mMjgyNzE5YS0xNjI0LTRiYTUtODk3MC1jNTc3ZDIzMTQ4YjUiLCJhbGciOiJIUzI1NiJ9.eyJ1cmwiOiJMb2dvIFBNTUcvRVNDVURPIFBNTUcucG5nIiwiaWF0IjoxNzY1NDAzMzE0LCJleHAiOjIzOTYxMjMzMTR9.1uAuyEEDpwU_vmvKjnSJw0uYbcOIkB-vRpXRDU-Arss";

  // Estados
  const [substitutions, setSubstitutions] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const [search, setSearch] = useState('');

  // Modais
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingId, setEditingId] = useState<string | null>(null);
  const [deletingId, setDeletingId] = useState<string | null>(null);

  // Formulário
  const initialForm = {
      received_prefix: '',
      received_plate: '',
      received_model: '',
      received_bgpm: '',
      received_year: '',
      received_city: '',
      received_unit: '',
      indicated_prefix: '',
      indicated_plate: ''
  };
  const [formData, setFormData] = useState(initialForm);

  // Fetch
  const fetchData = async () => {
    setLoading(true);
    const { data, error } = await supabase
        .from('fleet_substitutions')
        .select('*')
        .order('created_at', { ascending: false });

    if (error) {
        console.error("Erro ao buscar dados:", error);
        alert("Erro ao carregar dados.");
    } else {
        setSubstitutions(data || []);
    }
    setLoading(false);
  };

  useEffect(() => {
    fetchData();
  }, []);

  // Estatísticas
  const stats = {
    total: substitutions.length,
    pending: substitutions.filter(s => !s.indicated_prefix || !s.indicated_plate).length,
    completed: substitutions.filter(s => s.indicated_prefix && s.indicated_plate).length
  };

  // Importar Excel (Lógica Especial para a Planilha da Imagem)
  const handleImport = async (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      setLoading(true);
      const file = e.target.files[0];

      const reader = new FileReader();
      reader.onload = async (evt) => {
        try {
          const bstr = evt.target?.result;
          const wb = XLSX.read(bstr, { type: 'binary' });
          const wsname = wb.SheetNames[0];
          const ws = wb.Sheets[wsname];

          // Converte ignorando a primeira linha (VIATURA RECEBIDA) e tratando colunas duplicadas
          // range: 1 faz o XLSX ler a partir da segunda linha (onde estão os títulos reais)
          const data: any[] = XLSX.utils.sheet_to_json(ws, { range: 1 });

          const formattedData = data.map((row: any) => {
            // No sheet_to_json, se houver colunas duplicadas, o XLSX adiciona _1, _2...
            // Mapeamento baseado na ordem da imagem:
            // Ano | BGPM | Prefixo | Placa | Marca/Modelo | Município | Unidade | Prefixo(_1) | Placa(_1)

            return {
              received_year: String(row["Ano"] || '').trim(),
              received_bgpm: String(row["BGPM"] || '').trim(),
              received_prefix: String(row["Prefixo"] || '').trim(),
              received_plate: String(row["Placa"] || '').toUpperCase().trim(),
              received_model: String(row["Marca/Modelo/Ano"] || '').trim(),
              received_city: String(row["Município de destino"] || '').trim(),
              received_unit: String(row["Unidade"] || '').trim(),
              // Pega a segunda ocorrência de Prefixo/Placa (Viatura Indicada)
              indicated_prefix: String(row["Prefixo_1"] || '').trim() || null,
              indicated_plate: String(row["Placa_1"] || '').toUpperCase().trim() || null
            };
          }).filter(r => r.received_prefix && r.received_prefix !== 'undefined');

          if (formattedData.length > 0) {
            const { error } = await supabase.from('fleet_substitutions').insert(formattedData);
            if (error) throw error;
            alert(`${formattedData.length} registros da planilha importados com sucesso!`);
            fetchData();
          } else {
            alert("Nenhum dado válido encontrado na planilha. Verifique se os títulos das colunas na Linha 2 estão corretos.");
          }
        } catch (err: any) {
          alert(`Erro no processamento: ${err.message}`);
        } finally {
          setLoading(false);
          e.target.value = '';
        }
      };
      reader.readAsBinaryString(file);
    }
  };

  const handleSave = async () => {
    if (!formData.received_prefix || !formData.received_plate) {
        alert("Prefixo e Placa da viatura RECEBIDA são obrigatórios.");
        return;
    }

    const payload = {
        received_prefix: formData.received_prefix,
        received_plate: formData.received_plate.toUpperCase(),
        received_model: formData.received_model,
        received_bgpm: formData.received_bgpm,
        received_year: formData.received_year,
        received_city: formData.received_city,
        received_unit: formData.received_unit,
        indicated_prefix: formData.indicated_prefix || null,
        indicated_plate: formData.indicated_plate ? formData.indicated_plate.toUpperCase() : null
    };

    try {
        if (editingId) {
            const { error } = await supabase.from('fleet_substitutions').update(payload).eq('id', editingId);
            if (error) throw error;
            alert("Registro atualizado com sucesso!");
        } else {
            const { error } = await supabase.from('fleet_substitutions').insert([payload]);
            if (error) throw error;
            alert("Substituição registrada com sucesso!");
        }

        setIsModalOpen(false);
        setEditingId(null);
        setFormData(initialForm);
        fetchData();
    } catch (e: any) {
        alert("Erro ao salvar: " + e.message);
    }
  };

  const confirmDelete = async () => {
      if (!deletingId) return;
      try {
          const { error } = await supabase.from('fleet_substitutions').delete().eq('id', deletingId);
          if (error) throw error;
          fetchData();
      } catch (e: any) {
          alert("Erro ao excluir: " + e.message);
      } finally {
          setDeletingId(null);
      }
  };

  const openModal = (item?: any) => {
      if (item) {
          setEditingId(item.id);
          setFormData({
              received_prefix: item.received_prefix,
              received_plate: item.received_plate,
              received_model: item.received_model || '',
              received_bgpm: item.received_bgpm || '',
              received_year: item.received_year || '',
              received_city: item.received_city || '',
              received_unit: item.received_unit || '',
              indicated_prefix: item.indicated_prefix || '',
              indicated_plate: item.indicated_plate || ''
          });
      } else {
          setEditingId(null);
          setFormData(initialForm);
      }
      setIsModalOpen(true);
  };

  const handleExport = () => {
      const dataToExport = filteredItems.map(item => ({
          "Data de Lançamento": item.created_at ? new Date(item.created_at).toLocaleDateString('pt-BR') : '-',
          "Ano": item.received_year,
          "BGPM": item.received_bgpm,
          "RECEBIDA - Prefixo": item.received_prefix,
          "RECEBIDA - Placa": item.received_plate,
          "RECEBIDA - Modelo": item.received_model,
          "RECEBIDA - Município": item.received_city,
          "RECEBIDA - Unidade": item.received_unit,
          "INDICADA - Prefixo": item.indicated_prefix || 'Pendente',
          "INDICADA - Placa": item.indicated_plate || 'Pendente',
          "Status": (item.indicated_prefix && item.indicated_plate) ? 'Concluído' : 'Pendente'
      }));
      exportToExcel(dataToExport, 'Substituicoes_Frota_5RPM');
  };

  const filteredItems = substitutions.filter(item => 
      item.received_prefix.includes(search) || 
      item.received_plate.toLowerCase().includes(search.toLowerCase()) ||
      (item.received_city || '').toLowerCase().includes(search.toLowerCase()) ||
      (item.received_unit || '').toLowerCase().includes(search.toLowerCase()) ||
      (item.indicated_prefix || '').includes(search)
  );

  return (
    <div className="min-h-screen bg-[#958458] font-sans flex flex-col">
       <header className="bg-[#3E3223] shadow-lg sticky top-0 z-40 border-b-4 border-[#C5A059]">
        <div className="container mx-auto px-4 h-32 flex items-center justify-between">
          <div className="flex items-center gap-4 py-2">
             <button onClick={onBack} className="flex flex-col items-center justify-center text-[#C5A059] hover:text-white transition-colors bg-white/5 hover:bg-white/10 p-2 rounded-lg">
                <Home size={20} />
                <span className="text-[10px] uppercase font-bold mt-1">Menu</span>
             </button>
             <img src={shieldUrl} alt="Escudo" className="h-28 drop-shadow-xl" />
