  // Estados
  const [substitutions, setSubstitutions] = useState<FleetSubstitution[]>([]);
  const [loading, setLoading] = useState(true);
  const [search, setSearch] = useState('');

  // Modais
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingId, setEditingId] = useState<string | null>(null);
  const [deletingId, setDeletingId] = useState<string | null>(null);

  // Formulário
  const initialForm = {
      received_prefix: '',
      received_plate: '',
      received_model: '',
      received_bgpm: '',
      received_city: '',
      received_unit: '',
      indicated_prefix: '',
      indicated_plate: ''
  };
  const [formData, setFormData] = useState(initialForm);

  // Fetch
  const fetchData = async () => {
    setLoading(true);
    const { data, error } = await supabase
        .from('fleet_substitutions')
        .select('*')
        .order('created_at', { ascending: false });

    if (error) {
        console.error("Erro ao buscar dados:", error);
    } else {
        setSubstitutions(data || []);
    }
    setLoading(false);
  };

  useEffect(() => {
    fetchData();
  }, []);

  // Estatísticas
  const stats = {
    total: substitutions.length,
    pending: substitutions.filter(s => !s.indicated_prefix || !s.indicated_plate).length,
    completed: substitutions.filter(s => s.indicated_prefix && s.indicated_plate).length
  };

  // Importar Excel (Lógica Inteligente por Índice de Coluna)
  const handleImport = async (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      setLoading(true);
      const file = e.target.files[0];

      const reader = new FileReader();
      reader.onload = async (evt) => {
        try {
          const bstr = evt.target?.result;
          const wb = XLSX.read(bstr, { type: 'binary' });
          const wsname = wb.SheetNames[0];
          const ws = wb.Sheets[wsname];

          // Converte para matriz bruta (Array de Arrays) para lidar com duplicatas manualmente
          const rows: any[][] = XLSX.utils.sheet_to_json(ws, { header: 1 });

          if (rows.length < 2) {
              throw new Error("A planilha parece estar vazia.");
          }

          // 1. Encontrar a linha do cabeçalho real (onde estão BGPM, Prefixo, Placa)
          let headerRowIndex = -1;
          for (let i = 0; i < Math.min(rows.length, 10); i++) {
              const rowStr = rows[i].map(c => String(c || '').toUpperCase().trim());
              if (rowStr.includes('PREFIXO') && rowStr.includes('PLACA') && rowStr.includes('BGPM')) {
                  headerRowIndex = i;
                  break;
              }
          }

          if (headerRowIndex === -1) {
              throw new Error("Não foi possível encontrar as colunas 'BGPM', 'Prefixo' e 'Placa' na planilha. Verifique os títulos na Linha 2.");
          }

          const headers = rows[headerRowIndex].map(c => String(c || '').toUpperCase().trim());

          // 2. Mapear índices das colunas (lidando com duplicatas de Prefixo/Placa)
          const findOccurrences = (arr: string[], target: string) => 
              arr.reduce((acc: number[], val, i) => (val === target ? [...acc, i] : acc), []);

          const prefIndices = findOccurrences(headers, 'PREFIXO');
          const placIndices = findOccurrences(headers, 'PLACA');
          const bgpmIndex = headers.indexOf('BGPM');
          const modelIndex = headers.findIndex(h => h.includes('MARCA') || h.includes('MODELO'));
          const cityIndex = headers.findIndex(h => h.includes('MUNICÍPIO') || h.includes('DESTINO'));
          const unitIndex = headers.indexOf('UNIDADE');

          // 3. Processar dados a partir da linha seguinte ao cabeçalho
          const formattedData = rows.slice(headerRowIndex + 1).map((row) => {
              const getVal = (idx: number) => idx !== -1 ? String(row[idx] || '').trim() : '';

              // Se houver dois prefixos, o segundo é a indicada
              const prefRec = getVal(prefIndices[0]);
              const prefInd = prefIndices.length > 1 ? getVal(prefIndices[1]) : '';

              const placRec = getVal(placIndices[0]);
              const placInd = placIndices.length > 1 ? getVal(placIndices[1]) : '';

              return {
                received_bgpm: getVal(bgpmIndex),
                received_prefix: prefRec,
                received_plate: placRec.toUpperCase(),
                received_model: getVal(modelIndex),
                received_city: getVal(cityIndex),
                received_unit: getVal(unitIndex),
                indicated_prefix: prefInd || null,
                indicated_plate: placInd ? placInd.toUpperCase() : null
              };
          }).filter(r => r.received_prefix && r.received_prefix !== '' && r.received_prefix !== 'undefined');

          if (formattedData.length > 0) {
            const { error } = await supabase.from('fleet_substitutions').insert(formattedData);
            if (error) throw error;
            alert(`${formattedData.length} registros importados com sucesso!`);
            fetchData();
          } else {
            alert("Nenhum dado válido de viatura encontrado nas linhas abaixo do cabeçalho.");
          }
        } catch (err: any) {
          alert(`Erro na importação: ${err.message}`);
        } finally {
          setLoading(false);
          if (e.target) e.target.value = '';
        }
      };
      reader.readAsBinaryString(file);
    }
  };

  const handleSave = async () => {
    if (!formData.received_prefix || !formData.received_plate) {
        alert("Prefixo e Placa da viatura RECEBIDA são obrigatórios.");
        return;
    }

    const payload = {
        received_prefix: formData.received_prefix,
        received_plate: formData.received_plate.toUpperCase(),
        received_model: formData.received_model,
        received_bgpm: formData.received_bgpm,
        received_city: formData.received_city,
        received_unit: formData.received_unit,
        indicated_prefix: formData.indicated_prefix || null,
        indicated_plate: formData.indicated_plate ? formData.indicated_plate.toUpperCase() : null
    };

    try {
        if (editingId) {
            const { error } = await supabase.from('fleet_substitutions').update(payload).eq('id', editingId);
            if (error) throw error;
            alert("Registro atualizado com sucesso!");
        } else {
            const { error } = await supabase.from('fleet_substitutions').insert([payload]);
            if (error) throw error;
            alert("Substituição registrada com sucesso!");
        }

