import { exportToExcel } from '../utils/excel';
import { jsPDF } from "jspdf";
import autoTable from "jspdf-autotable";

interface VehicleScheduleModuleProps {
  onBack: () => void;
  userEmail: string;
  onLogout: () => void;
}

export const VehicleScheduleModule: React.FC<VehicleScheduleModuleProps> = ({ onBack, userEmail, onLogout }) => {
  const shieldUrl = "https://yaoebstgiagmrvlbozny.supabase.co/storage/v1/object/sign/Logo%20PMMG/ESCUDO%20PMMG.png?token=eyJraWQiOiJzdG9yYWdlLXVybC1zaWduaW5nLWtleV9mMjgyNzE5YS0xNjI0LTRiYTUtODk3MC1jNTc3ZDIzMTQ4YjUiLCJhbGciOiJIUzI1NiJ9.eyJ1cmwiOiJMb2dvIFBNTUcvRVNDVURPIFBNTUcucG5nIiwiaWF0IjoxNzY1NDAzMzE0LCJleHAiOjIzOTYxMjMzMTR9.1uAuyEEDpwU_vmvKjnSJw0uYbcOIkB-vRpXRDU-Arss";

  // Estados
  const [schedules, setSchedules] = useState<VehicleSchedule[]>([]);
  const [vehicles, setVehicles] = useState<Vehicle[]>([]);
  const [loading, setLoading] = useState(true);
  const [search, setSearch] = useState('');

  // Filtros
  const [showFutureOnly, setShowFutureOnly] = useState(false);
  const [filterDate, setFilterDate] = useState(''); // Filtro por data específica

  // Modais
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isFleetManagerOpen, setIsFleetManagerOpen] = useState(false);

  // Estado de Edição de Agendamento
  const [editingScheduleId, setEditingScheduleId] = useState<string | null>(null);

  // Estados de Erro e Validação
  const [conflictError, setConflictError] = useState<React.ReactNode | null>(null);
  const [errorMessage, setErrorMessage] = useState<string | null>(null); // Erros gerais de validação
  const [formErrors, setFormErrors] = useState<Record<string, boolean>>({}); // Campos específicos com erro

  // --- ESTADOS PARA MÚLTIPLOS DIAS (CRIAÇÃO) ---
  const [isMultiDayMode, setIsMultiDayMode] = useState(false);
  const [multiDates, setMultiDates] = useState<string[]>([]);
  const [dateToAdd, setDateToAdd] = useState('');

  // --- ESTADOS PARA SELEÇÃO E EDIÇÃO EM LOTE ---
  const [isSelectionMode, setIsSelectionMode] = useState(false);
  const [selectedIds, setSelectedIds] = useState<string[]>([]);

  // Modal Edição em Lote
  const [isBatchEditOpen, setIsBatchEditOpen] = useState(false);
  const [batchEditTab, setBatchEditTab] = useState<'VEHICLE' | 'TIME'>('VEHICLE');
  const [batchVehiclePrefix, setBatchVehiclePrefix] = useState(''); 
  const [batchStartHour, setBatchStartHour] = useState('');
  const [batchEndHour, setBatchEndHour] = useState('');
  const [ignoreBatchConflict, setIgnoreBatchConflict] = useState(false);

  // Modal Exclusão em Lote
  const [isBatchDeleteOpen, setIsBatchDeleteOpen] = useState(false);

  // Form Data Agendamento
  const initialForm = {
    vehicle_prefix: '',
    start_date: '',
    end_date: '',
    start_hour: '',
    end_hour: '',
    driver_name: '',
    reason: '',
    observations: ''
  };
  const [formData, setFormData] = useState(initialForm);

  // Form Data Viatura (Gerenciamento)
  const [vehicleFormData, setVehicleFormData] = useState<Partial<Vehicle>>({});
  const [isEditingVehicle, setIsEditingVehicle] = useState<Vehicle | null>(null);

  // Exclusão Individual
  const [deletingId, setDeletingId] = useState<string | null>(null);

  // Fetch Data
  const fetchData = async () => {
    setLoading(true);
    try {
        const { data: schData, error: schError } = await supabase
            .from('vehicle_schedules')
            .select('*')
            .order('start_time', { ascending: true }); 

        if (schError) throw schError;
        setSchedules(schData || []);

        const { data: vData, error: vError } = await supabase
            .from('vehicles')
            .select('*')
            .order('prefix');

        if (vError) throw vError;
        setVehicles(vData || []);

    } catch (error: any) {
        console.error("Erro ao buscar dados:", error);
        alert(`Erro ao carregar dados da agenda.`);
    } finally {
        setLoading(false);
    }
  };

  useEffect(() => {
    fetchData();
  }, []);

  const hasScheduleConflict = (current: VehicleSchedule): boolean => {
      const currentStart = new Date(current.start_time).getTime();
      const currentEnd = new Date(current.end_time).getTime();

      return schedules.some(other => {
          if (other.id === current.id) return false;
          if (other.vehicle_prefix !== current.vehicle_prefix) return false;
          const otherStart = new Date(other.start_time).getTime();
          const otherEnd = new Date(other.end_time).getTime();
          return (currentStart < otherEnd && currentEnd > otherStart);
      });
  };

  const checkConflict = (newStart: Date, newEnd: Date, prefix: string, excludeId?: string): VehicleSchedule | null => {
      const vehicleSchedules = schedules.filter(s => s.vehicle_prefix === prefix);
      for (const schedule of vehicleSchedules) {
          if (excludeId && schedule.id === excludeId) continue;
          const existingStart = new Date(schedule.start_time);
          const existingEnd = new Date(schedule.end_time);
          if (newStart < existingEnd && newEnd > existingStart) {
              return schedule;
          }
      }
      return null; 
  };

  const handleOpenEdit = (schedule: VehicleSchedule) => {
      if (isSelectionMode) {
          toggleSelection(schedule.id);
          return;
      }
      setConflictError(null);
      setErrorMessage(null);
      setFormErrors({});
      setIsMultiDayMode(false);
      setMultiDates([]);
      const startDate = new Date(schedule.start_time);
      const endDate = new Date(schedule.end_time);
      const startDateStr = startDate.toISOString().split('T')[0];
      const endDateStr = endDate.toISOString().split('T')[0];
      const startHour = startDate.toLocaleTimeString('pt-BR', { hour: '2-digit', minute: '2-digit' });
      const endHour = endDate.toLocaleTimeString('pt-BR', { hour: '2-digit', minute: '2-digit' });
      setFormData({
          vehicle_prefix: schedule.vehicle_prefix,
          start_date: startDateStr,
          end_date: endDateStr,
          start_hour: startHour,
          end_hour: endHour,
          driver_name: schedule.driver_name,
          reason: schedule.reason,
          observations: schedule.observations || ''
      });
      setEditingScheduleId(schedule.id);
      setIsModalOpen(true);
  };

  const handleOpenNew = () => {
      setIsModalOpen(true);
      setEditingScheduleId(null);
      setFormData(initialForm);
      setConflictError(null);
      setErrorMessage(null);
      setFormErrors({});
      setIsMultiDayMode(false); 
      setMultiDates([]);
      setDateToAdd('');
  };

  const getInputClass = (field: keyof typeof initialForm) => {
      const baseClass = "w-full border p-2 rounded outline-none transition-colors ";
      if (formErrors[field]) {
          return baseClass + "border-red-500 bg-red-50 focus:ring-2 focus:ring-red-500 text-red-900 placeholder-red-300";
      }
      return baseClass + "focus:ring-2 focus:ring-[#C5A059]";
  };

  const addDateToList = () => {
      if (!dateToAdd) return;
      if (multiDates.includes(dateToAdd)) {
          alert("Esta data já foi adicionada.");
          return;
      }
      const newDates = [...multiDates, dateToAdd].sort();
      setMultiDates(newDates);
      setDateToAdd('');
  };

  const removeDateFromList = (dateToRemove: string) => {
      setMultiDates(multiDates.filter(d => d !== dateToRemove));
  };

  const toggleSelection = (id: string) => {
      if (selectedIds.includes(id)) {
          setSelectedIds(selectedIds.filter(item => item !== id));
      } else {
          setSelectedIds([...selectedIds, id]);
      }
  };

  const toggleAllSelection = () => {
      if (selectedIds.length === filteredSchedules.length) {
          setSelectedIds([]);
      } else {
          setSelectedIds(filteredSchedules.map(s => s.id));
      }
  };

  const handleBatchDelete = async () => {
      setLoading(true);
      try {
          const { error } = await supabase.from('vehicle_schedules').delete().in('id', selectedIds);
          if (error) throw error;
          alert(`${selectedIds.length} agendamentos excluídos.`);
          setIsBatchDeleteOpen(false);
          setIsSelectionMode(false);
          setSelectedIds([]);
          fetchData();
      } catch (err: any) {
          alert("Erro ao excluir: " + err.message);
      } finally {
          setLoading(false);
      }
  };

  // Individual Delete confirmation logic
  const confirmDeleteSchedule = async () => {
    if (!deletingId) return;
    setLoading(true);
    try {
      const { error } = await supabase
        .from('vehicle_schedules')
        .delete()
        .eq('id', deletingId);

      if (error) throw error;
      setDeletingId(null);
      fetchData();
    } catch (err: any) {
      console.error('Erro ao excluir:', err);
      alert(`Erro ao excluir: ${err.message || JSON.stringify(err)}`);
    } finally {
      setLoading(false);
    }
  };

  const handleBatchEdit = async () => {
      setLoading(true);
      try {
          if (batchEditTab === 'VEHICLE') {
              if (!batchVehiclePrefix) { alert("Selecione a nova viatura."); setLoading(false); return; }
              if (!ignoreBatchConflict) {
                  for (const id of selectedIds) {
                      const schedule = schedules.find(s => s.id === id);
                      if (schedule) {
                          const conflict = checkConflict(new Date(schedule.start_time), new Date(schedule.end_time), batchVehiclePrefix, id);
                          if (conflict) {
                              alert(`Conflito detectado para a viatura ${batchVehiclePrefix} em ${new Date(schedule.start_time).toLocaleString('pt-BR')}.`);
                              setLoading(false);
                              return;
                          }
                      }
                  }
              }
              const { error } = await supabase.from('vehicle_schedules').update({ vehicle_prefix: batchVehiclePrefix }).in('id', selectedIds);
              if (error) throw error;
          } else {
              if (!batchStartHour || !batchEndHour) { alert("Informe o horário."); setLoading(false); return; }
              for (const id of selectedIds) {
                  const schedule = schedules.find(s => s.id === id);
                  if (!schedule) continue;
                  const datePart = new Date(schedule.start_time).toISOString().split('T')[0];
                  const newStart = new Date(`${datePart}T${batchStartHour}:00`);
                  let newEnd = new Date(`${datePart}T${batchEndHour}:00`);
                  if (newEnd <= newStart) newEnd.setDate(newEnd.getDate() + 1);
                  if (!ignoreBatchConflict) {
                      const conflict = checkConflict(newStart, newEnd, schedule.vehicle_prefix, id);
                      if (conflict) { alert("Conflito de horário detectado."); setLoading(false); return; }
                  }
                  const { error } = await supabase.from('vehicle_schedules').update({ start_time: newStart.toISOString(), end_time: newEnd.toISOString() }).eq('id', id);
                  if (error) throw error;
              }
          }
          setIsBatchEditOpen(false);
          setIsSelectionMode(false);
          setSelectedIds([]);
          fetchData();
      } catch (err: any) {
          alert("Erro: " + err.message);
      } finally {
          setLoading(false);
      }
  };

  const handleSaveSchedule = async (forceSave: boolean = false) => {
    setConflictError(null); 
    setErrorMessage(null);
    setFormErrors({});
    const requiredFieldsCommon = ['vehicle_prefix', 'start_hour', 'end_hour', 'driver_name', 'reason'];
    const newErrors: Record<string, boolean> = {};
    let hasEmptyFields = false;
    requiredFieldsCommon.forEach((field) => {
        if (!formData[field as keyof typeof formData]) { newErrors[field] = true; hasEmptyFields = true; }
    });
    if (isMultiDayMode) {
        if (multiDates.length === 0) { setErrorMessage("Adicione pelo menos uma data."); return; }
    } else {
        if (!formData.start_date) { newErrors['start_date'] = true; hasEmptyFields = true; }
        if (!formData.end_date) { newErrors['end_date'] = true; hasEmptyFields = true; }
    }
    if (hasEmptyFields) { setFormErrors(newErrors); setErrorMessage("Preencha todos os campos obrigatórios."); return; }
    const schedulesToInsert: any[] = [];
    const formatConflict = (d: Date) => d.toLocaleString('pt-BR', { day: '2-digit', month: '2-digit', hour: '2-digit', minute: '2-digit' });
    if (isMultiDayMode) {
        for (const dateStr of multiDates) {
            const currentStart = new Date(`${dateStr}T${formData.start_hour}:00`);
            let currentEnd = new Date(`${dateStr}T${formData.end_hour}:00`);
            if (currentEnd <= currentStart) currentEnd.setDate(currentEnd.getDate() + 1);
            if (!forceSave) {
                const conflict = checkConflict(currentStart, currentEnd, formData.vehicle_prefix);
                if (conflict) {
                     setConflictError(
                        <div className="bg-red-50 border-l-4 border-red-500 p-4 mb-4 rounded shadow-sm animate-fade-in">
                            <div className="flex items-center gap-2 text-red-700 font-bold mb-2"><XCircle size={20} /><span>CONFLITO EM {new Date(dateStr).toLocaleDateString('pt-BR')}</span></div>
                            <p className="text-sm text-gray-700 mb-2">A viatura {formData.vehicle_prefix} está ocupada das {formatConflict(new Date(conflict.start_time))} até {formatConflict(new Date(conflict.end_time))}.</p>
                            <button onClick={() => handleSaveSchedule(true)} className="bg-red-600 text-white py-2 px-4 rounded text-sm font-bold">IGNORAR E SALVAR</button>
                        </div>
                    );
                    return; 
                }
            }
            schedulesToInsert.push({ vehicle_prefix: formData.vehicle_prefix, driver_name: formData.driver_name.toUpperCase(), reason: formData.reason.toUpperCase(), start_time: currentStart.toISOString(), end_time: currentEnd.toISOString(), observations: formData.observations });
        }
    } else {
        const startDateTime = new Date(`${formData.start_date}T${formData.start_hour}:00`);
        const endDateTime = new Date(`${formData.end_date}T${formData.end_hour}:00`);
        if (endDateTime <= startDateTime) { setErrorMessage("Término deve ser após o início."); return; }
        if (!forceSave) {
            const conflict = checkConflict(startDateTime, endDateTime, formData.vehicle_prefix, editingScheduleId || undefined);
            if (conflict) {
                setConflictError(
                    <div className="bg-red-50 border-l-4 border-red-500 p-4 mb-4 rounded shadow-sm animate-fade-in">
                        <div className="flex items-center gap-2 text-red-700 font-bold mb-2"><XCircle size={20} /><span>CONFLITO DETECTADO</span></div>
                        <p className="text-sm text-gray-700 mb-2">Viatura {formData.vehicle_prefix} ocupada: {formatConflict(new Date(conflict.start_time))} - {formatConflict(new Date(conflict.end_time))}.</p>
                         <button onClick={() => handleSaveSchedule(true)} className="bg-red-600 text-white py-2 px-4 rounded text-sm font-bold">IGNORAR E SALVAR</button>
                    </div>
                );
                return;
            }
        }
        schedulesToInsert.push({ vehicle_prefix: formData.vehicle_prefix, driver_name: formData.driver_name.toUpperCase(), reason: formData.reason.toUpperCase(), start_time: startDateTime.toISOString(), end_time: endDateTime.toISOString(), observations: formData.observations });
    }
    try {
        if (editingScheduleId && !isMultiDayMode) {
            await supabase.from('vehicle_schedules').update(schedulesToInsert[0]).eq('id', editingScheduleId);
        } else {
            await supabase.from('vehicle_schedules').insert(schedulesToInsert);
        }
        setIsModalOpen(false);
        fetchData();
    } catch (e: any) { alert("Erro ao salvar."); }
  };

  const handleSaveVehicle = async () => {
      if(!vehicleFormData.prefix || !vehicleFormData.plate) return;
      try {
          if (isEditingVehicle) await supabase.from('vehicles').update(vehicleFormData).eq('id', isEditingVehicle.id);
          else await supabase.from('vehicles').insert([vehicleFormData]);
          const { data } = await supabase.from('vehicles').select('*').order('prefix');
          if (data) setVehicles(data);
          setIsEditingVehicle(null);
          setVehicleFormData({});
      } catch (e) { alert("Erro ao salvar."); }
  };

  const handleExportPDF = () => {
      const doc = new jsPDF();
      doc.text("Agenda de Viaturas - 5ª RPM", 14, 20);
      autoTable(doc, {
          startY: 30,
          head: [['Viatura', 'Motorista', 'Início', 'Término', 'Motivo']],
          body: filteredSchedules.map(s => [s.vehicle_prefix, s.driver_name, new Date(s.start_time).toLocaleString('pt-BR'), new Date(s.end_time).toLocaleString('pt-BR'), s.reason]),
      });
      doc.save("Agenda_5RPM.pdf");
  };

  const filteredSchedules = schedules.filter(s => {
      const matchesSearch = s.vehicle_prefix.includes(search) || s.driver_name.toLowerCase().includes(search.toLowerCase());
      const matchesDate = filterDate ? (new Date(s.start_time) <= new Date(`${filterDate}T23:59:59`) && new Date(s.end_time) >= new Date(`${filterDate}T00:00:00`)) : true;
      return matchesSearch && matchesDate && (!showFutureOnly || new Date(s.end_time) > new Date());
  });

  return (
    <div className="min-h-screen bg-[#958458] font-sans flex flex-col">
       <header className="bg-[#3E3223] shadow-lg sticky top-0 z-40 border-b-4 border-[#C5A059]">
        <div className="container mx-auto px-4 h-32 flex items-center justify-between">
          <div className="flex items-center gap-4 py-2">
             <button onClick={onBack} className="flex flex-col items-center justify-center text-[#C5A059] hover:text-white transition-colors bg-white/5 hover:bg-white/10 p-2 rounded-lg">
                <Home size={20} /><span className="text-[10px] uppercase font-bold mt-1">Menu</span>
             </button>
             <img src={shieldUrl} alt="Escudo" className="h-28 drop-shadow-xl" style={{ height: '7rem' }} />
          </div>
          <div className="text-right">
             <h1 className="text-3xl md:text-4xl font-extrabold tracking-tight text-[#C5A059] font-serif uppercase">AGENDA DE VIATURA</h1>
             <p className="text-lg font-bold text-[#C5A059] opacity-90 tracking-widest font-serif">FROTA 5ª RPM</p>
          </div>
        </div>
        <div className="bg-[#4A3B2A]/90 backdrop-blur-sm text-white/90 py-2">
          <div className="container mx-auto px-4 flex justify-end items-center"><button onClick={onLogout} className="flex items-center gap-2 px-4 py-2 text-red-200 hover:text-red-100 hover:bg-red-900/30 rounded transition-colors text-sm font-semibold"><LogOut size={18} /> Sair</button></div>
        </div>
      </header>

      <main className="container mx-auto px-4 py-8 flex-grow pb-24">
        <div className="bg-[#fdfbf7] rounded-xl shadow-2xl border border-[#d4c5a3] p-6 min-h-[600px]">
            <div className="flex flex-col xl:flex-row justify-between items-center gap-4 mb-6">
                <div className="flex flex-col md:flex-row gap-3 w-full xl:w-auto flex-1">
                    <div className="relative w-full md:w-80"><Search className="absolute left-3 top-2.5 h-5 w-5 text-gray-400" /><input type="text" placeholder="Buscar..." className="w-full pl-10 pr-4 py-2 border rounded-md outline-none" value={search} onChange={e => setSearch(e.target.value)} /></div>
                    <input type="date" className="border p-2 rounded-md outline-none" value={filterDate} onChange={e => setFilterDate(e.target.value)} />
                    <button onClick={() => setShowFutureOnly(!showFutureOnly)} className={`px-4 py-2 rounded font-bold border ${showFutureOnly ? 'bg-blue-600 text-white' : 'bg-white text-gray-600'}`}>{showFutureOnly ? "Futuros" : "Todos"}</button>
                    <button onClick={() => { setIsSelectionMode(!isSelectionMode); setSelectedIds([]); }} className={`px-4 py-2 rounded font-bold border ${isSelectionMode ? 'bg-orange-500 text-white' : 'bg-white text-gray-600'}`}>Selecionar Vários</button>
                </div>
                <div className="flex gap-2 w-full xl:w-auto justify-end">
                    <button onClick={handleExportPDF} className="px-3 py-2 bg-red-600 text-white rounded hover:bg-red-700">PDF</button>
                    <button onClick={() => setIsFleetManagerOpen(true)} className="px-4 py-2 bg-gray-600 text-white font-bold rounded">Frota</button>
                    <button onClick={handleOpenNew} className="px-6 py-2 bg-[#C5A059] text-[#3E3223] font-bold rounded shadow-sm">Novo</button>
                </div>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-4">
                {filteredSchedules.map(sch => (
                    <div key={sch.id} onClick={() => isSelectionMode && toggleSelection(sch.id)} className={`bg-white rounded-lg shadow-sm p-4 border-l-4 relative group cursor-pointer ${selectedIds.includes(sch.id) ? 'ring-2 ring-orange-500 bg-orange-50' : 'border-gray-300'}`}>
                        <div className="flex items-center justify-between mb-3"><div className="bg-[#3E3223] text-[#C5A059] font-bold px-3 py-1.5 rounded-md text-xl flex items-center gap-2"><Car size={20} /> {sch.vehicle_prefix}</div></div>
                        <div className="mb-2"><div className="text-[#C5A059] font-bold text-sm">{new Date(sch.start_time).toLocaleDateString('pt-BR')}</div><div className="text-gray-600 font-semibold text-sm">{new Date(sch.start_time).toLocaleTimeString('pt-BR', {hour:'2-digit', minute:'2-digit'})} às {new Date(sch.end_time).toLocaleTimeString('pt-BR', {hour:'2-digit', minute:'2-digit'})}</div></div>
                        <div className="text-sm font-bold text-gray-700 uppercase">{sch.driver_name}</div>
                        <div className="text-xs text-gray-500 italic mt-1">{sch.reason}</div>
                        {!isSelectionMode && <button onClick={(e) => {e.stopPropagation(); setDeletingId(sch.id);}} className="absolute top-2 right-2 text-red-300 hover:text-red-500"><Trash2 size={16} /></button>}
                    </div>
                ))}
            </div>
        </div>

        {isSelectionMode && selectedIds.length > 0 && (
            <div className="fixed bottom-6 left-1/2 -translate-x-1/2 bg-gray-900 text-white px-6 py-4 rounded-full shadow-2xl flex items-center gap-4 z-50"><span className="bg-orange-500 text-white rounded-full w-6 h-6 flex items-center justify-center text-xs">{selectedIds.length}</span><button onClick={() => setIsBatchEditOpen(true)} className="bg-[#C5A059] text-[#3E3223] px-4 py-2 rounded-full font-bold text-sm">Editar</button><button onClick={() => setIsBatchDeleteOpen(true)} className="bg-red-600 text-white px-4 py-2 rounded-full font-bold text-sm">Excluir</button><button onClick={() => { setIsSelectionMode(false); setSelectedIds([]); }}><X size={20} /></button></div>
        )}

        {/* MODAL DE AGENDAMENTO COM BARRA DE ROLAGEM */}
        {isModalOpen && (
            <div className="fixed inset-0 bg-black/60 backdrop-blur-sm flex items-center justify-center z-50 p-4 overflow-y-auto">
                <div className="bg-white rounded-lg shadow-2xl w-full max-w-lg border-t-8 border-[#C5A059] my-8 animate-fade-in flex flex-col max-h-[90vh]">
                    {/* Cabeçalho Fixo */}
                    <div className="p-6 border-b">
                        <div className="flex justify-between items-start">
                            <h2 className="text-2xl font-bold text-[#3E3223] flex items-center gap-2">
                                <CalendarClock /> {editingScheduleId ? 'Editar Agendamento' : 'Novo Agendamento'}
                            </h2>
                            {!editingScheduleId && (
                                <button 
                                    onClick={() => setIsMultiDayMode(!isMultiDayMode)}
                                    className={`text-[10px] px-3 py-2 rounded-lg font-bold flex items-center gap-2 ${isMultiDayMode ? 'bg-indigo-600 text-white' : 'bg-indigo-500 text-white'}`}
                                >
                                    {isMultiDayMode ? <Layers size={14} /> : <CalendarPlus size={14} />}
                                    {isMultiDayMode ? "LOTE ATIVO" : "AGENDAR VÁRIOS DIAS"}
                                </button>
                            )}
                        </div>
                    </div>

                    {/* Conteúdo Rolável */}
                    <div className="p-6 overflow-y-auto flex-grow custom-scrollbar">
