                            className="w-full pl-9 pr-4 py-2 border rounded-md outline-none text-sm focus:ring-1 focus:ring-[#C5A059]" 
                            value={search} 
                            onChange={e => setSearch(e.target.value)} 
                        />
                    </div>
                    {/* DATA */}
                    <input 
                        type="date" 
                        className="border p-2 rounded-md outline-none text-sm" 
                        value={filterDate} 
                        onChange={e => setFilterDate(e.target.value)} 
                    />
                    {/* TODOS */}
                    <button 
                        onClick={() => setShowFutureOnly(!showFutureOnly)} 
                        className={`flex items-center gap-2 px-4 py-2 rounded font-bold border text-sm transition-colors ${showFutureOnly ? 'bg-blue-600 text-white' : 'bg-white text-gray-600 hover:bg-gray-50'}`}
                    >
                        {showFutureOnly ? <CheckSquare size={16}/> : <Square size={16}/>} Todos
                    </button>
                    {/* SELECIONAR VÁRIOS */}
                    <button 
                        onClick={() => { setIsSelectionMode(!isSelectionMode); setSelectedIds([]); }} 
