                    >
                        <MousePointerClick size={16}/> Selecionar Vários
                    </button>
                </div>

                <div className="flex items-center gap-2 w-full xl:w-auto justify-end">
                    {/* BOTÕES EXPORTAÇÃO COLORIDOS */}
                    <button 
                        onClick={handleExportExcel} 
                        className="flex items-center gap-2 px-4 py-2 bg-[#00875A] text-white rounded font-bold text-sm hover:bg-[#006644] transition-colors"
                    >
                        <FileDown size={16}/> Excel
                    </button>
                    <button 
                        onClick={handleExportPDF} 
                        className="flex items-center gap-2 px-4 py-2 bg-[#DE350B] text-white rounded font-bold text-sm hover:bg-[#BF2600] transition-colors"
                    >
                        <FileText size={16}/> PDF
                    </button>

                    <div className="h-8 w-px bg-gray-300 mx-1"></div>

                    {/* BOTÃO FROTA (ESCURECIDO) */}
                    <button 
                        onClick={() => setIsFleetManagerOpen(true)} 
                        className="flex items-center gap-2 px-4 py-2 bg-[#344563] text-white font-bold rounded text-sm hover:bg-[#253858] transition-colors"
                    >
                        <Settings size={16}/> Frota
                    </button>
                </div>
            </div>

            {/* BOTÃO NOVO (ABAIXO DA TOOLBAR) */}
            <div className="mb-6 flex justify-end">
                <button 
                    onClick={handleOpenNew} 
                    className="flex items-center gap-2 px-8 py-2.5 bg-[#C5A059] text-[#3E3223] font-black rounded shadow-md hover:bg-[#B08D4A] transition-all uppercase tracking-wider"
                >
                    <Plus size={20}/> Novo
                </button>
