                                        </div>
                                    </div>
                                    <div className="bg-gray-50 p-3 rounded border border-gray-200">
                                        <label className="text-[10px] font-bold uppercase text-gray-500 block mb-2">Chegada (Previsão)</label>
                                        <div className="grid grid-cols-2 gap-2">
                                            <input type="date" className={getInputClass('end_date')} value={formData.end_date} onChange={e => setFormData({...formData, end_date: e.target.value})} />
                                            <input type="time" className={getInputClass('end_hour')} value={formData.end_hour} onChange={e => setFormData({...formData, end_hour: e.target.value})} />
                                        </div>
                                    </div>
                                </>
                            )}

                            <div><label className="block text-sm font-bold text-gray-700 mb-1">Motorista / Responsável *</label><input className={getInputClass('driver_name') + " uppercase"} placeholder="POSTO/GRAD E NOME" value={formData.driver_name} onChange={e => setFormData({...formData, driver_name: e.target.value.toUpperCase()})} /></div>
                            <div><label className="block text-sm font-bold text-gray-700 mb-1">Motivo do Empréstimo *</label><input className={getInputClass('reason') + " uppercase"} placeholder="EX: APOIO A EVENTO, MANUTENÇÃO, MISSÃO..." value={formData.reason} onChange={e => setFormData({...formData, reason: e.target.value.toUpperCase()})} /></div>
                            <div><label className="block text-sm font-bold text-gray-700 mb-1">Observações</label><textarea className="w-full border p-2 rounded h-20 outline-none focus:ring-2 focus:ring-[#C5A059] text-sm" value={formData.observations} onChange={e => setFormData({...formData, observations: e.target.value})} placeholder="Detalhes adicionais..." /></div>
                        </div>
                    </div>

                    <div className="p-6 border-t bg-gray-50 flex justify-end gap-3 rounded-b-lg">
                        <button onClick={() => setIsModalOpen(false)} className="px-6 py-2 text-gray-600 hover:bg-gray-200 rounded border font-bold">Cancelar</button>
                        <button onClick={() => handleSaveSchedule(false)} className="px-6 py-2 bg-[#3E3223] text-white rounded hover:bg-black font-bold shadow-md transition-all">{editingScheduleId ? 'Salvar' : 'Agendar'}</button>
                    </div>
                </div>
            </div>
        )}

        {/* Modal de Exclusão Individual */}
        {deletingId && (
            <div className="fixed inset-0 bg-black/60 backdrop-blur-sm flex items-center justify-center z-[80]"><div className="bg-white p-6 rounded-lg shadow-2xl w-full max-w-md border-t-4 border-red-600"><h3 className="text-xl font-bold text-red-700 mb-4 flex items-center gap-2"><AlertTriangle /> Confirmar Exclusão</h3><p className="text-gray-700 mb-6 text-sm">Deseja realmente cancelar este agendamento?</p><div className="flex justify-end gap-3"><button onClick={() => setDeletingId(null)} className="px-4 py-2 text-gray-600 border rounded">Cancelar</button><button onClick={confirmDeleteSchedule} className="px-4 py-2 bg-red-600 text-white rounded font-bold">Excluir</button></div></div></div>
        )}
      </main>
    </div>
  );
};

