            <p className="text-sm text-gray-300 mb-2">Foi adicionado suporte a valores fracionados (Ex: 1,5). Se você já tem o sistema funcionando, execute o SQL novamente para aplicar as mudanças de tipo de coluna.</p>
            <ol className="list-decimal list-inside text-gray-300 space-y-1 text-sm">
                <li>Copie o código SQL abaixo.</li>
                <li>Vá até o painel do Supabase do seu projeto ({'>'} SQL Editor).</li>
                <li>Cole o código e clique em <strong>Run</strong>.</li>
            </ol>
        </div>

        <div className="relative">
            <div className="absolute top-2 right-2">
                <button 
                    onClick={handleCopy}
                    className={`flex items-center gap-2 px-3 py-1.5 rounded text-sm font-bold transition-all ${
                        copied 
                        ? 'bg-green-600 text-white' 
                        : 'bg-gray-700 hover:bg-gray-600 text-gray-200'
                    }`}
                >
                    {copied ? <><Check size={16} /> Copiado!</> : <><Copy size={16} /> Copiar SQL</>}
                </button>
            </div>
            <div className="bg-gray-950 p-4 rounded border border-gray-700 font-mono text-xs overflow-auto max-h-[400px] mb-6 select-all custom-scrollbar">
                <pre style={{ whiteSpace: 'pre-wrap' }}>{sql}</pre>
            </div>
        </div>

        {onBack ? (
            <button 
                onClick={onBack}
                className="w-full py-4 bg-gray-700 hover:bg-gray-600 rounded-lg font-bold text-lg transition shadow-lg"
            >
                Voltar ao Sistema
            </button>
        ) : (
            <button 
                onClick={() => window.location.reload()}
                className="w-full py-4 bg-blue-600 hover:bg-blue-700 rounded-lg font-bold text-lg transition shadow-lg hover:shadow-blue-500/20"
            >
                Já executei o SQL, Tentar Novamente
            </button>
        )}
      </div>
    </div>
  );
};

import React, { useEffect, useState } from 'react';
import { supabase } from '../lib/supabase';
import { Material, Movement, MovementType } from '../types';
import { Plus, ArrowDownCircle, ArrowUpCircle, FileDown, Search, Edit, XCircle, ArrowUpDown, ArrowUp, ArrowDown, PackagePlus, MessageSquare, Trash2, AlertTriangle } from 'lucide-react';
import { exportToExcel } from '../utils/excel';

type SortKey = 'created_at' | 'type' | 'material_name' | 'quantity' | 'requester' | 'vehicle_prefix' | 'guide_number';

export const MovementsTab: React.FC = () => {
  const [movements, setMovements] = useState<Movement[]>([]);
  const [materials, setMaterials] = useState<Material[]>([]);
  const [loading, setLoading] = useState(true);
  const [errorMsg, setErrorMsg] = useState<string | null>(null);
  const [isAdding, setIsAdding] = useState(false);
  const [isEditing, setIsEditing] = useState<Movement | null>(null);
  const [search, setSearch] = useState('');

  // Estado para exclusão
  const [deletingId, setDeletingId] = useState<string | null>(null);

  // Estado para cadastro rápido de novo material
  const [isAddingMaterial, setIsAddingMaterial] = useState(false);
  const [newMaterialData, setNewMaterialData] = useState({ 
    name: '', 
    unit: 'Unidade',
    compatible_vehicles: '' 
  });

  // Sorting
  const [sortConfig, setSortConfig] = useState<{ key: SortKey; direction: 'ASC' | 'DESC' }>({ 
    key: 'created_at', 
    direction: 'DESC' 
  });

  // Form State
  const initialForm = {
    material_id: '',
    type: MovementType.EXIT,
    quantity: 1,
    requester: '',
    vehicle_prefix: '',
    guide_number: '',
    observation: '',
    created_at: new Date().toISOString().split('T')[0]
  };
  const [formData, setFormData] = useState(initialForm);

  const fetchData = async () => {
    setLoading(true);
    setErrorMsg(null);

    try {
      // 1. Fetch Materials
      const { data: matData, error: matError } = await supabase
        .from('materials')
        .select('*')
        .order('name');

      if (matError) throw matError;
      setMaterials(matData || []);

      // 2. Fetch Movements
      const { data: movData, error: movError } = await supabase
        .from('movements')
        .select('*');

      if (movError) throw movError;

      // 3. Join in Javascript
      const matList = (matData || []) as Material[];
      const matMap = new Map<string, Material>(matList.map(m => [m.id, m]));

      const formatted = (movData || []).map((m: any) => ({
        ...m,
        material_name: matMap.get(m.material_id)?.name || 'Material não encontrado',
        material_unit: matMap.get(m.material_id)?.unit || ''
      }));

      setMovements(formatted);

    } catch (err: any) {
      console.error('Erro ao buscar dados:', err);
      setErrorMsg(err.message || JSON.stringify(err));
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchData();
  }, []);

  const handleSaveNewMaterial = async () => {
      if (!newMaterialData.name.trim()) return;

      try {
          const { data, error } = await supabase
              .from('materials')
              .insert([{ 
                name: newMaterialData.name, 
                quantity: 0, 
                unit: newMaterialData.unit,
                compatible_vehicles: newMaterialData.compatible_vehicles 
              }])
              .select()
              .single();

          if (error) throw error;

          alert(`Material "${data.name}" criado com sucesso!`);

          // Atualiza lista de materiais
          const { data: matData } = await supabase.from('materials').select('*').order('name');
          if (matData) setMaterials(matData);

          // Seleciona o novo material no formulário de movimentação
          setFormData({ ...formData, material_id: data.id });

          // Fecha modal
          setIsAddingMaterial(false);
          setNewMaterialData({ name: '', unit: 'Unidade', compatible_vehicles: '' });

      } catch (err: any) {
          alert("Erro ao criar material: " + err.message);
      }
  };

  const handleSave = async () => {
    // Validação de campos obrigatórios
    if (!formData.material_id) { alert("Selecione um material."); return; }
    if (formData.quantity <= 0) { alert("A quantidade deve ser maior que zero."); return; }
    if (!formData.created_at) { alert("Informe a data."); return; }

    // Validação Condicional: Responsável e Prefixo só obrigatórios na SAÍDA
    if (formData.type === MovementType.EXIT) {
        if (!formData.requester.trim()) { alert("Informe o Responsável pela retirada (Obrigatório na Saída)."); return; }
        if (!formData.vehicle_prefix.trim()) { alert("Informe o Prefixo da viatura (Obrigatório na Saída)."); return; }
    }

    try {
      const payload = {
          material_id: formData.material_id,
          type: formData.type,
          quantity: formData.quantity,
          requester: formData.requester.trim() || null,
          vehicle_prefix: formData.vehicle_prefix.trim() || null,
          guide_number: formData.guide_number,
          observation: formData.observation,
          created_at: formData.created_at
      };

      if (isEditing) {
        const { error } = await supabase
          .from('movements')
          .update(payload)
          .eq('id', isEditing.id);

        if (error) throw error;
        alert("Movimentação atualizada.");
      } else {
        const { error: movError } = await supabase.from('movements').insert([payload]);
        if (movError) {
             if (movError.message.includes("null value in column")) {
                 throw new Error("O banco de dados recusou campos vazios. Execute o script SQL na ajuda para corrigir as permissões.");
             }
             throw movError;
        }
      }

      setIsAdding(false);
      setIsEditing(null);
      setFormData(initialForm);
      fetchData();
    } catch (err: any) {
      console.error(err);
      alert(`Erro ao salvar: ${err.message || JSON.stringify(err)}`);
    }
  };

  const confirmDelete = async () => {
    if (!deletingId) return;

    try {
      const { error } = await supabase
        .from('movements')
        .delete()
        .eq('id', deletingId);

      if (error) throw error;

      // Sucesso
      setDeletingId(null);
      fetchData();
    } catch (err: any) {
      console.error('Erro ao excluir:', err);
      alert(`Erro ao excluir: ${err.message || JSON.stringify(err)}`);
      setDeletingId(null);
    }
  };

  const handleSort = (key: SortKey) => {
    let direction: 'ASC' | 'DESC' = 'ASC';
    if (sortConfig.key === key && sortConfig.direction === 'ASC') {
      direction = 'DESC';
    }
    setSortConfig({ key, direction });
  };

  const renderSortIcon = (key: SortKey) => {
    if (sortConfig.key !== key) return <ArrowUpDown size={14} className="text-gray-400 opacity-50" />;
    return sortConfig.direction === 'ASC' 
      ? <ArrowUp size={14} className="text-pmmg-primary" /> 
      : <ArrowDown size={14} className="text-pmmg-primary" />;
  };

  const filteredMovements = movements
    .filter(m => 
      (m.material_name?.toLowerCase() || '').includes(search.toLowerCase()) ||
      (m.requester?.toLowerCase() || '').includes(search.toLowerCase()) ||
      (m.vehicle_prefix?.toLowerCase() || '').includes(search.toLowerCase()) ||
      (m.guide_number?.toLowerCase() || '').includes(search.toLowerCase())
    )
    .sort((a, b) => {
      let valA: any = a[sortConfig.key as keyof Movement];
      let valB: any = b[sortConfig.key as keyof Movement];

      if (sortConfig.key === 'material_name') {
         valA = a.material_name || '';
         valB = b.material_name || '';
      }

      if (typeof valA === 'string') valA = valA.toLowerCase();
      if (typeof valB === 'string') valB = valB.toLowerCase();

      if (valA < valB) return sortConfig.direction === 'ASC' ? -1 : 1;
      if (valA > valB) return sortConfig.direction === 'ASC' ? 1 : -1;
      return 0;
    });

  return (
    <div className="space-y-6">
      <div className="flex flex-col xl:flex-row justify-between items-start xl:items-center gap-4 bg-white p-4 rounded-lg shadow-sm border-l-4 border-pmmg-primary">
        <div className="relative w-full xl:w-96">
           <Search className="absolute left-2 top-2.5 h-4 w-4 text-gray-400" />
           <input
              type="text"
              placeholder="Buscar por material, responsável, prefixo ou guia..."
              className="pl-8 pr-4 py-2 border rounded-md w-full outline-none focus:ring-2 focus:ring-pmmg-primary"
              value={search}
              onChange={e => setSearch(e.target.value)}
            />
        </div>

        <div className="flex flex-col items-end gap-2 w-full xl:w-auto">
            <div className="flex gap-2">
               <button 
                onClick={() => exportToExcel(movements, 'Movimentacoes_Frota_5RPM')}
                className="flex items-center gap-2 px-3 py-2 bg-gray-600 text-white rounded-md hover:bg-gray-700 transition-colors shadow-sm"
              >
                <FileDown size={16} /> Exportar Excel
              </button>
              <button 
                onClick={() => { setIsAdding(true); setFormData(initialForm); }}
                className="flex items-center gap-2 px-3 py-2 bg-pmmg-primary text-white rounded-md hover:bg-[#3E3223] transition-colors shadow-sm"
              >
                <Plus size={16} /> Nova Movimentação
              </button>
            </div>
        </div>
      </div>

      {errorMsg && (
        <div className="bg-red-50 text-red-700 p-4 rounded-lg flex items-center gap-2 border border-red-200">
          <XCircle size={20} />
          <span>Erro: {errorMsg}</span>
        </div>
      )}

      {/* MODAL DE CONFIRMAÇÃO DE EXCLUSÃO */}
      {deletingId && (
          <div className="fixed inset-0 bg-black/60 backdrop-blur-sm flex items-center justify-center z-[70]">
              <div className="bg-white p-6 rounded-lg shadow-2xl w-full max-w-md border-t-4 border-red-600">
                  <div className="flex items-center gap-3 mb-4 text-red-700">
                      <AlertTriangle size={32} />
                      <h3 className="text-xl font-bold">Confirmar Exclusão</h3>
                  </div>

                  <p className="text-gray-700 mb-6">
                      Tem certeza que deseja excluir esta movimentação? <br/>
                      <span className="text-sm font-bold text-gray-500 mt-2 block">
                          Isso irá corrigir automaticamente o saldo no estoque.
                      </span>
                  </p>

                  <div className="flex justify-end gap-3">
                      <button 
                          onClick={() => setDeletingId(null)}
                          className="px-4 py-2 text-gray-600 hover:bg-gray-100 rounded border font-medium"
                      >
                          Cancelar
                      </button>
                      <button 
                          onClick={confirmDelete}
                          className="px-4 py-2 bg-red-600 text-white rounded hover:bg-red-700 shadow-md font-bold flex items-center gap-2"
                      >
                          <Trash2 size={18} />
                          Sim, Excluir
                      </button>
                  </div>
              </div>
          </div>
      )}

      {/* MODAL DE NOVO MATERIAL */}
      {isAddingMaterial && (
          <div className="fixed inset-0 bg-black/70 backdrop-blur-sm flex items-center justify-center z-[60]">
              <div className="bg-white p-5 rounded-lg shadow-2xl w-96 border-l-4 border-pmmg-accent">
                  <h4 className="text-lg font-bold mb-3 text-pmmg-primary">Cadastrar Novo Material</h4>
                  <div className="space-y-3">
                      <div>
                          <label className="text-sm font-bold text-gray-700">Nome do Material</label>
                          <input 
                              className="w-full border p-2 rounded focus:ring-2 focus:ring-pmmg-primary outline-none"
                              value={newMaterialData.name}
                              onChange={e => setNewMaterialData({...newMaterialData, name: e.target.value})}
                              autoFocus
                          />
                      </div>
                      <div>
                          <label className="text-sm font-bold text-gray-700">Unidade de Medida</label>
                          <input 
                              className="w-full border p-2 rounded focus:ring-2 focus:ring-pmmg-primary outline-none"
                              value={newMaterialData.unit}
                              onChange={e => setNewMaterialData({...newMaterialData, unit: e.target.value})}
                              placeholder="Ex: Unidade, Litros, Caixa, Kg..."
                          />
                      </div>
                      <div>
                          <label className="text-sm font-bold text-gray-700">Veículos Compatíveis <span className="text-gray-400 text-xs font-normal">(Opcional)</span></label>
                          <input 
                              className="w-full border p-2 rounded focus:ring-2 focus:ring-pmmg-primary outline-none"
                              value={newMaterialData.compatible_vehicles}
                              onChange={e => setNewMaterialData({...newMaterialData, compatible_vehicles: e.target.value})}
                              placeholder="Ex: L200, Palio, Duster..."
                          />
                      </div>
                      <div className="flex justify-end gap-2 mt-4">
                          <button 
                              onClick={() => setIsAddingMaterial(false)}
                              className="px-3 py-1 text-gray-600 hover:bg-gray-100 rounded"
                          >
                              Cancelar
                          </button>
                          <button 
                              onClick={handleSaveNewMaterial}
                              className="px-3 py-1 bg-pmmg-primary text-white rounded hover:bg-[#3E3223]"
                          >
                              Criar e Selecionar
                          </button>
                      </div>
                  </div>
              </div>
          </div>
      )}

      {(isAdding || isEditing) && (
        <div className="fixed inset-0 bg-black/60 backdrop-blur-sm flex items-center justify-center z-50 overflow-y-auto">
          <div className="bg-white p-6 rounded-lg w-full max-w-2xl shadow-xl my-8 border-t-4 border-pmmg-primary">
             <h3 className="text-xl font-bold mb-4 text-pmmg-primary">{isEditing ? 'Editar Movimentação' : 'Registrar Movimentação'}</h3>
             <p className="mb-4 text-sm text-gray-500">Ao salvar, o estoque será atualizado automaticamente.</p>

             <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                <div className="col-span-2">
                  <label className="block text-sm font-bold text-gray-700">Material <span className="text-red-500">*</span></label>
                  <div className="flex gap-2">
                    <select 
                        className="w-full border p-2 rounded mt-1 focus:ring-2 focus:ring-pmmg-primary outline-none"
                        value={formData.material_id}
                        onChange={e => setFormData({...formData, material_id: e.target.value})}
                    >
                        <option value="">Selecione um material...</option>
                        {materials.map(m => (
                        <option key={m.id} value={m.id}>{m.name} ({m.quantity} {m.unit || 'un'})</option>
                        ))}
                    </select>
                    <button 
                        onClick={() => setIsAddingMaterial(true)}
                        className="mt-1 px-4 py-2 bg-green-600 text-white rounded hover:bg-green-700 flex items-center gap-2 text-sm font-bold whitespace-nowrap shadow-sm transition-colors"
                        title="Criar novo material"
                    >
                        <PackagePlus size={16} />
                        Cadastrar Novo Material
                    </button>
                  </div>
                </div>

                <div>
                  <label className="block text-sm font-bold text-gray-700">Tipo <span className="text-red-500">*</span></label>
                  <select 
                     className="w-full border p-2 rounded mt-1 focus:ring-2 focus:ring-pmmg-primary outline-none"
                     value={formData.type}
                     onChange={e => setFormData({...formData, type: e.target.value as MovementType})}
                  >
                    <option value={MovementType.EXIT}>SAÍDA</option>
                    <option value={MovementType.ENTRY}>ENTRADA</option>
                  </select>
                </div>

                <div>
                  <label className="block text-sm font-bold text-gray-700">Quantidade <span className="text-red-500">*</span></label>
                  <input 
                    type="number" 
                    step="any"
                    className="w-full border p-2 rounded mt-1 focus:ring-2 focus:ring-pmmg-primary outline-none"
                    value={formData.quantity}
                    onChange={e => setFormData({...formData, quantity: Number(e.target.value)})}
                  />
                </div>

                <div>
                  <label className="block text-sm font-bold text-gray-700">Data <span className="text-red-500">*</span></label>
                  <input 
                    type="date" 
                    className="w-full border p-2 rounded mt-1 focus:ring-2 focus:ring-pmmg-primary outline-none"
                    value={formData.created_at}
                    onChange={e => setFormData({...formData, created_at: e.target.value})}
                  />
                </div>

                <div>
                  <label className="block text-sm font-bold text-gray-700">Nº Guia</label>
                  <input 
                    type="text" 
                    className="w-full border p-2 rounded mt-1 focus:ring-2 focus:ring-pmmg-primary outline-none"
                    placeholder="Ex: 12345 (Opcional)"
                    value={formData.guide_number}
                    onChange={e => setFormData({...formData, guide_number: e.target.value})}
                  />
                </div>

                <div>
                  <label className="block text-sm font-bold text-gray-700">
                      Responsável 
                      {formData.type === MovementType.EXIT && <span className="text-red-500"> *</span>}
                      {formData.type === MovementType.ENTRY && <span className="text-gray-400 font-normal text-xs ml-1">(Opcional na Entrada)</span>}
                  </label>
                  <input 
                    type="text" 
                    className="w-full border p-2 rounded mt-1 focus:ring-2 focus:ring-pmmg-primary outline-none"
                    placeholder="Nome do militar/funcionário"
                    value={formData.requester}
                    onChange={e => setFormData({...formData, requester: e.target.value})}
                  />
                </div>

                <div>
                  <label className="block text-sm font-bold text-gray-700">
                      Prefixo Viatura
                      {formData.type === MovementType.EXIT && <span className="text-red-500"> *</span>}
                      {formData.type === MovementType.ENTRY && <span className="text-gray-400 font-normal text-xs ml-1">(Opcional na Entrada)</span>}
                  </label>
                  <input 
                    type="text" 
                    className="w-full border p-2 rounded mt-1 focus:ring-2 focus:ring-pmmg-primary outline-none"
                    placeholder="Ex: VP-1234"
                    value={formData.vehicle_prefix}
                    onChange={e => setFormData({...formData, vehicle_prefix: e.target.value})}
                  />
                </div>

                <div className="col-span-2">
                    <label className="block text-sm font-bold text-gray-700">Observações</label>
                    <textarea 
                        className="w-full border p-2 rounded mt-1 focus:ring-2 focus:ring-pmmg-primary outline-none resize-none h-20"
                        placeholder="Motivo da correção ou detalhes adicionais..."
                        value={formData.observation || ''}
                        onChange={e => setFormData({...formData, observation: e.target.value})}
                    />
                </div>
             </div>

             <div className="flex justify-end gap-2 mt-6">
                <button 
                  onClick={() => { setIsEditing(null); setIsAdding(false); }}
                  className="px-4 py-2 text-gray-600 hover:bg-gray-100 rounded border transition-colors"
                >
                  Cancelar
                </button>
                <button 
                  onClick={handleSave}
                  className="px-4 py-2 bg-pmmg-primary text-white rounded hover:bg-[#3E3223] shadow-md transition-colors"
                >
                  Salvar
                </button>
             </div>
          </div>
        </div>
      )}

      <div className="bg-white rounded-lg shadow-md overflow-x-auto border border-gray-200">
        <table className="w-full text-left border-collapse min-w-[1000px]">
          <thead className="bg-gray-100 text-gray-700 select-none border-b-2 border-pmmg-primary/20">
            <tr>
              <th className="p-4 font-semibold border-b cursor-pointer hover:bg-gray-200" onClick={() => handleSort('created_at')}>
                <div className="flex items-center gap-1">Data {renderSortIcon('created_at')}</div>
              </th>
              <th className="p-4 font-semibold border-b text-center cursor-pointer hover:bg-gray-200" onClick={() => handleSort('type')}>
                <div className="flex items-center justify-center gap-1">Tipo {renderSortIcon('type')}</div>
              </th>
              <th className="p-4 font-semibold border-b cursor-pointer hover:bg-gray-200" onClick={() => handleSort('material_name')}>
                <div className="flex items-center gap-1">Material {renderSortIcon('material_name')}</div>
              </th>
              <th className="p-4 font-semibold border-b text-center cursor-pointer hover:bg-gray-200" onClick={() => handleSort('quantity')}>
                <div className="flex items-center justify-center gap-1">Qtd {renderSortIcon('quantity')}</div>
              </th>
              <th className="p-4 font-semibold border-b cursor-pointer hover:bg-gray-200" onClick={() => handleSort('requester')}>
                <div className="flex items-center gap-1">Responsável {renderSortIcon('requester')}</div>
              </th>
              <th className="p-4 font-semibold border-b cursor-pointer hover:bg-gray-200" onClick={() => handleSort('vehicle_prefix')}>
                <div className="flex items-center gap-1">Prefixo {renderSortIcon('vehicle_prefix')}</div>
              </th>
              <th className="p-4 font-semibold border-b cursor-pointer hover:bg-gray-200" onClick={() => handleSort('guide_number')}>
                <div className="flex items-center gap-1">Nº Guia {renderSortIcon('guide_number')}</div>
              </th>
              <th className="p-4 font-semibold border-b text-center">Obs</th>
              <th className="p-4 font-semibold border-b text-right">Ações</th>
            </tr>
          </thead>
          <tbody>
            {loading ? (
               <tr><td colSpan={9} className="p-8 text-center text-gray-500">Carregando histórico...</td></tr>
            ) : filteredMovements.length === 0 ? (
               <tr><td colSpan={9} className="p-8 text-center text-gray-500">Nenhuma movimentação encontrada.</td></tr>
            ) : (
              filteredMovements.map(m => (
                <tr key={m.id} className="border-b hover:bg-amber-50/50 transition-colors">
                  <td className="p-4 text-sm text-gray-700">
                    {m.created_at ? new Date(m.created_at).toLocaleDateString('pt-BR', { timeZone: 'UTC' }) : '-'}
                  </td>
                  <td className="p-4 text-center">
                    {m.type === MovementType.ENTRY ? (
                      <span className="inline-flex items-center gap-1 text-green-700 font-bold text-xs bg-green-100 px-2 py-1 rounded border border-green-200">
                        <ArrowUpCircle size={14} /> ENTRADA
                      </span>
                    ) : (
                      <span className="inline-flex items-center gap-1 text-red-700 font-bold text-xs bg-red-100 px-2 py-1 rounded border border-red-200">
                        <ArrowDownCircle size={14} /> SAÍDA
                      </span>
                    )}
                  </td>
                  <td className="p-4 font-medium text-gray-800">
                    {m.material_name} 
                    {/* Exibe unidade na tabela se disponível */}
                    {(m as any).material_unit && <span className="text-xs text-gray-500 ml-1">({(m as any).material_unit})</span>}
                  </td>
                  <td className="p-4 text-center font-mono font-bold">{m.quantity}</td>
                  <td className="p-4 text-sm text-gray-700">{m.requester || '-'}</td>
                  <td className="p-4 text-sm font-mono text-center w-fit text-gray-800">
                      {m.vehicle_prefix ? <span className="bg-gray-50 rounded px-2 py-1">{m.vehicle_prefix}</span> : '-'}
                  </td>
                  <td className="p-4 text-sm text-gray-500">{m.guide_number || '-'}</td>
                  <td className="p-4 text-center">
                      {m.observation ? (
                          <div className="group relative inline-block">
                              <MessageSquare size={18} className="text-blue-500 cursor-help" />
                              <div className="absolute bottom-full right-0 mb-2 w-48 p-2 bg-gray-800 text-white text-xs rounded hidden group-hover:block z-50 shadow-lg">
                                  {m.observation}
                              </div>
                          </div>
                      ) : '-'}
                  </td>
                  <td className="p-4 text-right">
                    <div className="flex justify-end gap-2">
                      <button 
                        onClick={() => { 
                          setIsEditing(m); 
                          setFormData({
                            material_id: m.material_id,
                            type: m.type,
                            quantity: m.quantity,
                            requester: m.requester || '',
                            vehicle_prefix: m.vehicle_prefix || '',
                            guide_number: m.guide_number,
                            observation: m.observation || '',
                            created_at: m.created_at ? new Date(m.created_at).toISOString().split('T')[0] : ''
                          });
                        }}
                        className="p-2 text-pmmg-primary hover:bg-pmmg-primary/10 rounded-full transition-colors"
                        title="Editar"
                      >
                        <Edit size={16} />
                      </button>
                      <button 
                        onClick={() => setDeletingId(m.id)}
                        className="p-2 text-red-600 hover:bg-red-50 rounded-full transition-colors"
                        title="Excluir"
                      >
                        <Trash2 size={16} />
                      </button>
                    </div>
                  </td>
                </tr>
              ))
            )}
          </tbody>
        </table>
      </div>
    </div>
  );
};

import React, { useEffect, useState } from 'react';
import { supabase } from '../lib/supabase';
import { Material } from '../types';
import { Edit, FileDown, FileUp, AlertTriangle, Search, ArrowUpDown, ArrowUp, ArrowDown, XCircle, Car } from 'lucide-react';
import { exportToExcel, parseExcel } from '../utils/excel';

type SortKey = 'name' | 'quantity' | 'status' | 'unit';

export const InventoryTab: React.FC = () => {
  const [materials, setMaterials] = useState<Material[]>([]);
  const [loading, setLoading] = useState(true);
  const [errorMsg, setErrorMsg] = useState<string | null>(null);
  const [filter, setFilter] = useState<'ALL' | 'LOW' | 'NONE' | 'NORMAL'>('ALL');
  const [search, setSearch] = useState('');

  // Configuração de ordenação
  const [sortConfig, setSortConfig] = useState<{ key: SortKey; direction: 'ASC' | 'DESC' }>({ 
    key: 'name', 
    direction: 'ASC' 
  });

  const [isEditing, setIsEditing] = useState<Material | null>(null);

  // Form states
  const [formData, setFormData] = useState<Partial<Material>>({ 
      name: '', 
      quantity: 0, 
      unit: 'Unidade',
      compatible_vehicles: '' 
  });

  const fetchMaterials = async () => {
    setLoading(true);
    setErrorMsg(null);
    try {
      const { data, error } = await supabase
        .from('materials')
        .select('*');

      if (error) throw error;
      setMaterials(data || []);
    } catch (err: any) {
      console.error('Erro ao buscar materiais:', err);
      setErrorMsg(err.message || JSON.stringify(err));
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchMaterials();
  }, []);

  const handleSave = async () => {
    if (!formData.name) return;

    // Bloqueia inserção manual por aqui, permite apenas edição
    if (!isEditing || !isEditing.id) return;

    try {
      // Atualiza nome, unidade e veículos compatíveis. Quantidade é via Movimentações.
      const { error } = await supabase
        .from('materials')
        .update({ 
          name: formData.name, 
          unit: formData.unit,
          compatible_vehicles: formData.compatible_vehicles
        })
        .eq('id', isEditing.id);

      if (error) throw error;

      setIsEditing(null);
      setFormData({ name: '', quantity: 0, unit: 'Unidade', compatible_vehicles: '' });
      fetchMaterials();
    } catch (err: any) {
      alert(`Erro ao salvar: ${err.message || JSON.stringify(err)}`);
    }
  };

  const handleImport = async (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      try {
        const data = await parseExcel(e.target.files[0]);

        // Função auxiliar para buscar chave ignorando maiúsculas/minúsculas
        const findValue = (row: any, searchKeys: string[]) => {
            const objectKeys = Object.keys(row);
            for (const searchKey of searchKeys) {
                const foundKey = objectKeys.find(k => k.toLowerCase().trim() === searchKey.toLowerCase());
                if (foundKey) return row[foundKey];
            }
            return undefined;
        };

        const formattedData = data.map((row: any) => ({
          name: findValue(row, ['material', 'nome', 'name', 'item', 'descricao']),
          quantity: Number(findValue(row, ['quantidade', 'qtd', 'quantity', 'saldo', 'quant']) || 0),
          unit: findValue(row, ['unidade', 'medida', 'unit', 'und', 'tipo']) || 'Unidade',
          compatible_vehicles: findValue(row, ['compatibilidade', 'veiculos', 'compativel']) || ''
        })).filter(r => r.name); // Filtra linhas que tenham pelo menos nome

        if (formattedData.length > 0) {
          const { error } = await supabase.from('materials').insert(formattedData);
          if (error) throw error;
          alert(`${formattedData.length} itens importados com sucesso!`);
          fetchMaterials();
        } else {
          alert("Nenhum material encontrado no arquivo. Verifique se as colunas chamam 'Material' e 'Quantidade'.");
        }
      } catch (err: any) {
        alert(`Erro ao importar: ${err.message || 'Verifique o formato do arquivo.'}`);
        console.error(err);
      }
    }
  };

  const getStatus = (m: Material) => {
    if (m.quantity <= 0) return 'NONE';
    if (m.quantity < 5) return 'LOW'; 
    return 'NORMAL';
  };

  const handleSort = (key: SortKey) => {
    let direction: 'ASC' | 'DESC' = 'ASC';
    if (sortConfig.key === key && sortConfig.direction === 'ASC') {
      direction = 'DESC';
    }
    setSortConfig({ key, direction });
  };

  const renderSortIcon = (key: SortKey) => {
    if (sortConfig.key !== key) return <ArrowUpDown size={14} className="text-gray-400 opacity-50" />;
    return sortConfig.direction === 'ASC' 
      ? <ArrowUp size={14} className="text-pmmg-primary" /> 
      : <ArrowDown size={14} className="text-pmmg-primary" />;
  };

  const filteredMaterials = materials
    .filter(m => {
      const status = getStatus(m);
      const matchesFilter = filter === 'ALL' || status === filter;
      const matchesSearch = 
        m.name.toLowerCase().includes(search.toLowerCase()) || 
        (m.compatible_vehicles || '').toLowerCase().includes(search.toLowerCase());
      return matchesFilter && matchesSearch;
    })
    .sort((a, b) => {
      let valA: any = a[sortConfig.key as keyof Material];
      let valB: any = b[sortConfig.key as keyof Material];

      if (sortConfig.key === 'status') {
         const weight = (m: Material) => {
             const s = getStatus(m);
             if (s === 'NONE') return 0;
             if (s === 'LOW') return 1;
             return 2;
         };
         valA = weight(a);
         valB = weight(b);
      } 
      else if (sortConfig.key === 'name' || sortConfig.key === 'unit') {
         valA = (valA || '').toLowerCase();
         valB = (valB || '').toLowerCase();
      }

      if (valA < valB) return sortConfig.direction === 'ASC' ? -1 : 1;
      if (valA > valB) return sortConfig.direction === 'ASC' ? 1 : -1;
      return 0;
    });

  return (
    <div className="space-y-6">
      <div className="flex flex-col xl:flex-row justify-between items-center gap-4 bg-white p-4 rounded-lg shadow-sm border-l-4 border-pmmg-primary">
        <div className="flex flex-col md:flex-row items-center gap-2 w-full xl:w-auto">
          <div className="relative w-full md:w-64">
            <Search className="absolute left-2 top-2.5 h-4 w-4 text-gray-400" />
            <input
              type="text"
              placeholder="Buscar material ou veículo compatível..."
              className="pl-8 pr-4 py-2 border rounded-md w-full focus:ring-2 focus:ring-pmmg-primary outline-none"
              value={search}
              onChange={e => setSearch(e.target.value)}
            />
          </div>
          <div className="flex gap-2 w-full md:w-auto">
            <select 
              className="border p-2 rounded-md flex-1 md:flex-none focus:ring-2 focus:ring-pmmg-primary outline-none"
              value={filter}
              onChange={(e: any) => setFilter(e.target.value)}
            >
              <option value="ALL">Todos os Status</option>
              <option value="NORMAL">Estoque Normal</option>
              <option value="LOW">Estoque Baixo</option>
              <option value="NONE">Sem Estoque</option>
            </select>
          </div>
        </div>

        <div className="flex gap-2 w-full xl:w-auto justify-end">
          <label className="flex items-center gap-2 px-3 py-2 bg-pmmg-success text-white rounded-md cursor-pointer hover:bg-green-800 transition-colors shadow-sm">
            <FileUp size={16} /> <span className="hidden sm:inline">Importar Excel</span>
            <input type="file" accept=".xlsx, .xls, .csv" className="hidden" onChange={handleImport} />
          </label>
          <button 
            onClick={() => exportToExcel(materials, 'Estoque_Frota_5RPM')}
            className="flex items-center gap-2 px-3 py-2 bg-gray-600 text-white rounded-md hover:bg-gray-700 transition-colors shadow-sm"
          >
            <FileDown size={16} /> <span className="hidden sm:inline">Exportar Excel</span>
          </button>
        </div>
      </div>

      {errorMsg && (
        <div className="bg-red-50 text-red-700 p-4 rounded-lg flex items-center gap-2 border border-red-200">
          <XCircle size={20} />
          <span>Erro: {errorMsg}</span>
        </div>
      )}

      {isEditing && (
        <div className="fixed inset-0 bg-black/60 backdrop-blur-sm flex items-center justify-center z-50">
          <div className="bg-white p-6 rounded-lg w-full max-w-md shadow-2xl border-t-4 border-pmmg-primary">
            <h3 className="text-xl font-bold mb-4 text-pmmg-primary">Editar Material</h3>
            <div className="space-y-4">
              <div>
                <label className="block text-sm font-bold text-gray-700 mb-1">Nome do Material</label>
                <input 
                  type="text" 
                  className="w-full border p-2 rounded focus:ring-2 focus:ring-pmmg-primary outline-none" 
                  value={formData.name} 
                  onChange={e => setFormData({...formData, name: e.target.value})}
                  autoFocus
                />
              </div>
              <div>
                <label className="block text-sm font-bold text-gray-700 mb-1">Unidade de Medida</label>
                <input 
                  type="text" 
                  className="w-full border p-2 rounded focus:ring-2 focus:ring-pmmg-primary outline-none" 
                  value={formData.unit} 
                  onChange={e => setFormData({...formData, unit: e.target.value})}
                  placeholder="Ex: Unidade, Litros, Caixa, Kg..."
                />
              </div>

              {/* CAMPO DE VEÍCULOS COMPATÍVEIS */}
              <div>
                <label className="block text-sm font-bold text-gray-700 mb-1">Veículos Compatíveis (Opcional)</label>
                <input 
                  type="text" 
                  className="w-full border p-2 rounded focus:ring-2 focus:ring-pmmg-primary outline-none" 
                  value={formData.compatible_vehicles || ''} 
                  onChange={e => setFormData({...formData, compatible_vehicles: e.target.value})}
                  placeholder="Ex: L200, Duster, Palio..."
                />
              </div>

              <div>
                <label className="block text-sm font-bold text-gray-700 mb-1">
                  Quantidade
                  <span className="text-xs text-red-500 ml-2 font-normal">(Bloqueado na edição)</span>
                </label>
                <input 
                  type="number" 
                  step="any"
                  className="w-full border p-2 rounded bg-gray-100 text-gray-500 cursor-not-allowed"
                  value={formData.quantity} 
                  disabled={true} 
                />
                <p className="text-xs text-gray-500 mt-1">Para alterar a quantidade, realize uma Movimentação (Entrada/Saída).</p>
              </div>
            </div>
            <div className="flex justify-end gap-2 mt-6">
              <button 
                onClick={() => { setIsEditing(null); }}
                className="px-4 py-2 text-gray-600 hover:bg-gray-100 rounded border transition-colors"
              >
                Cancelar
              </button>
              <button 
                onClick={handleSave}
                className="px-4 py-2 bg-pmmg-primary text-white rounded hover:bg-[#3E3223] shadow-md transition-colors"
              >
                Salvar
              </button>
            </div>
          </div>
        </div>
      )}

      <div className="bg-white rounded-lg shadow-md overflow-hidden border border-gray-200">
        <table className="w-full text-left border-collapse">
          <thead className="bg-gray-100 text-gray-700 select-none border-b-2 border-pmmg-primary/20">
            <tr>
              <th 
                className="p-4 font-semibold border-b cursor-pointer hover:bg-gray-200 transition-colors"
                onClick={() => handleSort('name')}
              >
                <div className="flex items-center gap-1">Material {renderSortIcon('name')}</div>
              </th>
              <th 
                className="p-4 font-semibold border-b text-center w-32 cursor-pointer hover:bg-gray-200 transition-colors"
                onClick={() => handleSort('quantity')}
              >
                 <div className="flex items-center justify-center gap-1">Qtd {renderSortIcon('quantity')}</div>
              </th>
              <th 
                className="p-4 font-semibold border-b text-center cursor-pointer hover:bg-gray-200 transition-colors"
                onClick={() => handleSort('unit')}
              >
                <div className="flex items-center justify-center gap-1">Unidade {renderSortIcon('unit')}</div>
              </th>
              <th 
                className="p-4 font-semibold border-b text-center w-40 cursor-pointer hover:bg-gray-200 transition-colors"
                onClick={() => handleSort('status')}
              >
                 <div className="flex items-center justify-center gap-1">Status {renderSortIcon('status')}</div>
              </th>
              <th className="p-4 font-semibold border-b text-right w-24">Ações</th>
            </tr>
          </thead>
          <tbody>
            {loading ? (
              <tr><td colSpan={5} className="p-8 text-center text-gray-500">Carregando estoque...</td></tr>
            ) : filteredMaterials.length === 0 ? (
              <tr><td colSpan={5} className="p-8 text-center text-gray-500">Nenhum material encontrado.</td></tr>
            ) : (
              filteredMaterials.map(item => {
                const status = getStatus(item);
                return (
                  <tr key={item.id} className="border-b hover:bg-amber-50/50 transition-colors">
                    <td className="p-4 font-medium text-gray-800">
                        <div>{item.name}</div>
                        {/* Exibe Veículos Compatíveis na Tabela se houver */}
                        {item.compatible_vehicles && (
                            <div className="text-xs text-gray-500 mt-1 flex items-center gap-1">
                                <Car size={12} className="text-pmmg-accent" /> 
                                <span className="font-semibold text-gray-600">Compatível:</span> {item.compatible_vehicles}
                            </div>
                        )}
                    </td>
                    <td className="p-4 text-center font-mono text-lg font-bold text-gray-700">{item.quantity}</td>
                    <td className="p-4 text-center text-gray-600 text-sm">{item.unit || '-'}</td>
                    <td className="p-4 text-center">
                      {status === 'NONE' && (
                        <span className="inline-flex items-center gap-1 px-3 py-1 rounded-full text-xs font-bold bg-red-100 text-red-800 border border-red-200">
                          <AlertTriangle size={12} /> SEM ESTOQUE
                        </span>
                      )}
                      {status === 'LOW' && (
                        <span className="inline-flex items-center gap-1 px-3 py-1 rounded-full text-xs font-bold bg-yellow-100 text-yellow-800 border border-yellow-200">
                          <AlertTriangle size={12} /> BAIXO
                        </span>
                      )}
                      {status === 'NORMAL' && (
                        <span className="inline-flex items-center gap-1 px-3 py-1 rounded-full text-xs font-bold bg-green-100 text-green-800 border border-green-200">
                          NORMAL
                        </span>
                      )}
                    </td>
                    <td className="p-4 text-right">
                      <div className="flex justify-end gap-2">
                        <button 
                          onClick={() => { setIsEditing(item); setFormData({ ...item, compatible_vehicles: item.compatible_vehicles || '' }); }}
                          className="p-2 text-pmmg-primary hover:bg-pmmg-primary/10 rounded-full transition-colors"
                          title="Editar"
                        >
                          <Edit size={18} />
                        </button>
                      </div>
                    </td>
                  </tr>
                );
              })
            )}
          </tbody>
        </table>
      </div>
    </div>
  );
};

