Aqui está o script SQL completo e atualizado para ser executado no **SQL Editor** do seu projeto no Supabase. 

Este script já contempla as atualizações mais recentes, como o suporte a **valores fracionados (decimais)** no estoque e as tabelas para todos os módulos (PAV, Agenda, Substituição e Estoque).

```sql
-- =========================================================
-- SCRIPT DE CONFIGURAÇÃO INTEGRADO - v7
-- Suporte a decimais, Agenda, PAV e Substituição de Frota
-- =========================================================

-- 1. HABILITAR EXTENSÃO DE CRIPTOGRAFIA
CREATE EXTENSION IF NOT EXISTS pgcrypto;

-- 2. TABELA DE PERFIS (Vinculada ao Auth do Supabase)
CREATE TABLE IF NOT EXISTS public.profiles (
    id UUID REFERENCES auth.users ON DELETE CASCADE PRIMARY KEY,
    pm_number TEXT UNIQUE NOT NULL,
    email TEXT NOT NULL,
    full_name TEXT,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT timezone('utc'::text, now()) NOT NULL
);

ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "Public Read Profiles" ON public.profiles;
CREATE POLICY "Public Read Profiles" ON public.profiles FOR SELECT USING (true);
DROP POLICY IF EXISTS "Users Insert Self" ON public.profiles;
CREATE POLICY "Users Insert Self" ON public.profiles FOR INSERT WITH CHECK (auth.uid() = id);
DROP POLICY IF EXISTS "Users Update Self" ON public.profiles;
CREATE POLICY "Users Update Self" ON public.profiles FOR UPDATE USING (auth.uid() = id);

-- 3. GATILHO PARA CRIAR PERFIL AUTOMATICAMENTE NO CADASTRO
CREATE OR REPLACE FUNCTION public.handle_new_user()
RETURNS TRIGGER AS $$
BEGIN
  INSERT INTO public.profiles (id, pm_number, email, full_name)
  VALUES (
    new.id,
    new.raw_user_meta_data->>'pm_number',
    new.email,
    new.raw_user_meta_data->>'full_name'
  )
  ON CONFLICT (id) DO NOTHING;
  RETURN new;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

DROP TRIGGER IF EXISTS on_auth_user_created ON auth.users;
CREATE TRIGGER on_auth_user_created
  AFTER INSERT ON auth.users
  FOR EACH ROW EXECUTE FUNCTION public.handle_new_user();

-- 4. FUNÇÃO PARA REDEFINIÇÃO DE SENHA VIA Nº PM (RPC)
CREATE OR REPLACE FUNCTION public.reset_password_via_pm(
    target_pm text, 
    new_password text, 
    secret_code text
)
RETURNS text
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
  target_user_id uuid;
BEGIN
  IF secret_code <> 'FROTA5RPM' THEN
     RAISE EXCEPTION 'Código Mestre da Seção incorreto.';
  END IF;
  IF length(new_password) < 6 THEN
     RAISE EXCEPTION 'A senha deve ter no mínimo 6 caracteres.';
  END IF;
  SELECT id INTO target_user_id FROM public.profiles WHERE pm_number = target_pm;
  IF target_user_id IS NULL THEN
     RAISE EXCEPTION 'Nº PM não encontrado no sistema.';
  END IF;
  UPDATE auth.users
  SET encrypted_password = crypt(new_password, gen_salt('bf')),
      updated_at = now()
  WHERE id = target_user_id;
  RETURN 'Senha alterada com sucesso!';
END;
$$;

-- 5. TABELAS DO SISTEMA

-- Materiais (Estoque)
CREATE TABLE IF NOT EXISTS public.materials (
    id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
    name TEXT NOT NULL,
    quantity NUMERIC DEFAULT 0, -- NUMERIC permite decimais
    unit TEXT DEFAULT 'Unidade',
    compatible_vehicles TEXT,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT timezone('utc'::text, now()) NOT NULL
);

-- Viaturas (Frota Disponível)
CREATE TABLE IF NOT EXISTS public.vehicles (
    id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
    prefix TEXT NOT NULL,
    plate TEXT,
    model TEXT,
    fraction TEXT,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT timezone('utc'::text, now()) NOT NULL
);

-- Movimentações (Entradas e Saídas)
CREATE TABLE IF NOT EXISTS public.movements (
    id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
    material_id UUID REFERENCES public.materials(id) ON DELETE CASCADE,
    type TEXT NOT NULL, -- 'ENTRADA' ou 'SAIDA'
    quantity NUMERIC NOT NULL,
    requester TEXT,
    vehicle_prefix TEXT,
    guide_number TEXT,
    observation TEXT,
    created_at DATE DEFAULT CURRENT_DATE NOT NULL
);

-- Processos PAV
CREATE TABLE IF NOT EXISTS public.pav_processes (
    id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
    fraction TEXT,
    vehicle_prefix TEXT,
    vehicle_plate TEXT,
    accident_date DATE,
    reds_number TEXT,
    pav_number TEXT,
    inquirer TEXT,
    sent_to_inquirer BOOLEAN DEFAULT FALSE,
    os_request_date DATE,
    os_number TEXT,
    os_followup_date DATE,
    observations TEXT,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT timezone('utc'::text, now()) NOT NULL
);

-- Agenda de Viaturas
CREATE TABLE IF NOT EXISTS public.vehicle_schedules (
    id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
    vehicle_prefix TEXT NOT NULL,
    driver_name TEXT NOT NULL,
    reason TEXT NOT NULL,
    start_time TIMESTAMP WITH TIME ZONE NOT NULL,
    end_time TIMESTAMP WITH TIME ZONE NOT NULL,
    observations TEXT,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT timezone('utc'::text, now()) NOT NULL
);

-- Substituição de Frota
CREATE TABLE IF NOT EXISTS public.fleet_substitutions (
    id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
    received_prefix TEXT NOT NULL,
    received_plate TEXT NOT NULL,
    received_model TEXT,
    received_bgpm TEXT,
    received_city TEXT,
    received_unit TEXT,
    indicated_prefix TEXT,
    indicated_plate TEXT,
    not_required BOOLEAN DEFAULT FALSE,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT timezone('utc'::text, now()) NOT NULL
);

-- 6. MIGRAÇÕES DE TIPO (Caso você já tenha as tabelas criadas como Integer)
ALTER TABLE public.materials ALTER COLUMN quantity TYPE NUMERIC;
ALTER TABLE public.movements ALTER COLUMN quantity TYPE NUMERIC;

-- 7. POLÍTICAS DE ACESSO (RLS - Permite que usuários logados operem os dados)
ALTER TABLE public.materials ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.vehicles ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.movements ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.pav_processes ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.vehicle_schedules ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.fleet_substitutions ENABLE ROW LEVEL SECURITY;

CREATE POLICY "Acesso Total" ON public.materials FOR ALL USING (true) WITH CHECK (true);
CREATE POLICY "Acesso Total" ON public.vehicles FOR ALL USING (true) WITH CHECK (true);
CREATE POLICY "Acesso Total" ON public.movements FOR ALL USING (true) WITH CHECK (true);
CREATE POLICY "Acesso Total" ON public.pav_processes FOR ALL USING (true) WITH CHECK (true);
CREATE POLICY "Acesso Total" ON public.vehicle_schedules FOR ALL USING (true) WITH CHECK (true);
