                                    <div className="text-xs text-gray-500 font-bold font-mono">Nº PM: {formatPmNumber(p.inquirer_pm_number || '')}</div>
                                    {p.pav_number ? (
                                        <div className="text-lg font-bold font-mono text-[#3E3223] mt-1">{p.pav_number}</div>
