                                </td>
                                <td className="p-3 border-r">
                                    {p.os_number ? (
                                        <>
                                            <div className="font-bold text-lg text-blue-800">{p.os_number}</div>
                                            <div className="text-xs text-gray-600 font-medium">1ª Solic: {formatDate(p.os_request_date)}</div>
                                            {p.os_followup_date && (
