                                    <div>
                                        <label className="block text-xs font-bold text-gray-700 uppercase mb-1">Placa <span className="text-red-500">*</span></label>
                                        <input 
                                            className={getInputClass('vehicle_plate')}
                                            value={formData.vehicle_plate}
                                            onChange={e => {
